/// A condition a decision's tests saw both ways but never alone deciding it
/// is said to be that, and one never seen true is said to be that.
#[test]
fn a_decision_names_a_condition_seen_both_ways_that_never_decided_alone() {
    let project = Project::empty("masked-condition");
    project.write(
        "package.json",
        r#"{ "name": "masked", "private": true, "type": "module" }"#,
    );
    project.write(
        "src/a.js",
        "export function f(a, b) {\n  if (a && b) return 1;\n  return 2;\n}\n",
    );
    project.write(
        "test/a.test.js",
        "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { f } from '../src/a.js';\ntest('tf', () => assert.equal(f(true, false), 2));\ntest('ff', () => assert.equal(f(false, false), 2));\n",
    );
    project.git(&["init", "-q"]);
    project.measure(&[]);
    contains_all(
        &project
            .supercov(&["runs", "latest", "decision", "src/a.js:2"])
            .succeeds(),
        &[
            "C1 MISSING: a (seen both ways, never deciding alone)",
            "C2 MISSING: b (never true)",
        ],
    );
}

#[test]
fn bun_native_callback_arity_is_preserved_inside_describe() {
    if !bun_is_available() {
        return;
    }
    let project = bun_project("bun-arity-probe", false);
    project.write(
        "src/clamp.test.ts",
        r#"import { test, describe } from 'bun:test';
const run = test.concurrent ?? test;
const callback = async () => { await new Promise(r => setTimeout(r, 1)); };
function wrapped() { return Reflect.apply(callback, this, arguments); }
Object.defineProperty(wrapped, 'length', {value:0});
describe('group', () => { run('wrapped', wrapped); });
"#,
    );
    let native = std::process::Command::new("bun")
        .args(["test"])
        .current_dir(&project.root)
        .output()
        .unwrap();
    assert!(
        native.status.success(),
        "native Bun: {}",
        String::from_utf8_lossy(&native.stderr)
    );
    let adapter = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../runtime/javascript/bunTest.mjs");
    let adapted = std::process::Command::new("bun")
        .args(["test", "--preload"])
        .arg(adapter)
        .current_dir(&project.root)
        .output()
        .unwrap();
    assert!(
        adapted.status.success(),
        "adapted Bun: {}",
        String::from_utf8_lossy(&adapted.stderr)
    );
}

/// An Ant build is read before it runs: what it compiles is its product code,
/// what it writes into is not, and `SUPERCOV_TEST_ROOTS` says where its tests
/// are when its own words cannot. A stand-in for Ant shows what Supercov
/// decided without needing one: it runs no task, so it records nothing, and
/// the run says what an Ant build has to reach.
#[cfg(unix)]
#[test]
fn an_ant_build_is_read_before_it_runs() {
    let project = Project::empty("ant-read");
    project.write(
        "build.xml",
        r#"<project default="test"><target name="test"><javac srcdir="src" destdir="classes"/><junit><batchtest><fileset dir="checks"/></batchtest></junit></target></project>"#,
    );
    project.write(
        "src/app/Calc.java",
        "package app;\npublic class Calc { public static int twice(int x) { return 2 * x; } }\n",
    );
    project.write(
        "checks/app/CalcTest.java",
        "package app;\npublic class CalcTest {}\n",
    );
    // Java the build compiled into place earlier is output, not source.
    project.write("classes/app/Stale.java", "package app;\nclass Stale {}\n");
    // A file whose package is not where it sits says nothing of its root.
    project.write(
        "src/misplaced/Odd.java",
        "package elsewhere;\nclass Odd {}\n",
    );
    project.write_script("ant", "#!/bin/sh\nexit 0\n");
    project.write_script("ant.bat", "#!/bin/sh\nexit 0\n");

    let ran = project.supercov(&["--", "./ant", "test"]);
    let stderr = ran.stderr();
    assert_ne!(ran.code(), 0, "{stderr}");
    contains_all(
        &stderr,
        &[
            "instrumenting 2 source file(s)",
            "An Ant build reports through its <junit>, <junitlauncher> and <testng> tasks",
        ],
    );
    // A blank override is no override.
    let blank = project.supercov_with(&["--", "./ant", "test"], &[("SUPERCOV_TEST_ROOTS", " ")]);
    assert!(
        blank.stderr().contains("instrumenting 2 source file(s)"),
        "{}",
        blank.stderr()
    );
    // Named as tests, the product code leaves nothing to measure.
    let named = project.supercov_with(&["--", "./ant", "test"], &[("SUPERCOV_TEST_ROOTS", "src")]);
    assert!(
        named
            .stderr()
            .contains("no source root of this Ant build holds product code"),
        "{}",
        named.stderr()
    );

    // A build that runs its tests through none of the tasks Supercov reads
    // leaves them unattributed, and says so in Ant's terms.
    project.write(
        "build.xml",
        r#"<project default="test"><target name="test"><javac srcdir="src" destdir="classes"/><java classname="Runner"/></target></project>"#,
    );
    let untasked = project.supercov_with(
        &["--", "./ant", "test"],
        &[("SUPERCOV_TEST_ROOTS", "checks")],
    );
    contains_all(
        &untasked.stderr(),
        &["through no <junit>, <junitlauncher> or <testng> task Supercov can find"],
    );
    assert!(
        !untasked.stderr().contains("junit-vintage-engine"),
        "{}",
        untasked.stderr()
    );
    // Without tests to run there is nothing left unattributed to mention.
    let testless = project.supercov_with(
        &["--", "./ant", "test"],
        &[("SUPERCOV_TEST_ROOTS", "nothing")],
    );
    let stderr = testless.stderr();
    assert!(
        stderr.contains("instrumenting 2 source file(s)"),
        "{stderr}"
    );
    assert!(!stderr.contains("Supercov can find"), "{stderr}");

    // A build file holding Supercov's own changes is one an earlier run left,
    // and patching it again would run that run's compilation.
    for leftover in [
        r#"<formatter classname="com.supercorp.supercov.SupercovAntFormatter"/>"#,
        r#"<listener classname="com.supercorp.supercov.SupercovListener"/>"#,
        r#"<testng listeners="com.supercorp.supercov.SupercovTestNGListener"/>"#,
    ] {
        project.write(
            "build.xml",
            &format!(r#"<project default="test"><target name="test"><junit>{leftover}<batchtest><fileset dir="checks"/></batchtest></junit></target></project>"#),
        );
        let left = project.supercov(&["--", "./ant", "test"]);
        assert!(
            left.stderr()
                .contains("still holds an earlier run's changes"),
            "{leftover}: {}",
            left.stderr()
        );
    }

    // Ant run on another build file is refused: the build Supercov reads is
    // the one where it runs.
    project.write("sub/build.xml", "<project/>");
    let elsewhere = project.supercov(&["--", "./ant.bat", "-f", "sub/build.xml"]);
    assert_ne!(elsewhere.code(), 0, "{}", elsewhere.stderr());
    assert!(
        elsewhere
            .stderr()
            .contains("run Supercov from that file's directory"),
        "{}",
        elsewhere.stderr()
    );
}

/// A process the suite starts that a crash signal ends says nothing of it:
/// on 2026-11-06 a backend that died so right after it listened read as one
/// that never became ready. The run names it, and a child its test stops
/// with SIGTERM is not named.
#[cfg(unix)]
#[test]
fn a_child_a_crash_signal_ends_is_named() {
    let project = Project::cart("crashed-child");
    project.write(
        "test/server.test.js",
        r#"import { test } from "node:test";
import { spawn, spawnSync } from "node:child_process";

test("the helper server crashes, the test does not", () => {
  spawnSync(process.execPath, ["-e", "process.kill(process.pid, 'SIGSEGV')"]);
});

test("a server the test stops is not a crash", async () => {
  const server = spawn(process.execPath, ["-e", "setInterval(() => {}, 1000)"]);
  server.kill("SIGTERM");
  await new Promise((done) => server.once("exit", done));
});
"#,
    );
    project.commit("a crashing helper");
    let measured = project.supercov(&["--", "node", "--test"]);
    let output = measured.exits(0);
    let named: Vec<&str> = output
        .lines()
        .filter(|line| line.contains("crashed with"))
        .collect();
    assert_eq!(named.len(), 1, "{output}");
    contains_all(
        named[0],
        &[
            "[supercov] warning:",
            "crashed with SIGSEGV",
            "s after it started",
        ],
    );
    assert!(!output.contains("SIGTERM"), "{output}");
}

/// A mocha project whose tests leave a boundary unhit and a function
/// uncalled, with node_modules from the repository.
#[cfg(unix)]
fn mutants_project(label: &str) -> Project {
    let project = Project::empty(label);
    project.write(
        "package.json",
        r#"{ "name": "mutants", "type": "module", "scripts": { "test": "mocha" } }"#,
    );
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n");
    project.write(
        "src/cart.js",
        "export function shipping(sum) {\n  if (sum >= 50) {\n    return 0;\n  }\n  return 5;\n}\n\nexport function label(name) {\n  return name.trim().toUpperCase();\n}\n\nexport function refund(sum) {\n  return sum > 100 ? sum * 0.9 : sum;\n}\n",
    );
    project.write(
        "test/cart.test.js",
        "import assert from \"node:assert/strict\";\nimport { shipping, label } from \"../src/cart.js\";\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => assert.equal(shipping(80), 0));\n  it(\"charges small orders\", () => assert.equal(shipping(10), 5));\n  it(\"labels\", () => assert.equal(label(\" a \"), \"A\"));\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("mutants");
    project
}

/// Each mutant's status in a `mutants --json` reply, by id.
#[cfg(unix)]
fn mutant_statuses(reply: &serde_json::Value) -> std::collections::BTreeMap<String, String> {
    reply["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .map(|mutant| {
            (
                mutant["id"].as_str().unwrap().to_owned(),
                mutant["status"].as_str().unwrap().to_owned(),
            )
        })
        .collect()
}

/// `mutants --diff`: only the mutants on lines a change added or modified
/// since it left a base, the tests' survivors first, as a pull request's
/// comment, and as a gate.
#[cfg(unix)]
#[test]
fn mutants_on_a_change_are_those_on_its_lines() {
    let project = mutants_project("mutants-diff");
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.commit("ignore the runs");
    project.git(&["branch", "base"]);
    // The change: a new module and its test, and one line of the old one.
    project.write(
        "src/tax.js",
        "export function tax(sum) {\n  return sum >= 10 ? sum * 0.2 : 0;\n}\n",
    );
    project.write(
        "test/tax.test.js",
        "import assert from \"node:assert/strict\";\nimport { tax } from \"../src/tax.js\";\nit(\"taxes\", () => assert.equal(tax(20), 4));\n",
    );
    project.edit("src/cart.js", "return 5;", "return 6;");
    project.edit("test/cart.test.js", "shipping(10), 5", "shipping(10), 6");
    project.commit("tax");
    let head = project.git(&["rev-parse", "HEAD"]).trim().to_owned();
    let merge_base = project.git(&["rev-parse", "base"]).trim().to_owned();
    project
        .supercov_with(&["--", "npx", "mocha"], &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();

    let reply = project
        .supercov(&[
            "runs", "latest", "mutants", "--diff", "base", "--json", "--limit", "0",
        ])
        .json();
    let data = &reply["data"];
    assert_eq!(data["diff"]["base"], "base");
    assert_eq!(data["diff"]["mergeBase"], merge_base.as_str());
    assert_eq!(data["diff"]["commit"], head.as_str());
    // tax.js's three lines, and cart.js's changed `return`, whose only
    // mutant is the body around it, emptied.
    assert_eq!(data["diff"]["changedLines"], 4, "{data}");
    assert_eq!(data["diff"]["linesWithMutants"], 4, "{data}");
    let mutants = data["mutants"].as_array().unwrap();
    assert!(!mutants.is_empty());
    assert!(
        mutants.iter().all(|mutant| mutant["file"] == "src/tax.js"
            || mutant["id"].as_str().is_some_and(
                |id| id.starts_with("src/cart.js:1:") && id.ends_with("-6:2:BlockStatement:{}")
            )),
        "{data}"
    );
    // The survivors first: `sum` was 20, never 10.
    assert_eq!(mutants[0]["status"], "not-infected", "{data}");
    assert!(
        mutants.iter().any(
            |mutant| mutant["id"] == "src/tax.js:2:10-2:19:EqualityOperator:>"
                && mutant["status"] == "not-infected"
        ),
        "{data}"
    );
    let ranks = mutants
        .iter()
        .map(|mutant| match mutant["status"].as_str() {
            Some("not-infected") => 0,
            Some("not-reached") => 1,
            _ => 2,
        })
        .collect::<Vec<_>>();
    assert!(ranks.is_sorted(), "{data}");
    assert_eq!(data["summary"]["mutants"], mutants.len());

    let human = project
        .supercov(&["runs", "latest", "mutants", "--diff", "base"])
        .succeeds();
    contains_all(
        &human,
        &[
            "Change       ",
            "(where it left base)",
            "Lines        4 added or changed, 4 with mutants",
            "Not infected",
            "src/tax.js:2:10",
            "sum >= 10 → sum > 10",
            "why: `sum` never equal to `10`",
            "Not listed: ",
            "--diff 'base' --status infected",
        ],
    );
    assert!(!human.contains("src/cart.js:"), "{human}");

    let markdown = project
        .supercov(&[
            "runs", "latest", "mutants", "--diff", "base", "--format", "markdown",
        ])
        .succeeds();
    contains_all(
        &markdown,
        &[
            "### Mutants on this change",
            "on 4 of 4 changed lines since `base`",
            "| Where | Mutant | Status | Tests on its line | Why |",
            "| `src/tax.js:2:10` | `sum >= 10 → sum > 10` | not infected | 1 | `sum` never equal to `10` |",
        ],
    );

    // A gate: a mutant the tests leave alive on the change fails it.
    let failed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--diff",
            "base",
            "--fail-on",
            "not-infected,not-reached",
        ])
        .exits(1);
    assert!(
        failed.contains("FAILED --fail-on not-infected,not-reached"),
        "{failed}"
    );
    project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--diff",
            "base",
            "--fail-on",
            "equivalent",
        ])
        .succeeds();
    project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--diff",
            "base",
            "--format",
            "markdown",
            "--fail-on",
            "not-infected",
        ])
        .exits(1);
    let gated = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--diff",
            "base",
            "--fail-on",
            "not-infected",
            "--json",
        ])
        .exits(1);
    assert!(gated.contains("\"failOn\""), "{gated}");

    // A base git does not know is refused, saying why.
    let refused = project
        .supercov(&["runs", "latest", "mutants", "--diff", "no-such-branch"])
        .exits(2);
    assert!(
        refused.contains("git knows no commit by that name"),
        "{refused}"
    );
}

#[cfg(unix)]
#[test]
fn mutants_say_how_far_the_tests_got_toward_killing_each() {
    let project = mutants_project("mutants");
    // Listed by default.
    project
        .supercov_with(&["--", "npx", "mocha"], &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let summary = project.supercov(&["runs", "latest"]).succeeds();
    contains_all(
        &summary,
        &[
            "Mutants      15 · weak score 53.3% · 1 not infected · 6 not reached · 0 unknown · 0 equivalent",
        ],
    );
    let summary = project.supercov(&["runs", "latest", "--json"]).json();
    assert_eq!(summary["data"]["mutants"]["mutantSet"], "stryker-js@10.1.1");
    assert_eq!(summary["data"]["mutants"]["mutants"], 15);

    let reply = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    assert_eq!(reply["command"], "coverage.mutants");
    let data = &reply["data"];
    assert_eq!(data["mutantSet"], "stryker-js@10.1.1");
    assert_eq!(
        data["levels"],
        serde_json::json!({"weak": true, "strong": false})
    );
    assert_eq!(
        data["summary"],
        serde_json::json!({
            "mutants": 15,
            "status": {"not-reached": 6, "not-infected": 1, "infected": 8, "unknown": 0, "equivalent": 0},
            "untestable": 0,
            "weakScore": 0.5333,
            "weakScoreReached": 0.8889,
            "mutationScore": null,
        })
    );
    assert_eq!(data["stryker"], serde_json::Value::Null);
    let statuses = mutant_statuses(&reply);
    for (id, status) in [
        // `sum` was 80 and 10, never 50.
        ("src/cart.js:2:7-2:16:EqualityOperator:>", "not-infected"),
        ("src/cart.js:2:7-2:16:EqualityOperator:<", "infected"),
        (
            "src/cart.js:2:7-2:16:ConditionalExpression:false",
            "infected",
        ),
        // No test calls `refund`.
        (
            "src/cart.js:13:10-13:19:ConditionalExpression:true",
            "not-reached",
        ),
        (
            "src/cart.js:13:22-13:31:ArithmeticOperator:/",
            "not-reached",
        ),
        ("src/cart.js:9:10-9:21:MethodExpression:removed", "infected"),
    ] {
        assert_eq!(
            statuses.get(id).map(String::as_str),
            Some(status),
            "{id}: {statuses:?}"
        );
    }
    let boundary = data["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["id"] == "src/cart.js:2:7-2:16:EqualityOperator:>")
        .unwrap();
    assert_eq!(
        boundary,
        &serde_json::json!({
            "id": "src/cart.js:2:7-2:16:EqualityOperator:>",
            "file": "src/cart.js",
            "span": {"start": [2, 7], "end": [2, 16]},
            "mutator": "EqualityOperator",
            "original": "sum >= 50",
            "replacement": "sum > 50",
            "status": "not-infected",
            "weak": {
                "reach": "reached",
                "infection": "not-infected",
                "code": "operands-never-equal",
                "reason": "`sum` never equal to `50`",
            },
            "strong": null,
            "stryker": null,
            // How many of the run's tests ran its line.
            "lineTests": 2,
        })
    );

    // The table, a file by line, and a line with its reasons.
    let table = project.supercov(&["runs", "latest", "mutants"]).succeeds();
    contains_all(
        &table,
        &[
            "Mutants of run",
            "(stryker-js@10.1.1, weak mutation)",
            "Weak score   53.3% · 88.9% of reached mutants",
            "File         Mutants  Not infected  Not reached  Infected  Unknown",
            "src/cart.js       15             1            6         8        0",
            "showing 1-1 of 1 files",
        ],
    );
    let file = project
        .supercov(&["runs", "latest", "mutants", "src/cart.js"])
        .succeeds();
    contains_all(
        &file,
        &[
            "sum >= 50 → sum > 50",
            "not-infected  `sum` never equal to `50`",
            "13:22  ArithmeticOperator",
            "sum * 0.9 → sum / 0.9",
            "no test ran its statement",
            "showing 1-15 of 15",
        ],
    );
    let line = project
        .supercov(&["runs", "latest", "mutants", "src/cart.js:2"])
        .succeeds();
    contains_all(
        &line,
        &[
            "in src/cart.js:2 ",
            "2:7  EqualityOperator  not-infected",
            "  why: `sum` never equal to `50` (operands-never-equal)",
            "  id:  src/cart.js:2:7-2:16:EqualityOperator:>",
        ],
    );
    assert!(!line.contains("13:10"), "{line}");

    // `--status` picks mutants across files; the summary stays the run's.
    let picked = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--status",
            "not-infected,not-reached",
            "--json",
        ])
        .json();
    let statuses = mutant_statuses(&picked);
    assert_eq!(statuses.len(), 7, "{statuses:?}");
    assert!(
        statuses
            .values()
            .all(|status| status == "not-infected" || status == "not-reached"),
        "{statuses:?}"
    );
    assert_eq!(picked["data"]["summary"]["mutants"], 15);
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--status", "not-infected"])
        .succeeds();
    contains_all(&listed, &["src/cart.js:2:7", "showing 1-1 of 1"]);
    // A strong verdict picks the mutants a strong pass gave it: none ran.
    let killed = project
        .supercov(&["runs", "latest", "mutants", "--status", "killed"])
        .succeeds();
    assert!(killed.contains("No mutants match."), "{killed}");

    // Only the tests a title picks: the boundary they never cross.
    let narrowed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/cart.js:2",
            "--title",
            "ships big",
            "--json",
        ])
        .json();
    let statuses = mutant_statuses(&narrowed);
    assert_eq!(
        statuses
            .get("src/cart.js:2:7-2:16:ConditionalExpression:true")
            .map(String::as_str),
        Some("not-infected"),
        "{statuses:?}"
    );

    // StrykerJS's results joined by id: one kill this run agrees with, one it
    // says was impossible, one survivor it explains, one mutant it lacks.
    let source = project.read("src/cart.js");
    let mutant =
        |mutator: &str, start: [u32; 2], end: [u32; 2], replacement: &str, status: &str| {
            serde_json::json!({
                "id": "1",
                "mutatorName": mutator,
                "replacement": replacement,
                "location": {
                    "start": {"line": start[0], "column": start[1]},
                    "end": {"line": end[0], "column": end[1]},
                },
                "status": status,
            })
        };
    project.write(
        "reports/mutation.json",
        &serde_json::json!({
            "schemaVersion": "1",
            "thresholds": {"high": 80, "low": 60},
            "files": {"src/cart.js": {"language": "javascript", "source": source, "mutants": [
                mutant("ConditionalExpression", [2, 7], [2, 16], "true", "Killed"),
                mutant("EqualityOperator", [2, 7], [2, 16], "sum > 50", "Killed"),
                mutant("ConditionalExpression", [13, 10], [13, 19], "true", "Survived"),
                mutant("StringLiteral", [9, 3], [9, 4], "\"\"", "Survived"),
                mutant("EqualityOperator", [13, 10], [13, 19], "sum >= 100", "CompileError"),
            ]}},
        })
        .to_string(),
    );
    let joined = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--stryker",
            "reports/mutation.json",
        ])
        .exits(1);
    contains_all(
        &joined,
        &[
            "StrykerJS (reports/mutation.json)",
            "Matched              3",
            "Only in StrykerJS    1 (StringLiteral 1)",
            "Survivors explained  1 of 1",
            "SOUNDNESS VIOLATIONS 1",
            "src/cart.js:2:7-2:16:EqualityOperator:>  not-infected here, Killed by StrykerJS",
        ],
    );
    let joined = project.supercov(&[
        "runs",
        "latest",
        "mutants",
        "--stryker",
        "reports/mutation.json",
        "--json",
        "--limit",
        "0",
    ]);
    assert_eq!(joined.code(), 1, "{}", joined.stderr());
    let joined = joined.json();
    let stryker = &joined["data"]["stryker"];
    assert_eq!(stryker["matched"], 3);
    assert_eq!(stryker["onlyStryker"]["byMutator"]["StringLiteral"], 1);
    assert_eq!(stryker["onlySupercov"]["total"], 12);
    assert_eq!(stryker["soundnessViolations"]["total"], 1);
    assert_eq!(
        stryker["soundnessViolations"]["mutants"][0]["id"],
        "src/cart.js:2:7-2:16:EqualityOperator:>"
    );
    assert_eq!(
        stryker["survivorsExplained"],
        serde_json::json!({"survivors": 1, "explained": 1})
    );
    let killed = joined["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["id"] == "src/cart.js:2:7-2:16:ConditionalExpression:true")
        .unwrap();
    assert_eq!(killed["stryker"], "Killed");
    // Paths relative to another directory are named from the project root.
    project.write(
        "reports/nested/mutation.json",
        &project
            .read("reports/mutation.json")
            .replace("\"src/cart.js\"", "\"../../src/cart.js\""),
    );
    let rooted = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/cart.js:2",
            "--stryker",
            "reports/nested/mutation.json",
            "--stryker-root",
            "reports/nested",
            "--json",
        ])
        .json();
    assert_eq!(rooted["data"]["stryker"]["matched"], 2);
    assert_eq!(rooted["data"]["stryker"]["onlyStryker"]["total"], 0);

    // A report in chunks: several after one --stryker, or their directory.
    let report: serde_json::Value =
        serde_json::from_str(&project.read("reports/mutation.json")).unwrap();
    let chunk_mutants = report["files"]["src/cart.js"]["mutants"]
        .as_array()
        .unwrap()
        .clone();
    for (number, mutants) in chunk_mutants.chunks(2).enumerate() {
        let mut chunk = report.clone();
        chunk["files"]["src/cart.js"]["mutants"] = serde_json::Value::from(mutants.to_vec());
        project.write(&format!("chunks/part/r0{number}.json"), &chunk.to_string());
    }
    project.write("chunks/notes.txt", "not a report");
    let matched = |arguments: &[&str]| {
        let mut command = vec!["runs", "latest", "mutants", "--json", "--limit", "0"];
        command.extend(arguments);
        let joined = project.supercov(&command);
        assert_eq!(joined.code(), 1, "{arguments:?}: {}", joined.stderr());
        let joined = joined.json();
        (
            joined["data"]["stryker"]["matched"].clone(),
            joined["data"]["stryker"]["reports"].clone(),
        )
    };
    let chunks = serde_json::json!([
        "chunks/part/r00.json",
        "chunks/part/r01.json",
        "chunks/part/r02.json"
    ]);
    assert_eq!(
        matched(&["--stryker", "chunks"]),
        (3.into(), chunks.clone())
    );
    assert_eq!(
        matched(&[
            "--stryker",
            "chunks/part/r00.json",
            "chunks/part/r01.json",
            "chunks/part/r02.json",
            "chunks/part/r00.json",
        ]),
        (3.into(), chunks)
    );
    // More than a few reports are not repeated in every command shown.
    project.write(
        "chunks/part/r03.json",
        &project.read("reports/mutation.json"),
    );
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--stryker",
            "chunks/part/r00.json",
            "chunks/part/r01.json",
            "chunks/part/r02.json",
            "chunks/part/r03.json",
        ])
        .exits(1);
    contains_all(
        &listed,
        &[
            "StrykerJS (4 reports)",
            "mutants 'src/cart.js' --stryker <4 reports>",
            "<4 reports> in these commands: the reports given to --stryker",
        ],
    );
    assert!(!listed.contains("r01.json"), "{listed}");
    let directory = project
        .supercov(&["runs", "latest", "mutants", "--stryker", "chunks/part"])
        .exits(1);
    contains_all(
        &directory,
        &[
            "StrykerJS (4 reports in chunks/part)",
            "mutants 'src/cart.js' --stryker 'chunks/part'",
        ],
    );

    // Every mutant at once, one per line, each as --json lists it.
    let all = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let exported = project
        .supercov(&["runs", "latest", "mutants", "--format", "jsonl"])
        .succeeds();
    let lines = exported
        .lines()
        .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
        .collect::<Vec<_>>();
    assert_eq!(serde_json::Value::from(lines), all["data"]["mutants"]);
    project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/cart.js",
            "--status",
            "not-infected",
            "--format",
            "jsonl",
            "--output",
            "not-infected.jsonl",
        ])
        .succeeds();
    let written = project.read("not-infected.jsonl");
    assert_eq!(written.lines().count(), 1, "{written}");
    assert!(
        written.contains("\"id\":\"src/cart.js:2:7-2:16:EqualityOperator:>\""),
        "{written}"
    );
    // A soundness violation fails the export as it fails the query.
    let violated = project.supercov(&[
        "runs",
        "latest",
        "mutants",
        "--format",
        "jsonl",
        "--stryker",
        "reports/mutation.json",
    ]);
    assert_eq!(violated.code(), 1, "{}", violated.stderr());
    assert!(
        violated.stdout().contains("\"stryker\":\"Killed\""),
        "{}",
        violated.stdout()
    );
    project
        .supercov(&["runs", "latest", "mutants", "--format", "csv"])
        .exits(2);

    // A plain run lists no mutants and costs nothing for them. Asked for
    // them, it lists them from its sources, decided from its coverage alone.
    project.supercov(&["--", "npx", "mocha"]).succeeds();
    let summary = project.supercov(&["runs", "latest"]).succeeds();
    assert!(!summary.contains("Mutants "), "{summary}");
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json"])
        .json();
    assert_eq!(listed["data"]["mutantSet"], "stryker-js@10.1.1", "{listed}");
    assert!(
        listed["data"]["summary"]["mutants"].as_u64() > Some(0),
        "{listed}"
    );
}

/// node:test records its tests' evidence as a server process does, in
/// records rather than snapshots: the values its probes saw are recorded
/// with them, and decide its mutants as Mocha's snapshots do.
#[cfg(unix)]
#[test]
fn mutants_under_node_test_are_decided_from_the_values_its_records_carry() {
    let project = Project::empty("mutants-node-test");
    project.write("package.json", r#"{ "name": "mutants", "type": "module" }"#);
    project.write(
        "src/cart.js",
        "export function shipping(sum) {\n  if (sum >= 50) {\n    return 0;\n  }\n  return 5;\n}\n\nexport function label(name) {\n  return name.trim().toUpperCase();\n}\n\nexport function refund(sum) {\n  return sum > 100 ? sum * 0.9 : sum;\n}\n",
    );
    project.write(
        "test/cart.test.js",
        "import assert from \"node:assert/strict\";\nimport test from \"node:test\";\nimport { shipping, label } from \"../src/cart.js\";\ntest(\"ships big orders free\", () => assert.equal(shipping(80), 0));\ntest(\"charges small orders\", () => assert.equal(shipping(10), 5));\ntest(\"labels\", () => assert.equal(label(\" a \"), \"A\"));\n",
    );
    project.git(&["init", "-q"]);
    project.commit("mutants");
    project
        .supercov_with(&["--", "node", "--test"], &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let statuses = mutant_statuses(&reply);
    for (id, status) in [
        // `sum` was 80 and 10, never 50: a boundary only values decide.
        ("src/cart.js:2:7-2:16:EqualityOperator:>", "not-infected"),
        ("src/cart.js:2:7-2:16:EqualityOperator:<", "infected"),
        ("src/cart.js:9:10-9:21:MethodExpression:removed", "infected"),
        (
            "src/cart.js:13:22-13:31:ArithmeticOperator:/",
            "not-reached",
        ),
    ] {
        assert_eq!(
            statuses.get(id).map(String::as_str),
            Some(status),
            "{id}: {statuses:?}"
        );
    }
    // What Mocha's run of the same tests says, mutant for mutant.
    assert_eq!(
        reply["data"]["summary"],
        serde_json::json!({
            "mutants": 15,
            "status": {"not-reached": 6, "not-infected": 1, "infected": 8, "unknown": 0, "equivalent": 0},
            "untestable": 0,
            "weakScore": 0.5333,
            "weakScoreReached": 0.8889,
            "mutationScore": null,
        }),
        "{statuses:?}"
    );
}

/// A test that writes a file of the run's own name into the run's evidence
/// directory -- the declaration beside the evidence -- does not get it into
/// the archive under that name: the run stops and names the file.
#[test]
fn a_test_writing_one_of_the_run_s_own_files_into_its_evidence_stops_the_run() {
    let project = Project::cart("evidence-collision");
    project.write(
        "test/collide.test.js",
        "import test from 'node:test';\nimport { mkdirSync, writeFileSync } from 'node:fs';\ntest('writes beside the evidence', () => {\n  const directory = `.supercov/evidence/${process.env.SUPERCOV_RUN_ID}`;\n  mkdirSync(directory, { recursive: true });\n  writeFileSync(`${directory}/frontend.json`, '{}');\n});\n",
    );
    let ran = project.supercov(&["--", "node", "--test"]);
    let said = ran.stderr();
    assert_ne!(ran.code(), 0, "{said}");
    assert!(
        said.contains("duplicate Supercov evidence archive path: frontend.json"),
        "{said}"
    );
}

/// The workspace a run replaces is swept from the trash while the tests run.
/// A part of it already gone -- removed by hand meanwhile, its listing or
/// itself -- is as swept as one removed here, and the trash is left empty; a
/// part that cannot be removed leaves the rest of that tree in the trash, for
/// a later sweep.
#[test]
fn a_replaced_workspace_is_swept_whatever_is_gone_meanwhile() {
    for (fault, emptied) in [
        (
            "fs.remove_file:2#lifecycle.remove-tree-on.remove-file",
            true,
        ),
        ("fs.read_dir:2#lifecycle.remove-tree-on.read-dir", true),
        ("fs.remove_file#lifecycle.remove-tree-on.remove-file", false),
    ] {
        let project = Project::cart("sweep");
        assert_eq!(project.supercov(&["--", "node", "--test"]).code(), 0);
        let ran =
            project.supercov_with(&["--", "node", "--test"], &[("SUPERCOV_TEST_FAULT", fault)]);
        let said = ran.stderr();
        assert_eq!(ran.code(), 0, "{fault}: {said}");
        let place = &fault[fault.find('#').unwrap() + 1..];
        assert!(fired_at(&said, place), "{fault}: {said}");
        let trash = project.root.join(".supercov/.trash");
        let left = std::fs::read_dir(&trash)
            .map(|entries| {
                entries
                    .map(|entry| entry.unwrap().file_name())
                    .filter(|name| name != ".deleter.lock")
                    .count()
            })
            .unwrap_or(0);
        assert_eq!(left == 0, emptied, "{fault}: {left} left");
    }
}

/// A run prunes the sources from its workspace copy into the trash as it
/// ends, best effort: when one cannot be moved there the prune stops, what
/// it had not moved stays in the copy, which the next run copies over, and
/// the run is not failed for it.
#[test]
fn a_copied_source_that_cannot_be_pruned_stays_in_the_copy() {
    let left_in_copy = |fault: &str| {
        let project = Project::cart("prune");
        let ran =
            project.supercov_with(&["--", "node", "--test"], &[("SUPERCOV_TEST_FAULT", fault)]);
        let said = ran.stderr();
        assert_eq!(ran.code(), 0, "{said}");
        assert_eq!(
            fired_at(
                &said,
                "workspace.prune-cached-workspace-sources.remove-scratch-tree-deferred"
            ),
            !fault.is_empty(),
            "{said}"
        );
        let copies = project.root.join(".supercov/workspaces/workspace");
        std::fs::read_dir(&copies)
            .unwrap()
            .map(|copy| copy.unwrap().path())
            .filter(|copy| copy.is_dir())
            .map(|copy| {
                std::fs::read_dir(copy)
                    .unwrap()
                    .map(|entry| entry.unwrap().file_name())
                    .filter(|name| name != "node_modules" && name != ".supercov")
                    .count()
            })
            .sum::<usize>()
    };
    assert_eq!(left_in_copy(""), 0);
    // The prune stops there: that source and those after it stay.
    assert!(
        left_in_copy(
            "fs.rename#workspace.prune-cached-workspace-sources.remove-scratch-tree-deferred"
        ) > 0
    );
}

/// `mutants test --plan`: a mutant no test infected is decided without
/// running, one no test reached has no coverage, and an infected one runs
/// against the tests that infected it, and no other.
#[cfg(unix)]
#[test]
fn the_strong_plan_runs_each_infected_mutant_against_the_tests_that_infected_it() {
    let project = mutants_project("strong-plan");
    project
        .supercov_with(&["--", "npx", "mocha"], &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--plan", "--json"])
        .json();
    let tests = reply["tests"].as_array().unwrap();
    let name = |index: &serde_json::Value| {
        tests[index.as_u64().unwrap() as usize]["name"]
            .as_str()
            .unwrap()
            .to_owned()
    };
    let mutants = reply["mutants"].as_array().unwrap();
    let find = |id: &str| {
        mutants
            .iter()
            .find(|mutant| mutant["id"] == id)
            .unwrap_or_else(|| panic!("no {id} in {reply}"))
    };
    // `sum >= 50` to `sum > 50`: the tests use 80 and 10, never 50.
    let boundary = find("src/cart.js:2:7-2:16:EqualityOperator:>");
    assert_eq!(boundary["decided"], "survived", "{boundary}");
    assert_eq!(boundary["candidates"], serde_json::json!([]));
    // `refund` is never called.
    let refund = find("src/cart.js:13:10-13:19:ConditionalExpression:true");
    assert_eq!(refund["decided"], "no-coverage", "{refund}");
    // `name.trim()` to `name`: only the label test gives it a padded name.
    let trim = find("src/cart.js:9:10-9:21:MethodExpression:removed");
    assert!(trim["decided"].is_null(), "{trim}");
    let candidates = trim["candidates"]
        .as_array()
        .unwrap()
        .iter()
        .map(|candidate| name(&candidate["test"]))
        .collect::<Vec<_>>();
    assert_eq!(candidates, ["cart > labels"], "{trim}");
    // `sum >= 50` always true: only the test it changes runs it.
    let always = find("src/cart.js:2:7-2:16:ConditionalExpression:true");
    let candidates = always["candidates"]
        .as_array()
        .unwrap()
        .iter()
        .map(|candidate| name(&candidate["test"]))
        .collect::<Vec<_>>();
    assert_eq!(candidates, ["cart > charges small orders"], "{always}");
    assert_eq!(reply["summary"]["mutants"], 15);
}

/// A run whose mutants are of a language no strong driver runs yet: the
/// plan still decides them, and each it would run is an error that says so.
#[cfg(unix)]
#[test]
fn mutants_of_a_language_no_driver_runs_are_errors_that_say_so() {
    let project = vitest_mutants_project("strong-undriven");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let run = project.latest();
    // Listed beside the run, as `supercov mutants` lists a plain run's.
    project.write(
        &format!(".supercov/runs/{run}/mutants-listed.json"),
        r#"{"schemaVersion": 1, "mutantSet": "cobol-mutants@1",
            "mutantSets": {"cobol": "cobol-mutants@1"},
            "languages": {"src/cart.js": "cobol"},
            "files": {"src/cart.js": [{"mutator": "BooleanLiteral", "replacement": "false",
                "start": [2, 7], "end": [2, 16], "original": "sum >= 50"}]}}"#,
    );
    let ran = project.supercov(&["runs", "latest", "mutants", "test", "--json"]);
    let said = ran.stderr();
    let reply = ran.json();
    assert_eq!(reply["summary"]["error"], 1, "{reply}\n{said}");
    assert!(
        said.contains("no strong mutation driver for cobol yet: its mutants are errors"),
        "{said}"
    );
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let strong = &listed["data"]["mutants"][0]["strong"];
    assert_eq!(strong["status"], "error", "{listed}");
    assert_eq!(
        strong["reason"], "no strong mutation driver for cobol yet",
        "{listed}"
    );
}

/// A strong pass saves its verdicts as it makes them, so one a signal ends
/// keeps them and the next runs the rest; it keeps only its logs; after an
/// edit, only what the edit could move runs again; a run whose command
/// failed is answered and exits 2, and one that recorded no test is
/// refused; `supercov mutants` checks its options before it measures, and
/// writes its answer as markdown when asked.
#[cfg(unix)]
#[test]
fn a_strong_pass_keeps_what_it_decides_and_says_what_cannot_gate() {
    let project = vitest_mutants_project("strong-keeps");
    // Options are checked before anything is measured: there is no run yet.
    let mistaken = project
        .supercov(&["mutants", "--diff", "HEAD", "--bogus"])
        .exits(2);
    assert!(
        mistaken.contains("Unknown option: --bogus")
            && mistaken.contains("Usage: supercov mutants"),
        "{mistaken}"
    );
    assert!(project.root.join(".supercov/runs").read_dir().is_err());
    project.write(
        "src/tax.js",
        "export function tax(sum) {\n  return sum >= 10 ? sum * 0.2 : 0;\n}\n",
    );
    project.write(
        "test/tax.test.js",
        "import { expect, it } from \"vitest\";\nimport { tax } from \"../src/tax.js\";\nit(\"taxes\", () => expect(tax(20)).toBe(4));\n",
    );
    // Kills each mutant it is given by its first candidate, noting their
    // ids; with FAKE_HALF, half
    // of them and then ends as Ctrl-C ends a pass.
    project.write(
        "fake-strong.mjs",
        "import { appendFileSync, readFileSync } from \"node:fs\";\nconst plan = JSON.parse(readFileSync(process.env.SUPERCOV_STRONG_PLAN, \"utf8\"));\nconst mutants = plan.mutants.filter((mutant) => !mutant.decided);\nconst kill = process.env.FAKE_HALF ? mutants.slice(0, Math.ceil(mutants.length / 2)) : mutants;\nappendFileSync(process.env.FAKE_ASKED, mutants.map((mutant) => mutant.id + \"\\n\").join(\"\"));\nfor (const mutant of kill) appendFileSync(process.env.SUPERCOV_STRONG_RESULTS, JSON.stringify({ id: mutant.id, status: \"killed\", killedBy: plan.tests[mutant.candidates[0].test].id, tests: 1 }) + \"\\n\");\nif (process.env.FAKE_HALF) process.exit(130);\n",
    );
    project.commit("tax");
    project
        .supercov_with(
            &["--", "npx", "vitest", "run"],
            &[("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let run = project.latest();
    let asked = project.root.join("asked.txt");
    let asked_path = asked.to_str().unwrap();
    let fake = [
        "runs",
        "latest",
        "mutants",
        "test",
        "--json",
        "--",
        "node",
        "fake-strong.mjs",
    ];
    let take_asked = || {
        let ids = std::fs::read_to_string(&asked).unwrap_or_default();
        let _ = std::fs::remove_file(&asked);
        ids.lines().map(str::to_owned).collect::<Vec<_>>()
    };

    // Ended by a signal: what it killed is saved, and the next pass runs
    // the rest.
    let ended = project.supercov_with(
        &fake,
        &[
            ("FAKE_ASKED", asked_path),
            ("FAKE_HALF", "1"),
            ("SUPERCOV_STRONG_KEEP", "1"),
        ],
    );
    assert_eq!(ended.code(), 130, "{}", ended.stderr());
    assert!(
        ended
            .stderr()
            .contains("interrupted: the verdicts the pass reached are saved"),
        "{}",
        ended.stderr()
    );
    let first = take_asked();
    // Asked to, the pass kept its directory whole; the next pass removes it.
    let kept_plan = std::fs::read_dir(project.root.join(".supercov/strong"))
        .unwrap()
        .any(|pass| pass.unwrap().path().join("plan.json").is_file());
    assert!(kept_plan);
    let reply = project
        .supercov_with(&fake, &[("FAKE_ASKED", asked_path)])
        .json();
    let second = take_asked();
    assert_eq!(second.len(), first.len() / 2, "{first:?}\n{second:?}");
    assert!(second.iter().all(|id| first.contains(id)), "{second:?}");
    assert_eq!(reply["summary"]["ran"], second.len(), "{reply}");
    // The pass keeps no plan, results or jobs, only its logs.
    for pass in std::fs::read_dir(project.root.join(".supercov/strong")).unwrap() {
        for entry in std::fs::read_dir(pass.unwrap().path()).unwrap() {
            let name = entry.unwrap().file_name().into_string().unwrap();
            assert!(name.ends_with(".log"), "{name}");
        }
    }
    // The summary of the run shows the score.
    let summary = project.supercov(&["runs", "latest"]).succeeds();
    assert!(
        summary.contains("             mutation score ")
            && summary.contains("mutants --status survived"),
        "{summary}"
    );

    // Runs between that one and the next, none of which can lend their
    // verdicts: one of another command, one with none, one of another
    // mutant set.
    let measure = |command: &[&str]| {
        let mut words = vec!["--"];
        words.extend(command);
        project
            .supercov_with(&words, &[("SUPERCOV_MUTANTS", "1")])
            .succeeds();
        project.latest()
    };
    measure(&["npx", "vitest", "run", "test/cart.test.js"]);
    measure(&["npx", "vitest", "run"]);
    let other = measure(&["npx", "vitest", "run"]);
    project.write(
        &format!(".supercov/runs/{other}/strong-mutation.json"),
        r#"{"schemaVersion": 1, "run": "x", "mutantSet": "other@1", "mutants": {}}"#,
    );
    // An edit of tax.js's code: `supercov mutants` measures again, and runs
    // tax.js's mutants alone; cart.js's keep their verdicts, as no cart test
    // ran tax.js. (`runs <id> mutants test` tests the run it names whole.)
    project.edit("src/tax.js", "sum * 0.2", "sum / 5");
    project
        .supercov_with(
            &["--", "npx", "vitest", "run"],
            &[("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let to_run = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "test",
            "--plan",
            "--json",
            "--file",
            "src/tax.js",
        ])
        .json()["summary"]["toRun"]
        .clone();
    let kept = project.supercov(&["mutants"]).succeeds();
    assert!(
        kept.contains(&format!("verdict(s) kept from run {run}")),
        "{kept}"
    );
    assert!(
        kept.contains(&format!("  ran {to_run} mutant(s)")),
        "{to_run}: {kept}"
    );
    let edited = project.latest();
    // An edit of both sources keeps nothing; where the latest earlier run's
    // record of what each test ran is gone, it lends nothing, and an older
    // run of tax.js as it is again lends tax.js's verdicts.
    project.edit("src/tax.js", "sum / 5", "sum / 5.0");
    project.edit("src/cart.js", "return 5;", "return 5.0;");
    let none_kept = project.supercov(&["mutants"]).succeeds();
    assert!(!none_kept.contains("kept from run"), "{none_kept}");
    let previous = project.latest();
    std::fs::remove_file(
        project
            .root
            .join(format!(".supercov/runs/{previous}/test-executions.json")),
    )
    .unwrap();
    project.edit("src/tax.js", "sum / 5.0", "sum / 5");
    let unrecorded = project.supercov(&["mutants"]).succeeds();
    assert!(
        unrecorded.contains(&format!("verdict(s) kept from run {edited} (commit ")),
        "{unrecorded}"
    );
    assert!(!unrecorded.contains(&previous), "{unrecorded}");
    // `--plan` keeps nothing and runs nothing.
    project.supercov(&["mutants", "--plan"]).succeeds();
    // As a pull request's comment, the change's, to a file or one that
    // cannot be written.
    let markdown = project
        .supercov(&["mutants", "--format", "markdown"])
        .succeeds();
    assert!(markdown.starts_with("### Mutants"), "{markdown}");
    let change = project
        .supercov(&["mutants", "--diff", "HEAD", "--format", "markdown"])
        .succeeds();
    assert!(change.starts_with("### Mutants on this change"), "{change}");
    let unwritable = project.supercov(&[
        "mutants",
        "--format",
        "markdown",
        "--output",
        "missing/dir/mutants.md",
    ]);
    assert_eq!(unwritable.code(), 2, "{}", unwritable.stderr());

    // A failing test: the pass answers, and cannot gate.
    project.write(
        "test/fails.test.js",
        "import { expect, it } from \"vitest\";\nit(\"fails\", () => expect(1).toBe(2));\n",
    );
    project.supercov_with(
        &["--", "npx", "vitest", "run"],
        &[("SUPERCOV_MUTANTS", "1")],
    );
    let failing = project.supercov_with(&fake, &[("FAKE_ASKED", asked_path)]);
    assert_eq!(failing.code(), 2, "{}", failing.stderr());
    assert_eq!(failing.json()["result"], "error");
    assert!(
        failing.stderr().contains("1 of its") && failing.stderr().contains("did not pass (fails)"),
        "{}",
        failing.stderr()
    );
    // A command that decides nothing: no mutant could be run.
    std::fs::remove_file(project.root.join("test/fails.test.js")).unwrap();
    project.edit("src/cart.js", "return 0;", "return 0 * 1;");
    project
        .supercov_with(
            &["--", "npx", "vitest", "run"],
            &[("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let nothing = project.supercov(&[
        "runs",
        "latest",
        "mutants",
        "test",
        "--file",
        "src/cart.js",
        "--",
        "node",
        "-e",
        "0",
    ]);
    assert_eq!(nothing.code(), 2, "{}", nothing.stdout());
    assert!(
        nothing.stderr().contains("no mutant of the"),
        "{}",
        nothing.stderr()
    );

    // A run that recorded no test, its command running the code: refused,
    // naming what ran it.
    project.write(
        "run-cart.mjs",
        "import { shipping } from \"./src/cart.js\";\nshipping(80);\n",
    );
    project.supercov(&["--", "node", "run-cart.mjs"]).succeeds();
    let refused = project
        .supercov(&["runs", "latest", "mutants", "test"])
        .exits(2);
    assert!(
        refused.contains("recorded no test")
            && refused.contains("no strong driver for run-cart.mjs"),
        "{refused}"
    );
}

/// A strong pass split across machines: each shard's run holds its share of
/// the verdicts, `merge` keeps them all in the merged run, so a pass over it
/// runs nothing, and after an edit `supercov mutants` keeps each unchanged
/// mutant's verdict from whichever shard's run holds it, and runs the edited
/// file's mutants again.
#[cfg(unix)]
#[test]
fn a_strong_pass_split_across_runs_merges_and_is_kept_after_an_edit() {
    let project = vitest_mutants_project("strong-shards");
    project.write(
        "src/tax.js",
        "export function tax(sum) {\n  return sum >= 10 ? sum * 0.2 : 0;\n}\n",
    );
    project.write(
        "test/tax.test.js",
        "import { expect, it } from \"vitest\";\nimport { tax } from \"../src/tax.js\";\nit(\"taxes\", () => expect(tax(20)).toBe(4));\n",
    );
    // Gives each mutant it is given FAKE_STATUS (a kill by its first
    // candidate), noting their ids.
    project.write(
        "fake-strong.mjs",
        "import { appendFileSync, readFileSync } from \"node:fs\";\nconst plan = JSON.parse(readFileSync(process.env.SUPERCOV_STRONG_PLAN, \"utf8\"));\nconst mutants = plan.mutants.filter((mutant) => !mutant.decided);\nappendFileSync(process.env.FAKE_ASKED, mutants.map((mutant) => mutant.id + \"\\n\").join(\"\"));\nfor (const mutant of mutants) appendFileSync(process.env.SUPERCOV_STRONG_RESULTS, JSON.stringify({ id: mutant.id, status: process.env.FAKE_STATUS, killedBy: plan.tests[mutant.candidates[0].test].id, tests: 1 }) + \"\\n\");\n",
    );
    project.commit("tax");
    // Each shard's job measures the whole suite on its own machine.
    let measure = || {
        project
            .supercov_with(
                &["--", "npx", "vitest", "run"],
                &[("SUPERCOV_MUTANTS", "1")],
            )
            .succeeds();
        project.latest()
    };
    let (first, second) = (measure(), measure());
    let asked = project.root.join("asked.txt");
    let asked_path = asked.to_str().unwrap();
    let take_asked = || {
        let ids = std::fs::read_to_string(&asked).unwrap_or_default();
        let _ = std::fs::remove_file(&asked);
        ids.lines().map(str::to_owned).collect::<Vec<_>>()
    };
    let shard = |run: &str, shard: &str, status: &str| {
        project
            .supercov_with(
                &[
                    "runs",
                    run,
                    "mutants",
                    "test",
                    "--shard",
                    shard,
                    "--json",
                    "--",
                    "node",
                    "fake-strong.mjs",
                ],
                &[("FAKE_ASKED", asked_path), ("FAKE_STATUS", status)],
            )
            .json()
    };
    shard(&first, "1/2", "killed");
    let killed = take_asked();
    shard(&second, "2/2", "survived");
    let survived = take_asked();
    assert!(!killed.is_empty() && !survived.is_empty(), "{killed:?}");
    let merged = project.supercov(&["merge", &first, &second]).succeeds();
    assert!(
        merged.contains(&format!(
            "strong verdict(s) kept from runs {first}, {second}"
        )),
        "{merged}"
    );
    // Every mutant has its verdict: a pass over the merged run runs none.
    let pass = project
        .supercov_with(
            &[
                "runs",
                "latest",
                "mutants",
                "test",
                "--json",
                "--",
                "node",
                "fake-strong.mjs",
            ],
            &[("FAKE_ASKED", asked_path), ("FAKE_STATUS", "killed")],
        )
        .json();
    assert!(take_asked().is_empty(), "{pass}");
    assert_eq!(pass["summary"]["ran"], 0, "{pass}");
    // And a mutant that compiles to the same code as one it ran is killed
    // with it: `if (sum >= 50)` made `false` is its block emptied.
    assert_eq!(pass["summary"]["killed"], killed.len() + 1, "{pass}");
    assert!(
        pass["summary"]["survived"].as_u64().unwrap() >= survived.len() as u64,
        "{pass}"
    );

    // After an edit of tax.js, cart.js's mutants keep their verdicts, each
    // from the shard's run that holds it, and tax.js's run again.
    project.edit("src/tax.js", "sum * 0.2", "sum / 5");
    measure();
    let to_run = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "test",
            "--plan",
            "--json",
            "--file",
            "src/tax.js",
        ])
        .json()["summary"]["toRun"]
        .clone();
    let kept = project
        .supercov(&["mutants", "--json", "--", "npx", "vitest", "run"])
        .json();
    assert_eq!(
        kept["carried"]["from"],
        serde_json::json!([second, first]),
        "{kept}"
    );
    let carried = killed
        .iter()
        .chain(&survived)
        .filter(|id| id.starts_with("src/cart.js:"))
        .count();
    // With the mutant that took a verdict as it compiles alike.
    assert_eq!(kept["carried"]["mutants"], carried + 1, "{kept}");
    assert_eq!(kept["summary"]["ran"], to_run, "{kept}");
    // Measured again as it is: the latest run lends every verdict, and the
    // shards' runs are not read.
    let whole = kept["run"].as_str().unwrap().to_owned();
    measure();
    let again = project
        .supercov(&["mutants", "--json", "--", "npx", "vitest", "run"])
        .json();
    assert_eq!(
        again["carried"]["from"],
        serde_json::json!([whole]),
        "{again}"
    );
    assert_eq!(again["summary"]["ran"], 0, "{again}");

    // A shard of this checkout continues the newest run of it that passed
    // with the command given: not a merge, not a run whose command failed,
    // not one of another command, not one measured before the edit.
    let latest_measured = again["run"].as_str().unwrap().to_owned();
    let run_json = |run: &str| format!(".supercov/runs/{run}/run.json");
    let mut failed =
        serde_json::from_str::<serde_json::Value>(&project.read(&run_json(&first))).unwrap();
    failed["testExitCode"] = serde_json::json!(1);
    project.write(&run_json(&first), &failed.to_string());
    project
        .supercov_with(
            &["--", "npx", "vitest", "run", "--silent"],
            &[("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let shard = |command: &[&str]| {
        let mut args = vec!["mutants", "--shard", "1/1", "--json", "--"];
        args.extend(command);
        let ran = project.supercov(&args);
        (ran.json(), ran.stderr())
    };
    let (continued, said) = shard(&["npx", "vitest", "run"]);
    assert!(
        said.contains(&format!(
            "[supercov] not measuring: the checkout is unchanged since run {latest_measured}, so this shard saves its verdicts into run {}, made from it",
            continued["run"].as_str().unwrap()
        )),
        "{said}"
    );
    // None of this command: measured.
    let (_, said) = shard(&["npx", "vitest", "run", "--reporter=dot"]);
    assert!(
        said.contains("measuring first (a shard saves its verdicts into a run of its own, and no run of this checkout that recorded its mutants' values can be made into one): npx vitest run --reporter=dot"),
        "{said}"
    );
    // Edited back as the shards measured it: no run of the command is of
    // this checkout, and the merge of the shards' runs, each of this
    // command, holds every test it runs: the shard is made from it.
    project.edit("src/tax.js", "sum / 5", "sum * 0.2");
    let (_, said) = shard(&["npx", "vitest", "run"]);
    assert!(
        said.contains("holds the tests the command runs (4 test(s) in 2 of its 2 test file(s))"),
        "{said}"
    );
    // Edited again: no run is of this checkout, and it is measured.
    project.edit("src/tax.js", "sum * 0.2", "sum * 0.3");
    let (_, said) = shard(&["npx", "vitest", "run"]);
    assert!(
        said.contains("measuring first (the checkout changed since the latest run)"),
        "{said}"
    );
}

/// A split strong pass continued round after round on the same commit:
/// each job restores the earlier round's runs and runs `supercov mutants
/// --shard k/n -- <command>`. Each job saves into a run of its own, rather
/// than into the latest restored run, a copy of which every job held: those
/// copies shared one id and could not be merged. On the unchanged checkout
/// that run is made from a restored one, with no measuring, and keeps every
/// verdict the restored runs hold, though the first round's two
/// measurements recorded different evidence (a test whose path depends on
/// when it runs). The last job's `supercov merge` takes the round's runs,
/// keeps the union of their verdicts, a kill over a survival where they
/// differ, and says how many came from each, and a third round runs
/// nothing. A run named twice is refused, saying why and what to do.
#[cfg(unix)]
#[test]
fn a_continuation_round_of_a_split_pass_merges_each_job_s_run() {
    let project = vitest_mutants_project("strong-shards-continued");
    project.write(
        "src/tax.js",
        "export function tax(sum) {\n  return sum >= 10 ? sum * 0.2 : 0;\n}\n",
    );
    project.write(
        "test/tax.test.js",
        "import { expect, it } from \"vitest\";\nimport { tax } from \"../src/tax.js\";\nit(\"taxes\", () => expect(tax(20)).toBe(4));\n",
    );
    // A test whose path depends on when it runs: here, on a variable one
    // job's machine sets.
    project.write(
        "test/refund.test.js",
        "import { expect, it } from \"vitest\";\nimport { refund } from \"../src/cart.js\";\nit(\"refunds\", () => {\n  expect(refund(50)).toBe(50);\n  if (process.env.LATE) expect(refund(200)).toBe(180);\n});\n",
    );
    project.commit("tax");
    let runs = project.root.join(".supercov/runs");
    let away = project.root.join(".supercov/elsewhere");
    // A job on a machine of its own: the store holds what it restored and
    // nothing another job of its round made.
    let job_at = |shard: &str, more: &[&str], hidden: &[&str], late: bool| {
        for (n, hidden) in hidden.iter().enumerate() {
            std::fs::create_dir_all(&away).unwrap();
            std::fs::rename(runs.join(hidden), away.join(n.to_string())).unwrap();
        }
        let mut args = vec!["mutants", "--shard", shard, "--json"];
        args.extend(more);
        args.extend(["--", "npx", "vitest", "run"]);
        let ran = project.supercov_with(&args, &[("LATE", if late { "1" } else { "" })]);
        for (n, hidden) in hidden.iter().enumerate() {
            std::fs::rename(away.join(n.to_string()), runs.join(hidden)).unwrap();
        }
        (ran.json(), ran.stderr())
    };
    let job = |shard: &str, more: &[&str], hidden: Option<&str>| {
        job_at(shard, more, hidden.as_slice(), false)
    };
    // The verdicts a pass reached that a run holds, by mutant id: not
    // those the run's plan decides, with no test run, but those a mutant
    // took from a twin that compiles to the same code, which a run decided.
    let reached = |run: &str| {
        let saved = serde_json::from_str::<serde_json::Value>(
            &project.read(&format!(".supercov/runs/{run}/strong-mutation.json")),
        )
        .unwrap();
        saved["mutants"]
            .as_object()
            .unwrap()
            .iter()
            .filter(|(_, verdict)| {
                ["killed", "survived", "timeout"].contains(&verdict["status"].as_str().unwrap())
                    && (verdict["tests"] != 0
                        || verdict["reason"]
                            .as_str()
                            .is_some_and(|reason| reason.starts_with("same-code-as:")))
            })
            .map(|(id, verdict)| (id.clone(), verdict.clone()))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    // The first round leaves tax.js's mutants for the next. Its jobs each
    // measure, at different times: the second job's refund test takes the
    // path the first's did not.
    let (first_a, _) = job("1/2", &["--file", "src/cart.js"], None);
    let a1 = first_a["run"].as_str().unwrap().to_owned();
    let (first_b, _) = job_at("2/2", &["--file", "src/cart.js"], &[a1.as_str()], true);
    let b1 = first_b["run"].as_str().unwrap().to_owned();
    assert_ne!(a1, b1);
    let decided = |reply: &serde_json::Value| reply["summary"]["ran"].as_u64().unwrap();
    assert!(
        decided(&first_a) > 0 && decided(&first_b) > 0,
        "{first_a}\n{first_b}"
    );
    let evidence = |run: &str| std::fs::read(runs.join(run).join("test-executions.json")).unwrap();
    // The two measurements differ: refund's discount ran in the second
    // alone.
    let discount = "src/cart.js:13:22-13:31:ArithmeticOperator:/";
    let reached_in = |run: &str| {
        project
            .supercov(&["runs", run, "mutants", "--json", "--limit", "0"])
            .json()["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"] == discount)
            .unwrap_or_else(|| panic!("no {discount} in {run}"))["weak"]["reach"]
            .clone()
    };
    assert_ne!(reached_in(&a1), reached_in(&b1));
    // Every verdict the first round reached, the newer run's where both
    // have one.
    let mut first = reached(&a1);
    first.extend(reached(&b1));

    // A plan writes nothing, and reads the latest run as it is.
    let plan = project.supercov(&[
        "mutants", "--shard", "1/2", "--plan", "--", "npx", "vitest", "run",
    ]);
    assert_eq!(plan.code(), 0, "{}", plan.stderr());
    assert!(
        !plan.stderr().contains("measuring first"),
        "{}",
        plan.stderr()
    );
    assert_eq!(project.latest(), b1);

    // The second round, on the unchanged checkout, with both runs restored:
    // each job makes its own run from the newest, measuring nothing, and
    // keeps every verdict both shards reached.
    let (second_a, said) = job("1/2", &[], None);
    let a2 = second_a["run"]
        .as_str()
        .unwrap_or_else(|| panic!("{second_a}\n{said}"))
        .to_owned();
    assert!(
        said.contains(&format!("[supercov] not measuring: the checkout is unchanged since run {b1}, so this shard saves its verdicts into run {a2}, made from it")) && !said.contains("measuring first"),
        "{said}"
    );
    assert_eq!(
        second_a["measurement"]["derivedFrom"],
        b1.as_str(),
        "{second_a}"
    );
    assert_eq!(evidence(&a2), evidence(&b1));
    let (second_b, said) = job("2/2", &[], Some(a2.as_str()));
    assert!(!said.contains("measuring first"), "{said}");
    let b2 = second_b["run"].as_str().unwrap().to_owned();
    let restored = [a1.as_str(), b1.as_str()];
    assert!(
        a2 != b2 && !restored.contains(&a2.as_str()) && !restored.contains(&b2.as_str()),
        "{a1} {b1} {a2} {b2}"
    );
    let carried = |reply: &serde_json::Value| reply["carried"]["mutants"].as_u64().unwrap();
    for (reply, run) in [(&second_a, &a2), (&second_b, &b2)] {
        assert_eq!(
            reply["carried"]["from"],
            serde_json::json!([b1, a1]),
            "{reply}"
        );
        assert_eq!(reply["carried"]["unchanged"], true, "{reply}");
        assert_eq!(carried(reply), first.len() as u64, "{reply}");
        // Kept as they were.
        let now = reached(run);
        assert!(
            first
                .iter()
                .all(|(id, verdict)| now.get(id) == Some(verdict)),
            "{reply}"
        );
    }
    // What no pass reached is not a verdict to keep: a mutant the first
    // job's run had no test for, which the second job's tests reach.
    assert!(
        second_a["carried"]["notKept"]
            .as_object()
            .unwrap()
            .keys()
            .all(|reason| reason == "notRunThen"),
        "{second_a}"
    );
    assert!(
        decided(&second_a) > 0 && decided(&second_b) > 0,
        "{second_a}\n{second_b}"
    );

    // The two jobs' runs disagree on a verdict both kept from the first
    // round: the first run the merge reads let it survive, the other
    // killed it.
    let verdicts_of = |run: &str| format!(".supercov/runs/{run}/strong-mutation.json");
    let mut of_b2 =
        serde_json::from_str::<serde_json::Value>(&project.read(&verdicts_of(&b2))).unwrap();
    let mut of_a2 =
        serde_json::from_str::<serde_json::Value>(&project.read(&verdicts_of(&a2))).unwrap();
    let contested = of_b2["mutants"]
        .as_object()
        .unwrap()
        .iter()
        .find(|(id, verdict)| {
            id.starts_with("src/cart.js:")
                && verdict["status"] == "killed"
                && of_a2["mutants"][id.as_str()] == **verdict
        })
        .map(|(id, _)| id.clone())
        .expect("a kill both jobs kept from the first round");
    of_b2["mutants"][&contested]["status"] = serde_json::json!("survived");
    project.write(&verdicts_of(&b2), &of_b2.to_string());
    of_a2["mutants"][&contested]["status"] = serde_json::json!("killed");
    project.write(&verdicts_of(&a2), &of_a2.to_string());

    // The last job: the second round's runs replace the first's, and the
    // merge keeps every verdict of both.
    let merged = project.supercov(&["merge"]).succeeds();
    contains_all(&merged, &["merging 2 runs", &a2, &b2]);
    let merged_id = project.latest();
    let kept =
        serde_json::from_str::<serde_json::Value>(&project.read(&verdicts_of(&merged_id))).unwrap();
    let kept = kept["mutants"].as_object().unwrap();
    assert_eq!(kept[&contested]["status"], "killed", "{merged}");
    let total = kept.len();
    // Each run counts what was taken from it: b2, read first, the first
    // round's verdicts and its share, a2 its share and the contested kill.
    let from_b2 = carried(&second_b) - 1 + decided(&second_b);
    let from_a2 = decided(&second_a) + 1;
    let planned = total as u64 - from_b2 - from_a2;
    assert!(
        merged.contains(&format!(
            "[supercov] {total} strong verdict(s) kept from runs {b2}, {a2}: {from_b2} from {b2}, {from_a2} from {a2}, {planned} the merged run's plan decides\n"
        )),
        "{merged}"
    );
    let left = project
        .supercov(&["runs", "latest", "mutants", "test", "--plan", "--json"])
        .json();
    assert_eq!(left["summary"]["toRun"], 0, "{left}");

    // A third round, from the second's runs alone: nothing to run, nothing
    // measured, every verdict kept.
    let second = reached(&a2)
        .into_iter()
        .chain(reached(&b2))
        .collect::<std::collections::BTreeMap<_, _>>();
    let (third, said) = job_at(
        "1/2",
        &[],
        &[a1.as_str(), b1.as_str(), merged_id.as_str()],
        false,
    );
    assert!(!said.contains("measuring first"), "{said}");
    assert_eq!(third["summary"]["ran"], 0, "{third}");
    assert_eq!(carried(&third), second.len() as u64, "{third}");
    assert!(
        third["carried"]["notKept"].as_object().unwrap().is_empty(),
        "{third}"
    );

    // Copies of one run cannot be merged: said, with what to do instead.
    let twice = project.supercov(&["merge", &b2, &b2]).exits(2);
    assert!(
        twice.contains(&format!(
            "Each merged run must be unique: {b2} is named more than once. Copies of one run"
        )) && twice.contains("Run that round again and merge its jobs' runs"),
        "{twice}"
    );
}

/// A measured run whose command failed only because a test failed (one
/// timing-sensitive test, unrelated to the mutated code) is continued by a
/// shard as one whose command passed is: the failed test is no candidate,
/// so the shard saves into a run made from it, measures nothing, and says
/// which test it leaves out. A run whose command failed for another reason
/// is not continued: where no run can be, the shard measures and says what
/// kept the newest one out, naming its failed tests.
#[cfg(unix)]
#[test]
fn a_shard_continues_a_run_whose_command_failed_only_in_a_failed_test() {
    let project = vitest_mutants_project("strong-shard-after-failed-test");
    project.write(
        "test/timing.test.js",
        "import { expect, it } from \"vitest\";\nimport { shipping } from \"../src/cart.js\";\nit(\"settles in time\", () => {\n  expect(shipping(80)).toBe(0);\n  if (process.env.SLOW) throw new Error(\"took too long\");\n});\n",
    );
    project.commit("timing");
    let command = ["npx", "vitest", "run"];
    // The measuring job: its one slow test failed, and its command exited 1.
    let mut args = vec!["mutants", "--file", "src/cart.js", "--budget", "30", "--"];
    args.extend(command);
    let measured = project.supercov_with(&args, &[("SLOW", "1")]);
    assert_eq!(measured.code(), 2, "{}", measured.stderr());
    let failing = project.latest();
    let run_json = |run: &str| format!(".supercov/runs/{run}/run.json");
    let metadata = |run: &str| {
        serde_json::from_str::<serde_json::Value>(&project.read(&run_json(run))).unwrap()
    };
    assert_eq!(metadata(&failing)["testExitCode"], 1);
    let shard = || {
        let mut args = vec!["mutants", "--shard", "1/1", "--json", "--"];
        args.extend(command);
        let ran = project.supercov(&args);
        (ran.json(), ran.stderr())
    };
    let slow = "settles in time";

    // The shard continues it, measuring nothing, and says what it leaves out.
    let (continued, said) = shard();
    let own = continued["run"].as_str().unwrap().to_owned();
    assert!(
        said.contains(&format!(
            "[supercov] not measuring: the checkout is unchanged since run {failing}, so this shard saves its verdicts into run {own}, made from it"
        )) && said.contains(&format!(
            "[supercov] continuing from run {failing}, whose command failed: 1 test failed while measuring and is not a candidate: {slow}"
        )) && !said.contains("measuring first"),
        "{said}"
    );
    assert_eq!(
        continued["measurement"]["derivedFrom"],
        failing.as_str(),
        "{continued}"
    );
    assert_eq!(
        continued["measurement"]["failedTests"],
        serde_json::json!([slow]),
        "{continued}"
    );
    // It keeps what the measuring job's pass decided, and no verdict is the
    // failed test's.
    assert_eq!(
        continued["carried"]["from"],
        serde_json::json!([failing]),
        "{continued}"
    );
    assert!(
        continued["summary"]["killed"].as_u64().unwrap() > 0,
        "{continued}"
    );
    let verdicts = project.read(&format!(".supercov/runs/{own}/strong-mutation.json"));
    assert!(
        verdicts.contains("\"killed\"") && !verdicts.contains(slow),
        "{verdicts}"
    );

    // A newer run whose command failed with no test failed (it failed
    // outside its tests) is passed over for the one whose test failed.
    project
        .supercov_with(
            &[&["--"][..], &command[..]].concat(),
            &[("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let broken = project.latest();
    let mut edited = metadata(&broken);
    edited["testExitCode"] = serde_json::json!(3);
    project.write(&run_json(&broken), &edited.to_string());
    let (again, said) = shard();
    assert!(!said.contains("measuring first"), "{said}");
    let from = again["measurement"]["derivedFrom"]
        .as_str()
        .unwrap()
        .to_owned();
    assert!(
        from != broken && metadata(&from)["testExitCode"] == 1,
        "{again}"
    );

    // A run that ended without an exit status is not continued either:
    // with none left, the shard measures, and says why, naming the newest
    // such run's failed test.
    let runs = std::fs::read_dir(project.root.join(".supercov/runs"))
        .unwrap()
        .map(|entry| entry.unwrap().file_name().into_string().unwrap())
        .collect::<Vec<_>>();
    for run in &runs {
        let mut edited = metadata(run);
        if edited["testExitCode"] == 1 {
            edited["testExitCode"] = serde_json::Value::Null;
            project.write(&run_json(run), &edited.to_string());
        }
    }
    let newest = again["run"].as_str().unwrap();
    let (_, said) = shard();
    assert!(
        said.contains(&format!(
            "measuring first (a shard saves its verdicts into a run of its own, and no run of this checkout that recorded its mutants' values can be made into one: run {newest}'s command ended without an exit status (1 test failed while measuring and is not a candidate: {slow})): npx vitest run"
        )),
        "{said}"
    );
}

/// A shard's run made from a restored one, on an unchanged checkout, that
/// could not be made -- the store unlisted, its staging not created, the
/// restored run's files unread or not copied, its record, its rename into
/// place or the store's sync failing -- stops the command before any pass,
/// saying from which run and why, and leaves no run behind.
#[cfg(unix)]
#[test]
fn a_shard_s_run_that_cannot_be_made_from_a_restored_one_stops_the_command() {
    let project = vitest_mutants_project("strong-derive-faults");
    project.write(
        "src/tax.js",
        "export function tax(sum) {\n  return sum >= 10 ? sum * 0.2 : 0;\n}\n",
    );
    project.write(
        "test/tax.test.js",
        "import { expect, it } from \"vitest\";\nimport { tax } from \"../src/tax.js\";\nit(\"taxes\", () => expect(tax(20)).toBe(4));\n",
    );
    project.commit("tax");
    project
        .supercov_with(
            &["--", "npx", "vitest", "run"],
            &[("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let restored = project.latest();
    for fault in [
        "run-store-unlisted",
        "fs.create_dir_all#lifecycle.derive-run.create-dir-all",
        "fs.read_dir#lifecycle.derive-run.read-dir",
        "fs.symlink_metadata#lifecycle.copy-regular-file",
        "fs.create_dir_all#lifecycle.derive-run.atomic-write",
        "fs.rename#lifecycle.derive-run.rename",
        "fs.open#lifecycle.derive-run.sync-directory",
    ] {
        let ran = project.supercov_with(
            &["mutants", "--shard", "1/2", "--", "npx", "vitest", "run"],
            &[("SUPERCOV_TEST_FAULT", fault)],
        );
        let said = ran.stderr();
        assert_eq!(ran.code(), 2, "{fault}\n{said}");
        assert!(
            said.contains(&format!(
                "[supercov] could not make this shard's run from {restored}: "
            )) && !said.contains("strong pass"),
            "{fault}\n{said}"
        );
        // Only the restored run and, past the rename, the one made.
        let runs = std::fs::read_dir(project.root.join(".supercov/runs"))
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| entry.file_name().to_string_lossy().starts_with("run_"))
            .count();
        assert_eq!(
            runs,
            if fault.ends_with("sync-directory") {
                2
            } else {
                1
            },
            "{fault}"
        );
        if runs == 2 {
            let made = project.latest();
            std::fs::remove_dir_all(project.root.join(".supercov/runs").join(made)).unwrap();
        }
    }
    // A run made from it holds cart.js's verdicts; a shard of tax.js's
    // mutants keeps none of them, and runs its own.
    let job = |file: &str| {
        project
            .supercov(&[
                "mutants", "--shard", "1/1", "--file", file, "--json", "--", "npx", "vitest", "run",
            ])
            .json()
    };
    let cart = job("src/cart.js");
    assert!(cart["summary"]["ran"].as_u64() > Some(0), "{cart}");
    let tax = job("src/tax.js");
    assert!(
        tax["carried"].is_null() && tax["summary"]["ran"].as_u64() > Some(0),
        "{tax}"
    );
}

/// Verdicts carried forward across commits are those a fresh pass reaches.
/// A project measured and passed whole on its first commit, then one commit
/// after another, each touching code, tests, helpers or configuration in its
/// own way: at each, `supercov mutants` keeps what no change could move and
/// runs the rest, and a pass from nothing on the same commit gives every
/// mutant the same verdict. The trap: `refund`'s mutants survive while
/// `audit`, which no test runs, returns what it is given, and a mutant that
/// sends `refund(20)` into `audit` is killed once `audit` changes, though no
/// test's record names `audit`. The listing says where a kept verdict was
/// reached.
#[cfg(unix)]
#[test]
fn verdicts_carried_across_commits_are_those_a_fresh_pass_reaches() {
    let project = vitest_mutants_project("strong-carried-forward");
    project.write(
        "vitest.config.js",
        "export default { test: { include: [\"test/**/*.test.js\"] } };\n",
    );
    project.write(
        "src/audit.js",
        "export function audit(sum) {\n  return sum;\n}\n",
    );
    project.write(
        "src/cart.js",
        "import { audit } from \"./audit.js\";\n\nexport function shipping(sum) {\n  if (sum >= 50) {\n    return 0;\n  }\n  return 5;\n}\n\nexport function label(name) {\n  return name.trim().toUpperCase();\n}\n\nexport function refund(sum) {\n  if (sum > 1000) {\n    return audit(sum);\n  }\n  return sum - 1;\n}\n\nexport function wrap(text) {\n  return \"[\" + text + \"]\";\n}\n",
    );
    project.write(
        "src/tax.js",
        "export function tax(sum) {\n  return sum >= 10 ? sum * 0.2 : 0;\n}\n\nexport function round(value) {\n  return Math.round(value * 100) / 100;\n}\n",
    );
    project.write(
        "src/format.js",
        "export function price(cents) {\n  const whole = Math.floor(cents / 100);\n  const rest = cents % 100;\n  return whole + \".\" + String(rest).padStart(2, \"0\");\n}\n",
    );
    project.write(
        "test/helpers.js",
        "export function cents(value) {\n  return value;\n}\n",
    );
    project.write(
        "test/cart.test.js",
        "import { describe, expect, it } from \"vitest\";\nimport { shipping, label, refund } from \"../src/cart.js\";\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\n  it(\"charges small orders\", () => expect(shipping(10)).toBe(5));\n  it(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n  it(\"refunds\", () => expect(refund(20)).toBeGreaterThan(0));\n});\n",
    );
    project.write(
        "test/tax.test.js",
        "import { expect, it } from \"vitest\";\nimport { tax, round } from \"../src/tax.js\";\nit(\"taxes\", () => expect(tax(20)).toBe(4));\nit(\"rounds\", () => expect(round(1.234)).toBe(1.23));\n",
    );
    project.write(
        "test/format.test.js",
        "import { expect, it } from \"vitest\";\nimport { price } from \"../src/format.js\";\nimport { cents } from \"./helpers.js\";\nit(\"prices\", () => expect(price(cents(1234))).toBe(\"12.34\"));\n",
    );
    project.commit("fixture");
    let pass = || {
        project
            .supercov(&["mutants", "--json", "--", "npx", "vitest", "run"])
            .json()
    };
    let statuses = |run: &str| {
        let saved = serde_json::from_str::<serde_json::Value>(
            &project.read(&format!(".supercov/runs/{run}/strong-mutation.json")),
        )
        .unwrap();
        saved["mutants"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(id, verdict)| (id.clone(), verdict["status"].as_str().unwrap().to_owned()))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    // A pass from nothing: the store set aside while it runs.
    let store = project.root.join(".supercov");
    let aside = project.root.join(".supercov-aside");
    let fresh = || {
        std::fs::rename(&store, &aside).unwrap();
        let reply = pass();
        let verdicts = statuses(reply["run"].as_str().unwrap());
        std::fs::remove_dir_all(&store).unwrap();
        std::fs::rename(&aside, &store).unwrap();
        (reply, verdicts)
    };
    let first = pass();
    let all = first["summary"]["ran"].as_u64().unwrap();
    assert!(all > 20, "{first}");
    // Each commit: what the carrying pass kept and ran, against a fresh
    // pass's verdicts.
    let mut kept_in_all = 0;
    let mut ran_in_all = 0;
    let mut step = |message: &str, kept: Option<u64>, why: &[&str]| {
        project.commit(message);
        let carried = pass();
        let (whole, verdicts) = fresh();
        assert_eq!(
            statuses(carried["run"].as_str().unwrap()),
            verdicts,
            "{message}: {carried}"
        );
        let ran = carried["summary"]["ran"].as_u64().unwrap();
        assert!(
            ran < whole["summary"]["ran"].as_u64().unwrap() || kept.is_none(),
            "{message}: {carried}"
        );
        if let Some(kept) = kept {
            assert_eq!(carried["carried"]["mutants"], kept, "{message}: {carried}");
        } else {
            assert!(carried["carried"].is_null(), "{message}: {carried}");
        }
        let reasons = carried["carried"]["notKept"]
            .as_object()
            .map(|reasons| reasons.keys().cloned().collect::<Vec<_>>())
            .unwrap_or_default();
        assert_eq!(reasons, why, "{message}: {carried}");
        kept_in_all += kept.unwrap_or(0);
        ran_in_all += ran;
        carried
    };
    // Comments and blank lines move every mutant of two files: each verdict
    // is found by its code.
    project.write(
        "src/cart.js",
        &format!(
            "// The cart's rules.\n// Shipping is free from 50.\n\n{}",
            project.read("src/cart.js")
        ),
    );
    project.edit(
        "src/tax.js",
        "export function round",
        "// Two decimals.\nexport function round",
    );
    let moved = step("comments", Some(25), &[]);
    assert_eq!(moved["summary"]["ran"], 0, "{moved}");
    // A test file: its tests' mutants run again, and the one a new test
    // could kill.
    project.write(
        "test/tax.test.js",
        &format!(
            "{}it(\"no tax under 10\", () => expect(tax(5)).toBe(0));\n",
            project.read("test/tax.test.js")
        ),
    );
    step("a test", Some(18), &["newTest", "testReached"]);
    // A helper one test file loads.
    project.edit(
        "test/helpers.js",
        "  return value;",
        "  return Number(value);",
    );
    step("a helper", Some(21), &["testReached"]);
    // One function of a source: its own mutants and its tests' run again.
    project.edit(
        "src/tax.js",
        "  return Math.round(value * 100) / 100;",
        "  const scaled = value * 100;\n  return Math.round(scaled) / 100;",
    );
    step("a function", Some(18), &["fileChanged", "testReached"]);
    // A function no test runs, which `refund`'s mutants lead the refund test
    // into: they run again, and two of them are killed now.
    project.edit("src/audit.js", "  return sum;", "  return -sum;");
    let trap = step("audit", Some(13), &["loadsChanged"]);
    let now = statuses(trap["run"].as_str().unwrap());
    for id in [
        "src/cart.js:18:7-18:17:ConditionalExpression:true",
        "src/cart.js:18:7-18:17:EqualityOperator:<=",
    ] {
        assert_eq!(now[id], "killed", "{id}: {trap}");
    }
    // A function of the same file no test runs or names: every verdict is
    // kept.
    project.edit(
        "src/cart.js",
        "\"[\" + text + \"]\"",
        "\"(\" + text + \")\"",
    );
    let unnamed = step("wrap", Some(26), &[]);
    assert_eq!(unnamed["summary"]["ran"], 0, "{unnamed}");
    // A test added to a file: its file's tests may run otherwise, and it may
    // kill what survived.
    project.edit(
        "test/cart.test.js",
        "  it(\"refunds\"",
        "  it(\"ships 50 free\", () => expect(shipping(50)).toBe(0));\n  it(\"refunds\"",
    );
    step("a test added", Some(13), &["newTest", "testReached"]);
    // The configuration: nothing is kept.
    project.edit("vitest.config.js", "] } };", "], testTimeout: 5000 } };");
    step("configuration", None, &[]);
    assert!(
        kept_in_all > ran_in_all,
        "kept {kept_in_all}, ran {ran_in_all}"
    );

    // The summary and the listing say where a kept verdict was reached.
    project.edit(
        "test/helpers.js",
        "  return Number(value);",
        "  return value;",
    );
    project.commit("helper back");
    let back = project.supercov(&["mutants", "--", "npx", "vitest", "run"]);
    let said = back.stdout();
    assert!(
        said.contains(" verdict(s) kept from run ")
            && said.contains(", which took ")
            && said.contains(" test run(s) to reach: nothing they depend on changed\n"),
        "{said}"
    );
    let listed = project
        .supercov(&["runs", "latest", "mutants", "src/cart.js"])
        .succeeds();
    let configured = project.git(&["rev-parse", "--short=7", "HEAD~1"]);
    assert!(
        listed.contains(&format!("(commit {})", configured.trim())),
        "{listed}"
    );
    let line = project
        .supercov(&["runs", "latest", "mutants", "src/cart.js:7"])
        .succeeds();
    assert!(
        line.contains("  strong: killed  carried from run "),
        "{line}"
    );
}

/// A Vitest project like `mutants_project`'s, with the repository's
/// node_modules.
#[cfg(unix)]
fn vitest_mutants_project(label: &str) -> Project {
    let project = Project::empty(label);
    project.write(
        "package.json",
        r#"{ "name": "mutants", "type": "module", "scripts": { "test": "vitest run" } }"#,
    );
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "src/cart.js",
        "export function shipping(sum) {\n  if (sum >= 50) {\n    return 0;\n  }\n  return 5;\n}\n\nexport function label(name) {\n  return name.trim().toUpperCase();\n}\n\nexport function refund(sum) {\n  return sum > 100 ? sum * 0.9 : sum;\n}\n",
    );
    project.write(
        "test/cart.test.js",
        "import { describe, expect, it } from \"vitest\";\nimport { shipping, label } from \"../src/cart.js\";\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\n  it(\"charges small orders\", () => expect(shipping(10)).toBe(5));\n  it(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("mutants");
    project
}

/// A strong pass compiles each JavaScript mutant's file and the original:
/// a mutant that compiles to the original's code is equivalent and is not
/// run, and mutants that compile to the same code as one another run once,
/// each taking that run's verdict. The pass, its summary, the listing and
/// the markdown report say so in plain words.
#[cfg(unix)]
#[test]
fn mutants_that_compile_to_the_same_code_are_decided_once_or_not_run() {
    let project = vitest_mutants_project("strong-same-code");
    project.write(
        "src/notify.js",
        "export function size(empty) {\n  if (empty) {\n    return \"none\";\n  }\n  return \"none\";\n}\n\nexport function notify(log) {\n  if (log) {\n    log(\"sent\");\n  }\n  return 1;\n}\n",
    );
    project.write(
        "test/notify.test.js",
        "import { expect, it, vi } from \"vitest\";\nimport { size, notify } from \"../src/notify.js\";\nit(\"sizes\", () => {\n  expect(size(true)).toBe(\"none\");\n  expect(size(false)).toBe(\"none\");\n});\nit(\"notifies\", () => {\n  const log = vi.fn();\n  notify(log);\n  expect(log).toHaveBeenCalledWith(\"sent\");\n  expect(notify(undefined)).toBe(1);\n});\n",
    );
    project.commit("notify");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let ran = project.supercov(&[
        "runs",
        "latest",
        "mutants",
        "test",
        "--json",
        "--file",
        "src/notify.js",
    ]);
    let said = ran.stderr();
    let reply = ran.json();
    // `if (empty)` made `true` or `false`, or its block emptied: each
    // returns "none" as the original does.
    assert_eq!(
        reply["sameCode"],
        serde_json::json!({"equivalent": 3, "equivalentToRun": 3, "duplicates": 1,
            "savedMs": reply["sameCode"]["savedMs"], "notCompiled": [], "tooLarge": []}),
        "{reply}\n{said}"
    );
    assert!(
        said.contains("[supercov] 3 mutant(s) proven equivalent: each compiles to the same code as the original, so no test can tell it apart; 3 of them would have run and did not\n")
            && said.contains("[supercov] 1 mutant(s) compile to the same code as another mutant, which runs once and gives them its verdict\n"),
        "{said}"
    );
    assert_eq!(reply["summary"]["equivalent"], 3, "{reply}");
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    // A pass over what has its verdicts compares nothing again, and says
    // nothing of it; the summary still counts them.
    let human = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "test",
            "--file",
            "src/notify.js",
        ])
        .succeeds();
    assert!(human.contains("  equivalent    3\n"), "{human}");
    assert!(!human.contains("compiles to the same code"), "{human}");
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let strong = |id: &str| {
        listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"] == id)
            .unwrap_or_else(|| panic!("no {id} in {listed}"))["strong"]
            .clone()
    };
    for id in [
        "src/notify.js:2:7-2:12:ConditionalExpression:true",
        "src/notify.js:2:7-2:12:ConditionalExpression:false",
        "src/notify.js:2:14-4:4:BlockStatement:{}",
    ] {
        let verdict = strong(id);
        assert_eq!(
            (&verdict["status"], &verdict["reason"]),
            (
                &serde_json::json!("equivalent"),
                &serde_json::json!("compiles-to-original")
            ),
            "{id}: {verdict}"
        );
    }
    // The `if (log)` block emptied and its test made `false` are one
    // program: the first runs, and the other takes its kill.
    let kept = strong("src/notify.js:9:7-9:10:ConditionalExpression:false");
    assert_eq!(kept["status"], "killed", "{kept}");
    {
        let id = "src/notify.js:9:12-11:4:BlockStatement:{}";
        let verdict = strong(id);
        assert_eq!(verdict["status"], "killed", "{id}: {verdict}");
        assert_eq!(verdict["tests"], 0, "{id}: {verdict}");
        assert_eq!(
            verdict["reason"], "same-code-as:src/notify.js:9:7-9:10:ConditionalExpression:false",
            "{id}: {verdict}"
        );
    }
    // One line's mutants say why in plain words.
    let line = project
        .supercov(&["runs", "latest", "mutants", "src/notify.js:2"])
        .succeeds();
    assert!(
        line.contains("  strong: equivalent: compiles to the same code as the original: no test can tell it apart, so it was not run\n"),
        "{line}"
    );
    // The comment folds them apart from the survivors.
    let markdown = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/notify.js",
            "--format",
            "markdown",
        ])
        .succeeds();
    assert!(
        markdown.contains("<details><summary>3 mutants proven equivalent: no test can tell them from the original, so they are not run, not counted as survivors, and not in the score</summary>"),
        "{markdown}"
    );
}

/// `mutants test` over a Vitest run: each mutant the tests infected runs
/// against the tests that infected it, and the verdicts are StrykerJS's:
/// killed where a test fails, survived where none can, no coverage where
/// none ran it. `mutants` then shows them and the mutation score.
#[cfg(unix)]
#[test]
fn mutants_test_kills_and_keeps_what_the_vitest_tests_can_and_cannot_tell() {
    let project = vitest_mutants_project("strong-vitest");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let ran = project.supercov(&["runs", "latest", "mutants", "test", "--json"]);
    let said = ran.stderr();
    let reply = ran.json();
    let summary = &reply["summary"];
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    assert_eq!(summary["mutants"], 15, "{reply}");
    assert_eq!(summary["error"], 0, "{reply}\n{said}\n{listed}");
    let strong = |id: &str| {
        listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"] == id)
            .unwrap_or_else(|| panic!("no {id} in {listed}"))["strong"]
            .clone()
    };
    // No test gives `shipping` 50: `>=` to `>` survives, decided unrun.
    assert_eq!(
        strong("src/cart.js:2:7-2:16:EqualityOperator:>")["status"],
        "survived"
    );
    assert_eq!(
        strong("src/cart.js:13:10-13:19:ConditionalExpression:true")["status"],
        "no-coverage"
    );
    let trim = strong("src/cart.js:9:10-9:21:MethodExpression:removed");
    assert_eq!(trim["status"], "killed", "{trim}");
    let always = strong("src/cart.js:2:7-2:16:ConditionalExpression:true");
    assert_eq!(always["status"], "killed", "{always}");
    let lower = strong("src/cart.js:9:10-9:35:MethodExpression:toLowerCase");
    assert_eq!(lower["status"], "killed", "{lower}");
    // 8 infected mutants all killed; 1 survived; 6 not covered.
    assert_eq!(summary["killed"], 8, "{reply}");
    assert_eq!(summary["survived"], 1, "{reply}");
    assert_eq!(summary["noCoverage"], 6, "{reply}");
    assert_eq!(listed["data"]["summary"]["mutationScore"], 0.5333);
    assert_eq!(listed["data"]["levels"]["strong"], true);
    // A second pass has nothing left to run.
    let again = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    assert_eq!(again["summary"]["ran"], 0, "{again}");
    assert_eq!(again["summary"]["killed"], 8, "{again}");
}

/// The cart of `mutants_project`, and a countdown whose `i--` made `i++`
/// never ends, tested by `test/cart.test.*` and `test/count.test.*` under
/// another runner. `module` is the package's `type`.
#[cfg(unix)]
fn job_runner_project(label: &str, module: &str, tests: &[(&str, &str)]) -> Project {
    let project = Project::empty(label);
    project.write(
        "package.json",
        &format!(r#"{{ "name": "cart", "type": "{module}" }}"#),
    );
    // The repository's packages, where it has them: Bun's tests need none
    // and run where they were never installed (the Bun bootstrap job).
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    if let Ok(modules) = modules.canonicalize() {
        std::os::unix::fs::symlink(modules, project.root.join("node_modules")).unwrap();
    }
    project.write(".gitignore", "node_modules\n.supercov\n");
    let exports = if module == "module" {
        ("export function", "")
    } else {
        (
            "function",
            "\nmodule.exports = { shipping, label, refund, countdown };\n",
        )
    };
    project.write(
        "src/cart.js",
        &format!(
            "{0} shipping(sum) {{\n  if (sum >= 50) {{\n    return 0;\n  }}\n  return 5;\n}}\n\n{0} label(name) {{\n  return name.trim().toUpperCase();\n}}\n\n{0} refund(sum) {{\n  return sum > 100 ? sum * 0.9 : sum;\n}}\n\n{0} countdown(n) {{\n  let i = n;\n  while (i > 0) {{\n    i--;\n  }}\n  return i;\n}}\n{1}",
            exports.0, exports.1
        ),
    );
    for (file, source) in tests {
        project.write(file, source);
    }
    project.git(&["init", "-q"]);
    project.commit("cart");
    project
}

/// Each mutant's strong verdict in a `mutants --json` reply, by id.
#[cfg(unix)]
fn strong_statuses(project: &Project) -> std::collections::BTreeMap<String, String> {
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .map(|mutant| {
            (
                mutant["id"].as_str().unwrap().to_owned(),
                mutant["strong"]["status"]
                    .as_str()
                    .unwrap_or("-")
                    .to_owned(),
            )
        })
        .collect()
}

/// The verdicts every runner's cart gives: the tests tell `trim()` and the
/// shipping condition apart, never give `shipping` 50, never call `refund`,
/// and a countdown that never ends is a timeout. Only the jobs driver ran.
#[cfg(unix)]
fn assert_cart_verdicts(project: &Project, command: &[&str], runner: &str) {
    let mut measure = vec!["--"];
    measure.extend_from_slice(command);
    project
        .supercov_with(&measure, &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let ran = project.supercov(&["runs", "latest", "mutants", "test", "--json"]);
    let said = ran.stderr();
    let reply = ran.json();
    assert_eq!(reply["summary"]["error"], 0, "{runner}: {reply}\n{said}");
    assert_eq!(reply["passes"][0]["driver"], "jobs", "{runner}: {reply}");
    let statuses = strong_statuses(project);
    for (id, status) in [
        ("src/cart.js:9:10-9:21:MethodExpression:removed", "killed"),
        ("src/cart.js:2:7-2:16:ConditionalExpression:true", "killed"),
        ("src/cart.js:2:7-2:16:EqualityOperator:>", "survived"),
        (
            "src/cart.js:13:10-13:19:ConditionalExpression:true",
            "no-coverage",
        ),
        ("src/cart.js:19:5-19:8:UpdateOperator:++", "timeout"),
    ] {
        assert_eq!(
            statuses.get(id).map(String::as_str),
            Some(status),
            "{runner} {id}: {statuses:?}\n{said}"
        );
    }
}

/// What a strong pass let survive is named in every view, not only counted:
/// the pass's summary ends with the survivors, the text listing shows each
/// mutant's strong verdict beside its weak status and `--status survived`
/// picks the survivors, and the markdown for a pull request lists them under
/// the mutation score.
#[cfg(unix)]
#[test]
fn surviving_mutants_are_named_in_every_view() {
    let project = job_runner_project(
        "strong-survivors-named",
        "module",
        &[(
            "test/cart.test.js",
            "import assert from \"node:assert/strict\";\nimport { it } from \"node:test\";\nimport { shipping, label } from \"../src/cart.js\";\nit(\"ships big orders free\", () => assert.equal(shipping(80), 0));\nit(\"charges small orders\", () => assert.equal(shipping(10), 5));\nit(\"labels\", () => assert.equal(label(\" a \"), \"A\"));\n",
        )],
    );
    project
        .supercov_with(&["--", "node", "--test"], &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let pass = project
        .supercov(&["runs", "latest", "mutants", "test"])
        .succeeds();
    // `sum >= 50` to `sum > 50` changes neither 80 nor 10.
    let survivors = pass.split("Survived:\n").nth(1).unwrap_or_default();
    assert!(
        survivors.contains("src/cart.js:2  EqualityOperator  sum >= 50 → sum > 50"),
        "{pass}"
    );
    let listed = project
        .supercov(&["runs", "latest", "mutants", "src/cart.js"])
        .succeeds();
    assert!(listed.contains("  Strong       score "), "{listed}");
    let line = listed
        .lines()
        .find(|line| line.contains("sum >= 50 → sum > 50"))
        .unwrap_or_default();
    assert!(line.contains("survived"), "{listed}");
    let killed = listed
        .lines()
        .find(|line| line.contains("trim() → name"))
        .unwrap_or_default();
    assert!(killed.contains("killed"), "{listed}");
    let only = project
        .supercov(&["runs", "latest", "mutants", "--status", "survived"])
        .succeeds();
    assert!(only.contains("sum >= 50 → sum > 50"), "{only}");
    assert!(!only.contains("trim() → name"), "{only}");
    // The table of files says how to list them, and a line's view gives
    // each mutant's verdict.
    let table = project.supercov(&["runs", "latest", "mutants"]).succeeds();
    assert!(
        table.contains("list the mutants the tests let survive: ")
            && table.contains(" --status survived"),
        "{table}"
    );
    let line = project
        .supercov(&["runs", "latest", "mutants", "src/cart.js:2"])
        .succeeds();
    assert!(line.contains("  strong: survived"), "{line}");
    let markdown = project
        .supercov(&["runs", "latest", "mutants", "--format", "markdown"])
        .succeeds();
    assert!(markdown.contains("Mutation score **"), "{markdown}");
    assert!(
        markdown
            .lines()
            .any(|line| line.contains("sum >= 50 → sum > 50") && line.contains(" | survived | ")),
        "{markdown}"
    );
    assert!(!markdown.contains("trim() → name"), "{markdown}");
}

/// `mutants test` under node:test, Mocha, Jest and AVA: each job starts the
/// run's command for one test file with the mutant on and only its tests. A
/// node:test file that asserts at its top level, with no test() in it, is a
/// test of its own, as node:test counts it.
#[cfg(unix)]
#[test]
fn mutants_test_runs_node_test_mocha_jest_and_ava_mutants_one_job_at_a_time() {
    let esm_cart = |import: &str, describe: bool| {
        let (open, close) = if describe {
            ("describe(\"cart\", () => {\n", "});\n")
        } else {
            ("", "")
        };
        format!(
            "{import}import {{ shipping, label }} from \"../src/cart.js\";\n{open}it(\"ships big orders free\", () => assert.equal(shipping(80), 0));\nit(\"charges small orders\", () => assert.equal(shipping(10), 5));\nit(\"labels\", () => assert.equal(label(\" a \"), \"A\"));\n{close}"
        )
    };
    let node = job_runner_project(
        "strong-jobs-node-test",
        "module",
        &[
            (
                "test/cart.test.js",
                &esm_cart(
                    "import assert from \"node:assert/strict\";\nimport { it } from \"node:test\";\n",
                    false,
                ),
            ),
            (
                "test/count.test.js",
                "import assert from \"node:assert/strict\";\nimport { countdown } from \"../src/cart.js\";\nassert.equal(countdown(3), 0);\n",
            ),
        ],
    );
    assert_cart_verdicts(&node, &["node", "--test"], "node:test");
    // A suite of ES modules runs each job in a fresh thread of a resident
    // Mocha.
    let mocha = job_runner_project(
        "strong-jobs-mocha",
        "module",
        &[
            (
                "test/cart.test.js",
                &esm_cart("import assert from \"node:assert/strict\";\n", true),
            ),
            (
                "test/count.test.js",
                "import assert from \"node:assert/strict\";\nimport { countdown } from \"../src/cart.js\";\nit(\"counts down\", () => assert.equal(countdown(3), 0));\n",
            ),
        ],
    );
    assert_cart_verdicts(&mocha, &["npx", "mocha", "--check-leaks"], "mocha");
    // A CommonJS suite runs in resident Mochas, its modules loaded afresh for
    // each job.
    let commonjs = job_runner_project(
        "strong-jobs-mocha-commonjs",
        "commonjs",
        &[
            (
                "test/cart.test.js",
                "const assert = require(\"node:assert/strict\");\nconst { shipping, label } = require(\"../src/cart.js\");\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => assert.equal(shipping(80), 0));\n  it(\"charges small orders\", () => assert.equal(shipping(10), 5));\n  it(\"labels\", () => assert.equal(label(\" a \"), \"A\"));\n});\n",
            ),
            (
                "test/count.test.js",
                "const assert = require(\"node:assert/strict\");\nconst { countdown } = require(\"../src/cart.js\");\nit(\"counts down\", () => assert.equal(countdown(3), 0));\n",
            ),
        ],
    );
    assert_cart_verdicts(&commonjs, &["npx", "mocha", "--check-leaks"], "mocha");
    let jest = job_runner_project(
        "strong-jobs-jest",
        "commonjs",
        &[
            (
                "test/cart.test.js",
                "const { shipping, label } = require(\"../src/cart.js\");\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\n  it(\"charges small orders\", () => expect(shipping(10)).toBe(5));\n  it(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n});\n",
            ),
            (
                "test/count.test.js",
                "const { countdown } = require(\"../src/cart.js\");\ntest(\"counts down\", () => expect(countdown(3)).toBe(0));\n",
            ),
        ],
    );
    assert_cart_verdicts(&jest, &["npx", "jest"], "jest");
    let ava = job_runner_project(
        "strong-jobs-ava",
        "module",
        &[
            (
                "test/cart.test.js",
                "import test from \"ava\";\nimport { shipping, label } from \"../src/cart.js\";\ntest(\"ships big orders free\", (t) => t.is(shipping(80), 0));\ntest(\"charges small orders\", (t) => t.is(shipping(10), 5));\ntest(\"labels\", (t) => t.is(label(\" a \"), \"A\"));\n",
            ),
            (
                "test/count.test.js",
                "import test from \"ava\";\nimport { countdown } from \"../src/cart.js\";\ntest(\"counts down\", (t) => t.is(countdown(3), 0));\n",
            ),
        ],
    );
    assert_cart_verdicts(&ava, &["npx", "ava"], "ava");
}

/// `mutants test` on a Python project under unittest: the run lists mutmut's
/// mutants and records their values (`SUPERCOV_MUTANTS=1`), and the strong
/// pass forks each mutant's tests after collection: a default's mutant, a
/// loop the mutant makes endless, code no test runs, a boundary no test
/// meets, and code a test module's import runs, which a fresh interpreter
/// runs with the mutant on.
#[cfg(unix)]
#[test]
fn mutants_test_runs_python_mutants_under_unittest() {
    let project = Project::empty("strong-python-unittest");
    project.write(".gitignore", ".supercov\n__pycache__\n");
    project.write("shop/__init__.py", "");
    project.write(
        "shop/cart.py",
        "def shipping(total, express=False):\n    if total >= 50:\n        return 0\n    fee = 5\n    if express:\n        fee += 10\n    return fee\n\n\ndef label(name):\n    return name.strip().upper()\n\n\ndef countdown(n):\n    while n > 0:\n        n -= 1\n    return n\n\n\ndef refund(total):\n    return total * 0.9 if total > 100 else total\n\n\ndef rate():\n    return 3\n",
    );
    project.write("tests/__init__.py", "");
    project.write(
        "tests/test_cart.py",
        "import unittest\nfrom shop.cart import shipping, label, countdown, rate\n\nRATE = rate()\n\n\nclass Cart(unittest.TestCase):\n    def test_free(self):\n        self.assertEqual(shipping(80), 0)\n\n    def test_paid(self):\n        self.assertEqual(shipping(10), 5)\n\n    def test_label(self):\n        self.assertEqual(label(' a '), 'A')\n\n    def test_countdown(self):\n        self.assertEqual(countdown(3), 0)\n\n    def test_rate(self):\n        self.assertEqual(RATE, 3)\n",
    );
    project.git(&["init", "-q"]);
    project.commit("cart");
    let command = [
        "--", "python3", "-m", "unittest", "discover", "-s", "tests", "-t", ".",
    ];
    // `SUPERCOV_MUTANTS=0` is a plain run: no value probe, no list.
    project
        .supercov_with(&command, &[("SUPERCOV_MUTANTS", "0")])
        .succeeds();
    let plain = project.latest();
    assert!(
        !project
            .root
            .join(format!(".supercov/runs/{plain}/mutants-listed.json"))
            .exists()
    );
    project
        .supercov_with(&command, &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let weak = project
        .supercov(&["runs", "latest", "mutants", "shop/cart.py:2", "--json"])
        .json();
    let boundary = weak["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["id"] == "shop/cart.py:2:14-2:19:EqualityOperator:>")
        .cloned()
        .unwrap_or_default();
    assert_eq!(boundary["status"], "not-infected", "{weak}");
    // A command timeout that is no number stops the pass before it runs, and
    // leaves no verdict.
    let refused = project.supercov_with(
        &["runs", "latest", "mutants", "test"],
        &[("SUPERCOV_COMMAND_TIMEOUT_MS", "soon")],
    );
    let said = refused.stderr();
    assert_ne!(refused.code(), 0, "{said}");
    assert!(said.contains("SUPERCOV_COMMAND_TIMEOUT_MS"), "{said}");
    let ran = project.supercov_with(
        &["runs", "latest", "mutants", "test", "--json"],
        &[("SUPERCOV_STRONG_WORKERS", "2")],
    );
    let said = ran.stderr();
    let reply = ran.json();
    assert_eq!(reply["summary"]["error"], 0, "{reply}\n{said}");
    assert_eq!(reply["passes"][0]["runner"], "unittest", "{reply}");
    let statuses = strong_statuses(&project);
    for (id, status) in [
        // `express=True`: the default a call that names no `express` gets.
        ("shop/cart.py:1:29-1:34:BooleanLiteral:True", "killed"),
        ("shop/cart.py:2:14-2:19:EqualityOperator:>", "survived"),
        ("shop/cart.py:6:9-6:18:AugmentedAssignment:=", "no-coverage"),
        ("shop/cart.py:2:17-2:19:NumberLiteral:51", "survived"),
        ("shop/cart.py:11:12-11:32:MethodExpression:lower", "killed"),
        ("shop/cart.py:16:9-16:15:AssignmentOperator:+=", "timeout"),
        ("shop/cart.py:21:12-21:49:IfExpression:true", "no-coverage"),
        // Called while the test module loads: run with the mutant on from
        // the interpreter's start.
        ("shop/cart.py:25:12-25:13:NumberLiteral:4", "killed"),
    ] {
        assert_eq!(
            statuses.get(id).map(String::as_str),
            Some(status),
            "{id}: {statuses:?}\n{said}"
        );
    }
}

/// `mutants test` under bun:test: Bun's runner loads every test file it is
/// given into one process, so each job names its file.
#[cfg(unix)]
#[test]
fn mutants_test_runs_bun_test_mutants_one_job_at_a_time() {
    if std::process::Command::new("bun")
        .arg("--version")
        .output()
        .is_err()
    {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BUN").is_none(),
            "Bun is required"
        );
        eprintln!("skipping: Bun is unavailable");
        return;
    }
    let bun = job_runner_project(
        "strong-jobs-bun",
        "module",
        &[
            (
                "test/cart.test.js",
                "import { expect, test } from \"bun:test\";\nimport { shipping, label } from \"../src/cart.js\";\ntest(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\ntest(\"charges small orders\", () => expect(shipping(10)).toBe(5));\ntest(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n",
            ),
            (
                "test/count.test.js",
                "import { expect, test } from \"bun:test\";\nimport { countdown } from \"../src/cart.js\";\ntest(\"counts down\", () => expect(countdown(3)).toBe(0));\n",
            ),
        ],
    );
    assert_cart_verdicts(&bun, &["bun", "test"], "bun:test");
}

/// `mutants test` under node-tap, installed from the registry as the
/// failure-output check installs it: each test file is a process of tap's,
/// and a file that asserts at its top level is a test of its own.
#[cfg(unix)]
#[test]
fn mutants_test_runs_tap_mutants_one_job_at_a_time() {
    let tap = Project::empty("strong-jobs-tap");
    tap.write("package.json", r#"{ "name": "cart", "type": "module" }"#);
    let installed = std::process::Command::new("npm")
        .args(["install", "--no-audit", "--no-fund", "--silent", "tap@21"])
        .current_dir(&tap.root)
        .output()
        .is_ok_and(|output| output.status.success());
    if !installed {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_TAP").is_none(),
            "tap could not be installed"
        );
        eprintln!("skipping: tap could not be installed");
        return;
    }
    let project = job_runner_project(
        "strong-jobs-tap-cart",
        "module",
        &[
            (
                "test/cart.test.js",
                "import t from \"tap\";\nimport { shipping, label } from \"../src/cart.js\";\nt.test(\"ships big orders free\", async (t) => t.equal(shipping(80), 0));\nt.test(\"charges small orders\", async (t) => t.equal(shipping(10), 5));\nt.test(\"labels\", async (t) => t.equal(label(\" a \"), \"A\"));\n",
            ),
            (
                "test/count.test.js",
                "import t from \"tap\";\nimport { countdown } from \"../src/cart.js\";\nt.equal(countdown(3), 0);\n",
            ),
        ],
    );
    // tap's own packages beside the repository's.
    std::fs::remove_file(project.root.join("node_modules")).unwrap();
    std::os::unix::fs::symlink(
        tap.root.join("node_modules"),
        project.root.join("node_modules"),
    )
    .unwrap();
    assert_cart_verdicts(&project, &["npx", "tap", "--disable-coverage"], "tap");
}

/// `mutants test` under Vitest's Browser Mode: the job's mutant is switched
/// on in the page, before the test file loads, and the browser's tests are
/// planned under `vitest-browser`.
#[cfg(unix)]
#[test]
fn mutants_test_runs_vitest_browser_mode_mutants_one_job_at_a_time() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let browser = job_runner_project(
        "strong-jobs-vitest-browser",
        "module",
        &[
            (
                "vitest.config.js",
                "import { defineConfig } from \"vitest/config\";\nimport { playwright } from \"@vitest/browser-playwright\";\nexport default defineConfig({ test: { browser: { enabled: true, provider: playwright(), headless: true, instances: [{ browser: \"chromium\" }] } } });\n",
            ),
            (
                "test/cart.test.js",
                "import { expect, it } from \"vitest\";\nimport { shipping, label } from \"../src/cart.js\";\nit(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\nit(\"charges small orders\", () => expect(shipping(10)).toBe(5));\nit(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n",
            ),
            (
                "test/count.test.js",
                "import { expect, it } from \"vitest\";\nimport { countdown } from \"../src/cart.js\";\nit(\"counts down\", () => expect(countdown(3)).toBe(0));\n",
            ),
        ],
    );
    let plan = {
        browser
            .supercov_with(
                &["--", "npx", "vitest", "run"],
                &[("SUPERCOV_MUTANTS", "1")],
            )
            .succeeds();
        browser
            .supercov(&["runs", "latest", "mutants", "test", "--plan", "--json"])
            .json()
    };
    assert!(
        plan["tests"]
            .as_array()
            .unwrap()
            .iter()
            .all(|test| test["runner"] == "vitest-browser"),
        "{plan}"
    );
    assert_cart_verdicts(&browser, &["npx", "vitest", "run"], "vitest-browser");
    // A run of node tests and browser tests: its node tests run as jobs
    // beside the browser's.
    let mixed = job_runner_project(
        "strong-jobs-vitest-mixed",
        "module",
        &[
            (
                "vitest.config.js",
                "import { defineConfig } from \"vitest/config\";\nimport { playwright } from \"@vitest/browser-playwright\";\nexport default defineConfig({ test: { projects: [\n  { test: { name: \"node\", include: [\"test/cart.test.js\"] } },\n  { test: { name: \"browser\", include: [\"test/count.test.js\"], browser: { enabled: true, provider: playwright(), headless: true, instances: [{ browser: \"chromium\" }] } } },\n] } });\n",
            ),
            (
                "test/cart.test.js",
                "import { expect, it } from \"vitest\";\nimport { shipping, label } from \"../src/cart.js\";\nit(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\nit(\"charges small orders\", () => expect(shipping(10)).toBe(5));\nit(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n",
            ),
            (
                "test/count.test.js",
                "import { expect, it } from \"vitest\";\nimport { countdown } from \"../src/cart.js\";\nit(\"counts down\", () => expect(countdown(3)).toBe(0));\n",
            ),
        ],
    );
    assert_cart_verdicts(&mixed, &["npx", "vitest", "run"], "vitest node and browser");
}

/// Rust compiled to wasm that node:test loads: the Rust run beside the
/// JavaScript one lists the crate's mutants, and `mutants test` runs them
/// under the JavaScript tests, the copy's crate built with them switched in
/// and each wasm instance handed the active mutant. Needs wasm-bindgen and
/// the wasm32 target; a job that installed them sets
/// `SUPERCOV_REQUIRE_RUST_WASM=1`.
#[cfg(unix)]
#[test]
fn rust_compiled_to_wasm_under_node_tests_runs_its_mutants() {
    let tools = std::process::Command::new("wasm-bindgen")
        .arg("--version")
        .output()
        .is_ok_and(|output| output.status.success())
        && std::process::Command::new("rustup")
            .args(["target", "list", "--installed"])
            .output()
            .is_ok_and(|output| {
                String::from_utf8_lossy(&output.stdout).contains("wasm32-unknown-unknown")
            });
    if !tools {
        assert!(
            std::env::var("SUPERCOV_REQUIRE_RUST_WASM").as_deref() != Ok("1"),
            "wasm-bindgen or the wasm32 target is missing where the job installed them"
        );
        eprintln!("skipping: needs wasm-bindgen and the wasm32-unknown-unknown target");
        return;
    }
    let project = Project::empty("wasm-node-mutants");
    project.write(
        "rust/Cargo.toml",
        "[workspace]\n\n[package]\nname = \"grades\"\nversion = \"0.1.0\"\nedition = \"2021\"\n\n[lib]\ncrate-type = [\"cdylib\"]\n\n[dependencies]\nwasm-bindgen = \"=0.2.129\"\n",
    );
    project.write(
        "rust/src/lib.rs",
        "use wasm_bindgen::prelude::*;\n\n#[wasm_bindgen]\npub fn grade(score: u32, curved: bool) -> String {\n    if score >= 90 || (curved && score >= 85) {\n        \"A\".into()\n    } else if score >= 50 {\n        \"pass\".into()\n    } else {\n        \"fail\".into()\n    }\n}\n",
    );
    project.write(
        "build.sh",
        "set -e\ncd rust\ncargo build -q --target wasm32-unknown-unknown --release\nwasm-bindgen --target nodejs --out-dir ../pkg target/wasm32-unknown-unknown/release/grades.wasm\n",
    );
    project.write(
        "package.json",
        r#"{ "name": "grades", "private": true, "scripts": { "test": "sh build.sh && node --test" } }"#,
    );
    project.write(
        "test/grades.test.mjs",
        "import test from \"node:test\";\nimport assert from \"node:assert/strict\";\nimport { createRequire } from \"node:module\";\nconst { grade } = createRequire(import.meta.url)(\"../pkg/grades.js\");\n\ntest(\"a curved score is an A\", () => {\n  assert.equal(grade(87, true), \"A\");\n});\n\ntest(\"a low score fails\", () => {\n  assert.equal(grade(10, false), \"fail\");\n});\n",
    );
    project.write(".gitignore", "pkg\nrust/target\n.supercov\n");
    let locked = std::process::Command::new("cargo")
        .args(["generate-lockfile", "-q"])
        .current_dir(project.root.join("rust"))
        .status()
        .unwrap();
    assert!(locked.success());
    project.git(&["init", "-q"]);
    project.commit("grades");
    project.supercov(&["--", "npm", "test"]).succeeds();
    let runs = project.supercov(&["runs", "--json"]).json();
    let rust = runs["data"]["runs"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|run| run["id"].as_str())
        .find(|id| {
            project
                .supercov(&["runs", id, "decision", "rust/src/lib.rs:5"])
                .code()
                == 0
        })
        .expect("a Rust run beside the JavaScript one")
        .to_owned();
    let reply = project
        .supercov(&["runs", &rust, "mutants", "test", "--json"])
        .json();
    // `&&` to `||` in `(curved && score >= 85)` changes neither test's
    // outcome; every other mutant fails one.
    assert_eq!(reply["summary"]["killed"], 6, "{reply}");
    assert_eq!(reply["summary"]["survived"], 1, "{reply}");
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    // A pass that cannot switch the crate's mutants in ends, saying why.
    std::fs::remove_file(
        project
            .root
            .join(".supercov/runs")
            .join(&rust)
            .join("strong-mutation.json"),
    )
    .unwrap();
    let failed = project.supercov_with(
        &["runs", &rust, "mutants", "test"],
        &[(
            "SUPERCOV_TEST_FAULT",
            "fs.read#rust-strong.switch-wasm.read",
        )],
    );
    assert_ne!(failed.code(), 0, "{}", failed.stderr());
    assert!(failed.stderr().contains("plan.json"), "{}", failed.stderr());
}

/// Two inline snapshots in one file, and a test that fakes the clock: the
/// measured run passes as the suite does alone (the snapshots keep their own
/// places; a duration is read from the real clock), and the strong pass runs.
#[cfg(unix)]
#[test]
fn inline_snapshots_and_faked_clocks_measure_and_mutate_as_the_suite_runs() {
    let project = vitest_mutants_project("strong-inline-snapshots");
    project.write(
        "test/snapshots.test.js",
        "import { expect, it, vi } from \"vitest\";\nimport { shipping, label } from \"../src/cart.js\";\nit(\"snapshots shipping\", () => {\n  expect(shipping(80)).toMatchInlineSnapshot(`0`);\n  expect(shipping(10)).toMatchInlineSnapshot(`5`);\n});\nit(\"labels under a faked clock\", () => {\n  vi.useFakeTimers();\n  vi.setSystemTime(0);\n  expect(label(\" b \")).toMatchInlineSnapshot(`\"B\"`);\n  vi.useRealTimers();\n});\n",
    );
    project.commit("snapshots");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    assert!(reply["summary"]["killed"].as_u64().unwrap() >= 8, "{reply}");
}

/// A server Playwright starts from its config's folder, which is not the
/// project's root, and which imports `@playwright/test` itself (a mock
/// server that drives a browser): it is given the same Playwright the tests
/// are, found from the project's root, so it starts and the tests are
/// recorded.
#[cfg(unix)]
#[test]
fn a_web_server_started_in_the_config_s_folder_can_import_playwright() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args([
            "--input-type=module",
            "-e",
            "await import('@playwright/test')",
        ])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright is required"
        );
        eprintln!("skipping: Playwright is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("playwright-server-in-config-folder");
    project.write(
        "package.json",
        r#"{ "name": "server-in-config-folder", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "src/greeting.js",
        "export function greeting(name) {\n  return name ? `hello ${name}` : \"hello\";\n}\n",
    );
    // Started with the config's folder as its working directory.
    project.write(
        "tests/e2e/mocks/server.mjs",
        "import http from \"node:http\";\nimport { chromium } from \"@playwright/test\";\nimport { greeting } from \"../../../src/greeting.js\";\nif (typeof chromium.launch !== \"function\") throw new Error(\"no chromium\");\nhttp.createServer((request, response) => {\n  const url = new URL(request.url, \"http://local\");\n  response.end(greeting(url.searchParams.get(\"name\")));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "tests/e2e/playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"specs\",\n  workers: 1,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node mocks/server.mjs\", url: \"http://127.0.0.1:{port}/\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    project.write(
        "tests/e2e/specs/greeting.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"greets\", async ({ request }) => {\n  expect(await (await request.get(\"/?name=ada\")).text()).toBe(\"hello ada\");\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("server in the config's folder");
    let measured = project.supercov(&[
        "--",
        "npx",
        "playwright",
        "test",
        "-c",
        "tests/e2e/playwright.config.js",
    ]);
    assert!(
        !measured.stderr().contains("was not able to start"),
        "{}",
        measured.stderr()
    );
    measured.succeeds();
    let summary = project.supercov(&["runs", "latest"]).succeeds();
    contains_all(&summary, &["Total       1", "Passed      1"]);
}

/// `mutants test` over a Playwright run against a Node server: the workers
/// of one Playwright invocation each test their own mutant against one
/// server, the mutant carried with each attempt's requests and switched on
/// in its pages; a mutant of the server's top level runs alone, with the
/// server started with it switched on; the controls, runs with no mutant
/// after a kill, pass; and the pass says as it goes what it does.
#[cfg(unix)]
#[test]
fn mutants_test_runs_playwright_mutants_per_request_and_per_server_start() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    // The server: its routes and files in support/, which is not measured,
    // and the code under test in server/. It notes what it served, outside
    // the project: its process, and the worker and mutant each request's
    // attempt named.
    let served = project.root.with_extension("served.jsonl");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { appendFileSync, readFileSync } from \"node:fs\";\nimport { answer } from \"../server/app.js\";\nconst files = { \"/\": \"../public/index.html\", \"/page.js\": \"../public/page.js\" };\n// One fault switch for the whole server, as a harness's per-slot fault\n// rules: a test that turns it on must not run beside another test.\nlet fault = false;\nhttp.createServer((request, response) => {\n  const cookie = /(?:^|;\\s*)__supercov_scope=([^;]*)/.exec(request.headers.cookie ?? \"\");\n  const scope = new URLSearchParams(request.headers[\"x-supercov-scope\"] ?? (cookie ? decodeURIComponent(cookie[1]) : \"\"));\n  appendFileSync(process.env.SERVED_LOG, JSON.stringify({ pid: process.pid, worker: scope.get(\"w\"), mutant: scope.get(\"m\"), path: request.url }) + \"\\n\");\n  const url = new URL(request.url, \"http://local\");\n  if (url.pathname === \"/fault\") {\n    fault = url.searchParams.get(\"on\") === \"1\";\n    return response.end();\n  }\n  if (url.pathname === \"/source\")\n    return response.end(readFileSync(new URL(\"../server/app.js\", import.meta.url)));\n  if (fault && url.pathname === \"/total\") {\n    response.statusCode = 503;\n    return response.end(\"faulted\");\n  }\n  try {\n    response.end(files[url.pathname] ? readFileSync(new URL(files[url.pathname], import.meta.url)) : answer(url));\n  } catch (error) {\n    response.statusCode = 500;\n    response.end(String(error));\n  }\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "server/app.js",
        "const GREETING = \"hello\";\n\nexport function total(quantity) {\n  console.log(`served ${quantity}`);\n  return quantity >= 3 ? quantity * 9 : quantity * 10;\n}\n\nexport function answer(url) {\n  return url.pathname === \"/greeting\" ? GREETING : String(total(Number(url.searchParams.get(\"q\"))));\n}\n\nexport const dynamic = \"force-dynamic\";\n",
    );
    // Reached by no test: the strong pass leaves it as written.
    project.write("server/unused.js", "export const unused = (a) => a + 1;\n");
    project.write(
        "public/index.html",
        "<!doctype html><p id=\"out\"></p><script src=\"/page.js\"></script>\n",
    );
    project.write(
        "public/page.js",
        "function shout(text) {\n  return text.toUpperCase();\n}\ndocument.getElementById(\"out\").textContent = shout(\"hi\");\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 4,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/greeting\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\", SERVED_LOG: {:?} }} }},\n}};\n",
            served.display().to_string()
        ),
    );
    project.write(
        "tests/api.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"totals\", async ({ request }) => {\n  expect(await (await request.get(\"/total?q=5\")).text()).toBe(\"45\");\n  expect(await (await request.get(\"/total?q=1\")).text()).toBe(\"10\");\n});\ntest(\"greets\", async ({ request }) => {\n  expect(await (await request.get(\"/greeting\")).text()).toBe(\"hello\");\n});\ntest(\"refuses while faulted @fault\", async ({ request }) => {\n  expect(await (await request.get(\"/total?q=2\")).text()).toBe(\"20\");\n  await request.get(\"/fault?on=1\");\n  await new Promise((done) => setTimeout(done, 400));\n  expect((await request.get(\"/total?q=1\")).status()).toBe(503);\n  await request.get(\"/fault?on=0\");\n});\ntest(\"keeps its segment config a literal\", async ({ request }) => {\n  expect(await (await request.get(\"/source\")).text()).toContain('export const dynamic = \"force-dynamic\";');\n});\n",
    );
    project.write(
        "tests/page.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"shouts\", async ({ page }) => {\n  await page.goto(\"/\");\n  await expect(page.locator(\"#out\")).toHaveText(\"HI\", { timeout: 12000 });\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("strong playwright");
    let roots = [("SUPERCOV_SOURCE_ROOTS", "server,public")];
    // Measured with the mutants' probes: their values decide some mutants
    // without running them.
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots[0], ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let _ = std::fs::remove_file(&served);
    let ran = project.supercov_with(
        &["runs", "latest", "mutants", "test", "--json"],
        &[roots[0], ("SUPERCOV_PROGRESS_INTERVAL_MS", "300")],
    );
    let said = ran.stderr();
    let reply = ran.json();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let shown = mutants
        .iter()
        .map(|mutant| format!("{} {} {}", mutant["id"], mutant["status"], mutant["strong"]))
        .collect::<Vec<_>>()
        .join("\n");
    // What each pass wrote and each attempt claimed, for a failure to show.
    let mut passes = String::new();
    for work in std::fs::read_dir(project.root.join(".supercov/strong"))
        .into_iter()
        .flatten()
        .flatten()
    {
        passes.push_str(
            &std::fs::read_to_string(work.path().join("results.jsonl")).unwrap_or_default(),
        );
        for pass in std::fs::read_dir(work.path().join("playwright"))
            .into_iter()
            .flatten()
            .flatten()
        {
            for attempt in std::fs::read_dir(pass.path().join("attempts"))
                .into_iter()
                .flatten()
                .flatten()
            {
                passes.push_str(&format!(
                    "{} {}\n",
                    pass.file_name().to_string_lossy(),
                    std::fs::read_to_string(attempt.path()).unwrap_or_default()
                ));
            }
        }
    }
    let context = format!("{reply}\n{shown}\n{said}\n{passes}");
    // Each pass's time, for whoever weighs the cost of confirming kills.
    eprintln!("strong passes: {}", reply["passes"]);
    // The one mutant on a line, by its file, line, mutator and descriptor.
    let strong = |file: &str, line: u32, ending: &str| {
        let found = mutants
            .iter()
            .filter(|mutant| {
                let id = mutant["id"].as_str().unwrap();
                id.starts_with(&format!("{file}:{line}:")) && id.ends_with(ending)
            })
            .collect::<Vec<_>>();
        assert_eq!(found.len(), 1, "{file}:{line} {ending}\n{context}");
        found[0]["strong"].clone()
    };
    // The one error: the segment config's value stays a literal Next.js
    // can read, and its mutant has no switch.
    assert_eq!(reply["summary"]["error"], 1, "{context}");
    let segment = strong("server/app.js", 12, ":StringLiteral:empty");
    assert_eq!(segment["status"], "error", "{context}");
    assert!(
        segment["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("next-segment-config")),
        "{context}"
    );
    // Only the files with mutants to run get switches.
    assert!(
        said.contains("switches in 2 of 3 source file(s)"),
        "{context}"
    );
    // A server-side mutant, killed by its own requests, with why.
    let always = strong("server/app.js", 5, ":ConditionalExpression:true");
    assert_eq!(always["status"], "killed", "{context}");
    assert!(
        always["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("Expected")),
        "{context}"
    );
    // Killed by the first test that took it: its other candidates never ran.
    let route = strong("server/app.js", 9, ":EqualityOperator:!==");
    assert_eq!(route["status"], "killed", "{context}");
    assert_eq!(route["tests"], 1, "{context}");
    // A page-side mutant the page shows: its assertion waits 12 s, its own
    // timeout, longer than the attempt's limit (1.5 x its baseline + 5 s)
    // on an idle machine and shorter on a loaded one. The attempt runs to
    // the assertion's own end either way, and the assertion kills it: it
    // was a timeout where the limit came first, and a kill where it did not.
    let lower = strong("public/page.js", 2, ":MethodExpression:toLowerCase");
    assert_eq!(lower["status"], "killed", "{context}");
    assert!(lower["killedBy"].as_str().is_some(), "{lower}\n{context}");
    assert!(
        lower["reason"].as_str().is_some_and(
            |reason| reason.contains("toHaveText") && reason.contains("Timeout: 12000ms")
        ),
        "{context}"
    );
    assert!(lower["durationMs"].as_u64() >= Some(12_000), "{context}");
    // Run, and no test tells: the log line. Its tests share the server's
    // fault switch with the @fault test, which the measured run never ran
    // beside them; neither does the strong pass, so nothing kills it.
    let logged = strong("server/app.js", 4, ":StringLiteral:empty");
    assert_eq!(logged["status"], "survived", "{context}");
    assert!(logged["tests"].as_u64() > Some(0), "{context}");
    // No request gives `total` 3: decided without running.
    let boundary = strong("server/app.js", 5, ":EqualityOperator:>");
    assert_eq!(boundary["status"], "survived", "{context}");
    assert_eq!(boundary["tests"], 0, "{context}");
    // The server's top level: run alone, the server started with it.
    let greeting = strong("server/app.js", 1, ":StringLiteral:empty");
    assert_eq!(greeting["status"], "killed", "{context}");
    assert!(
        greeting["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("ran alone")),
        "{context}"
    );
    // Controls ran after the kills, and none failed.
    let main = reply["passes"]
        .as_array()
        .unwrap()
        .iter()
        .find(|pass| pass["pass"] == "main")
        .unwrap_or_else(|| panic!("no main pass\n{context}"))
        .clone();
    assert!(
        main["controls"]["ran"].as_u64() > Some(0),
        "{main}\n{context}"
    );
    assert_eq!(
        main["controls"]["failed"],
        serde_json::json!([]),
        "{context}"
    );
    // The pass said what it did as it went: the round, its attempts and
    // what ran.
    assert!(
        said.contains("[supercov]   main round, 1 invocation(s): ")
            && said.contains(" mutant attempt(s), "),
        "{context}"
    );
    // The files the measured run ran one test at a time run so here too.
    assert_eq!(main["serialFiles"], 2, "{main}\n{context}");
    // One server process served two workers' attempts, each with a mutant
    // of its own.
    let log = std::fs::read_to_string(&served).unwrap_or_default();
    let requests = log
        .lines()
        .filter_map(|line| serde_json::from_str::<serde_json::Value>(line).ok())
        .filter(|request| {
            request["mutant"]
                .as_str()
                .is_some_and(|mutant| mutant != "-")
        })
        .collect::<Vec<_>>();
    let shared = requests.iter().any(|one| {
        requests.iter().any(|other| {
            one["pid"] == other["pid"]
                && one["worker"] != other["worker"]
                && one["mutant"] != other["mutant"]
        })
    });
    let _ = std::fs::remove_file(&served);
    assert!(shared, "{log}\n{context}");
}

/// A module-level table a server builds as it starts, read by few of a
/// browser suite's tests: each of its mutants has for candidates the tests
/// that read its value, not every test of the run, and the plan says how
/// far that narrowed them. A value read while the server's modules loaded,
/// and a value no literal holds, keep every test. Soundness: the same suite
/// measured without the probes plans every test for each, and every mutant
/// that broad pass kills, the narrowed one kills, with the broad killer
/// among its candidates.
#[cfg(unix)]
#[test]
fn a_module_level_value_s_mutants_run_against_the_tests_that_read_it() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-module-values");
    project.write(
        "package.json",
        r#"{ "name": "strong-module-values", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    let words = "export const WORDS = {\n  en: { hello: \"Hello\", bye: \"Bye\" },\n  fr: { hello: \"Bonjour\", bye: \"Au revoir\" },\n};\nconst LETTERS = { a: \"A\" };\nexport const COPIED = LETTERS.a;\nexport const PLAIN = \"plain\";\nexport function word(lang, key) {\n  return WORDS[lang][key];\n}\n";
    project.write("server/words.js", words);
    // A word the mutant took away is a 500 for the request that read it.
    // Uncaught, it took the server down, and a test that reads no word,
    // its request in flight on the other worker, failed first and was
    // named the broad pass's killer.
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { word, COPIED, PLAIN } from \"../server/words.js\";\nhttp.createServer((request, response) => {\n  const url = new URL(request.url, \"http://local\");\n  if (url.pathname === \"/word\") {\n    try {\n      return response.end(word(url.searchParams.get(\"lang\"), url.searchParams.get(\"key\")));\n    } catch (error) {\n      response.statusCode = 500;\n      return response.end(String(error));\n    }\n  }\n  if (url.pathname === \"/copied\") return response.end(COPIED);\n  if (url.pathname === \"/plain\") return response.end(PLAIN);\n  response.end(\"other\");\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 2,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/ready\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    project.write(
        "tests/words.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"greets in English\", async ({ request }) => {\n  expect(await (await request.get(\"/word?lang=en&key=hello\")).text()).toBe(\"Hello\");\n});\ntest(\"says goodbye in French\", async ({ request }) => {\n  expect(await (await request.get(\"/word?lang=fr&key=bye\")).text()).toBe(\"Au revoir\");\n});\n",
    );
    project.write(
        "tests/other.spec.js",
        "import { test, expect } from \"@playwright/test\";\nfor (const n of [1, 2, 3]) {\n  test(`answers otherwise ${n}`, async ({ request }) => {\n    expect(await (await request.get(\"/other\")).text()).toBe(\"other\");\n  });\n}\ntest(\"copies a letter\", async ({ request }) => {\n  expect(await (await request.get(\"/copied\")).text()).toBe(\"A\");\n});\ntest(\"answers plainly\", async ({ request }) => {\n  expect(await (await request.get(\"/plain\")).text()).toBe(\"plain\");\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("module-level values");
    let roots = ("SUPERCOV_SOURCE_ROOTS", "server");
    // Each run's plan, and its pass's verdicts, by mutant id.
    let measure_and_test = |probes: bool| {
        let mut env = vec![roots];
        if probes {
            env.push(("SUPERCOV_MUTANTS", "1"));
        }
        project
            .supercov_with(&["--", "npx", "playwright", "test"], &env)
            .succeeds();
        let plan = project
            .supercov_with(
                &["runs", "latest", "mutants", "test", "--plan", "--json"],
                &[roots],
            )
            .json();
        let text = project
            .supercov_with(&["runs", "latest", "mutants", "test", "--plan"], &[roots])
            .succeeds();
        let ran = project.supercov_with(&["runs", "latest", "mutants", "test", "--json"], &[roots]);
        let said = ran.stderr();
        let reply = ran.json();
        let verdicts = project
            .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
            .json()["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .map(|mutant| {
                (
                    mutant["id"].as_str().unwrap().to_owned(),
                    mutant["strong"].clone(),
                )
            })
            .collect::<std::collections::BTreeMap<_, _>>();
        (plan, text, reply, said, verdicts)
    };
    let (plan, text, reply, said, narrowed) = measure_and_test(true);
    let context = format!("{plan}\n{reply}\n{said}");
    let tests = plan["tests"].as_array().unwrap().clone();
    // The mutant of `text` on its line, by its mutator.
    let planned = |text: &str, mutator: &str| {
        let (line, column) = words
            .lines()
            .enumerate()
            .find_map(|(line, source)| source.find(text).map(|at| (line + 1, at + 1)))
            .unwrap();
        let prefix = format!(
            "server/words.js:{line}:{column}-{line}:{}:{mutator}:",
            column + text.len()
        );
        plan["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"].as_str().unwrap().starts_with(&prefix))
            .unwrap_or_else(|| panic!("{prefix}\n{context}"))
            .clone()
    };
    let names = |mutant: &serde_json::Value| {
        let mut names = mutant["candidates"]
            .as_array()
            .unwrap()
            .iter()
            .map(|candidate| {
                tests[candidate["test"].as_u64().unwrap() as usize]["title"]
                    .as_str()
                    .unwrap()
                    .to_owned()
            })
            .collect::<Vec<_>>();
        names.sort();
        names
    };
    // The English greeting: the one test that read it, of the seven that
    // ran with the server that loaded it.
    let hello = planned("\"Hello\"", "StringLiteral");
    assert_eq!(names(&hello), ["greets in English"], "{context}");
    assert_eq!(
        hello["narrowed"],
        serde_json::json!({"from": 7, "to": 1}),
        "{context}"
    );
    let goodbye = planned("\"Au revoir\"", "StringLiteral");
    assert_eq!(names(&goodbye), ["says goodbye in French"], "{context}");
    // Read by no test: decided without running it.
    let bonjour = planned("\"Bonjour\"", "StringLiteral");
    assert_eq!(bonjour["decided"], "survived", "{context}");
    assert_eq!(bonjour["reason"], "no-test-read-it", "{context}");
    // The English words replaced whole: what reads English.
    let english = planned("{ hello: \"Hello\", bye: \"Bye\" }", "ObjectLiteral");
    assert_eq!(names(&english), ["greets in English"], "{context}");
    // Copied while the module loaded: every test stays.
    let letter = planned("\"A\"", "StringLiteral");
    assert_eq!(names(&letter).len(), 7, "{context}");
    assert_eq!(letter["narrowed"]["escaped"], true, "{context}");
    // No literal holds it: every test.
    let plain = planned("\"plain\"", "StringLiteral");
    assert_eq!(names(&plain).len(), 7, "{context}");
    assert!(plain["narrowed"].is_null(), "{context}");
    // The plan and the pass say so.
    let summary = &plan["summary"]["narrowed"];
    assert!(summary["mutants"].as_u64() > Some(3), "{context}");
    assert_eq!(summary["escaped"], 2, "{context}");
    assert!(
        summary["candidatesAfter"].as_u64() < summary["candidatesBefore"].as_u64(),
        "{context}"
    );
    assert!(
        text.contains("module-level mutant(s) to the tests that read their value"),
        "{text}"
    );
    assert_eq!(reply["summary"]["narrowed"], *summary, "{context}");
    // The same suite measured without the probes: every module-level mutant
    // has every test for a candidate.
    let (broad_plan, _, broad_reply, broad_said, broad) = measure_and_test(false);
    let broad_context = format!("{broad_plan}\n{broad_reply}\n{broad_said}\n{context}");
    assert!(
        broad_plan["summary"]["narrowed"].is_null(),
        "{broad_context}"
    );
    let module_level = plan["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|mutant| mutant["function"].is_null())
        .collect::<Vec<_>>();
    assert_eq!(module_level.len(), 10, "{broad_context}");
    let mut killed = 0;
    for mutant in module_level {
        let id = mutant["id"].as_str().unwrap();
        let (narrow, wide) = (&narrowed[id], &broad[id]);
        if wide["status"] != "killed" {
            continue;
        }
        killed += 1;
        assert_eq!(narrow["status"], "killed", "{id}\n{broad_context}");
        let killer = wide["killedBy"].as_str().unwrap();
        let candidate = mutant["candidates"]
            .as_array()
            .unwrap()
            .iter()
            .any(|candidate| tests[candidate["test"].as_u64().unwrap() as usize]["id"] == killer);
        assert!(
            candidate,
            "{id}: {killer} is not a candidate\n{broad_context}"
        );
    }
    assert!(killed >= 6, "{broad_context}");
}

/// `mutants test` over Playwright tests that reach the server without a
/// page navigation: a request context the test makes itself, the page's
/// own `request`, Node's `fetch` and `http`, a routed request
/// `route.fetch` sends again, and `curl` in a child process, which carries
/// no test's name at all and is sent while another test runs. Each route's
/// mutant is killed by the one test that reaches it; so is an arrow defined
/// at the module's top level and mutated whole, whose switch the server
/// evaluates once, as it loads the module, whatever mutant a request names.
/// What survives only changes a log line, and is counted as such.
#[cfg(unix)]
#[test]
fn mutants_test_kills_server_mutants_tests_reach_without_a_page() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    let curl = std::process::Command::new("curl")
        .arg("--version")
        .output()
        .is_ok_and(|output| output.status.success());
    if !available || !curl {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright, Chromium and curl are required"
        );
        eprintln!("skipping: Playwright, Chromium or curl is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright-outside-pages");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-outside-pages", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { routes } from \"../server/app.js\";\nhttp.createServer((request, response) => {\n  const url = new URL(request.url, \"http://local\");\n  const route = routes[url.pathname.slice(1)];\n  if (!route) {\n    response.statusCode = 404;\n    return response.end(\"none\");\n  }\n  response.end(String(route(Number(url.searchParams.get(\"q\")))));\n}).listen(Number(process.env.PORT));\n",
    );
    // Each route's own arithmetic, and `context` an arrow at the module's
    // top level; `fetch` logs what no test reads.
    project.write(
        "server/app.js",
        "export const routes = {\n  context: (q) => q * 2,\n  page(q) {\n    return q * 3;\n  },\n  fetch(q) {\n    console.info(`fetched ${q}`, q + 1);\n    return q * 4;\n  },\n  http(q) {\n    return q * 5;\n  },\n  route(q) {\n    return q * 6;\n  },\n  curl(q) {\n    return q * 7;\n  },\n  ready() {\n    return \"ready\";\n  },\n};\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 2,\n  fullyParallel: true,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/ready\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    project.write(
        "tests/outside.spec.js",
        concat!(
            "import { test, expect, request as playwrightRequest } from \"@playwright/test\";\n",
            "test(\"a request context of its own\", async ({ baseURL }) => {\n",
            "  const api = await playwrightRequest.newContext({ baseURL });\n",
            "  expect(await (await api.get(\"/context?q=5\")).text()).toBe(\"10\");\n",
            "  await api.dispose();\n",
            "});\n",
            "test(\"the page's request\", async ({ page }) => {\n",
            "  expect(await (await page.request.get(\"/page?q=5\")).text()).toBe(\"15\");\n",
            "});\n",
            "test(\"node fetch\", async ({ baseURL }) => {\n",
            "  expect(await (await fetch(`${baseURL}/fetch?q=5`)).text()).toBe(\"20\");\n",
            "});\n",
            "test(\"node http\", async ({ baseURL }) => {\n",
            "  const http = await import(\"node:http\");\n",
            "  const body = await new Promise((done, fail) => http.get(`${baseURL}/http?q=5`, (response) => {\n",
            "    let text = \"\";\n",
            "    response.on(\"data\", (chunk) => (text += chunk)).on(\"end\", () => done(text));\n",
            "  }).on(\"error\", fail));\n",
            "  expect(body).toBe(\"25\");\n",
            "});\n",
            "test(\"a routed fetch\", async ({ page, baseURL }) => {\n",
            "  await page.route(\"**/route*\", async (route) => {\n",
            "    const response = await route.fetch();\n",
            "    await route.fulfill({ response, body: `<p id=\"out\">${await response.text()}</p>`, contentType: \"text/html\" });\n",
            "  });\n",
            "  await page.goto(`${baseURL}/route?q=5`);\n",
            "  await expect(page.locator(\"#out\")).toHaveText(\"30\");\n",
            "});\n",
        ),
    );
    // curl's request names no test, and the other worker's test runs all
    // the while: it is no test's by time.
    project.write(
        "tests/child.spec.js",
        concat!(
            "import { test, expect } from \"@playwright/test\";\n",
            "import { execFileSync } from \"node:child_process\";\n",
            "test(\"a child process\", async ({ baseURL }) => {\n",
            "  await new Promise((done) => setTimeout(done, 500));\n",
            "  expect(execFileSync(\"curl\", [\"-s\", `${baseURL}/curl?q=5`], { encoding: \"utf8\" })).toBe(\"35\");\n",
            "});\n",
            "test(\"waits beside it\", async ({ request }) => {\n",
            "  await new Promise((done) => setTimeout(done, 2000));\n",
            "  expect(await (await request.get(\"/ready\")).text()).toBe(\"ready\");\n",
            "});\n",
        ),
    );
    project.git(&["init", "-q"]);
    project.commit("requests outside pages");
    let roots = [("SUPERCOV_SOURCE_ROOTS", "server")];
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots[0], ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let ran = project.supercov_with(&["runs", "latest", "mutants", "test", "--json"], &roots);
    let said = ran.stderr();
    let reply = ran.json();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let shown = mutants
        .iter()
        .map(|mutant| format!("{} {} {}", mutant["id"], mutant["status"], mutant["strong"]))
        .collect::<Vec<_>>()
        .join("\n");
    let context = format!("{reply}\n{shown}\n{said}");
    let strong = |line: u32, ending: &str| {
        let found = mutants
            .iter()
            .filter(|mutant| {
                let id = mutant["id"].as_str().unwrap();
                id.starts_with(&format!("server/app.js:{line}:")) && id.ends_with(ending)
            })
            .collect::<Vec<_>>();
        assert_eq!(found.len(), 1, "{line} {ending}\n{context}");
        found[0]["strong"].clone()
    };
    // Each way a test reaches the server kills its route's mutant.
    for (line, way) in [
        (2, "a request context of its own"),
        (4, "the page's request"),
        (8, "Node's fetch"),
        (11, "Node's http"),
        (14, "a routed fetch"),
        (17, "curl in a child process"),
    ] {
        let verdict = strong(line, ":ArithmeticOperator:/");
        assert_eq!(verdict["status"], "killed", "{way}\n{context}");
    }
    // curl's request named no test, and was no test's by time: its mutant
    // ran with the server started with it.
    let child = strong(17, ":ArithmeticOperator:/");
    assert!(
        child["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("its code ran for a request that named no test")),
        "{context}"
    );
    // The arrow, mutated whole: the server made it as it loaded the module.
    let arrow = strong(2, ":ArrowFunction:undefined");
    assert_eq!(arrow["status"], "killed", "{context}");
    assert!(
        arrow["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("it is a server module's top-level code")),
        "{context}"
    );
    // What survives only changes the log line: counted on its own, and
    // marked where survivors are listed.
    assert_eq!(reply["summary"]["survived"], 2, "{context}");
    assert_eq!(reply["survivors"]["logOnly"], 2, "{context}");
    for logged in mutants
        .iter()
        .filter(|mutant| mutant["strong"]["status"] == "survived")
    {
        assert!(
            logged["id"]
                .as_str()
                .unwrap()
                .starts_with("server/app.js:7:")
                && logged["logOnly"] == true,
            "{context}"
        );
    }
    let survivors = project
        .supercov(&["runs", "latest", "mutants", "--status", "survived"])
        .succeeds();
    contains_all(
        &survivors,
        &[
            "2 survived (2 only change a log line)",
            "(only changes a log line)",
        ],
    );
}

/// `mutants test` over a Playwright test whose `expect` starts late under a
/// mutant and fails by its own timeout after the attempt's limit: the
/// mutant sends the page's request through a route the test delays, so the
/// assertion begins seconds after it does without the mutant, and its five
/// seconds end past the limit its baseline gives. Stopped there, the mutant
/// was a timeout on a loaded machine and a kill on an idle one; it is let run
/// to the assertion's own end, and the assertion kills it, on any machine.
#[cfg(unix)]
#[test]
fn mutants_test_lets_an_expect_that_starts_late_fail_by_its_own_timeout() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright-late-expect");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-late-expect", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "server.mjs",
        "import { createServer } from \"node:http\";\nimport { readFileSync } from \"node:fs\";\ncreateServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  const file = path === \"/\" ? \"index.html\" : path.slice(1);\n  try {\n    const body = readFileSync(new URL(`./public/${file}`, import.meta.url));\n    response.writeHead(200, { \"content-type\": file.endsWith(\".js\") ? \"text/javascript\" : \"text/html\" });\n    response.end(body);\n  } catch {\n    response.writeHead(404);\n    response.end();\n  }\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "public/index.html",
        "<!doctype html><p id=\"out\">loading</p><script type=\"module\" src=\"/app.js\"></script>\n",
    );
    // The page asks for its mode's data; every mutant of the condition but
    // one asks for the other mode's.
    project.write(
        "public/app.js",
        "export function mode(count) {\n  return count > 2 ? \"good\" : \"bad\";\n}\nfetch(`/data?mode=${mode(5)}`).then((response) => response.text()).then((text) => {\n  document.getElementById(\"out\").textContent = text;\n});\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node server.mjs\", url: \"http://127.0.0.1:{port}/\", reuseExistingServer: false, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    // The route answers the other mode three seconds late: the assertion
    // starts then, and its five seconds end well past the limit a
    // half-second baseline gives (1.5 × baseline + 5 s).
    project.write(
        "tests/late.spec.js",
        concat!(
            "import { test, expect } from \"@playwright/test\";\n",
            "test(\"shows its mode's data\", async ({ page }) => {\n",
            "  await page.route(\"**/data*\", async (route) => {\n",
            "    const good = route.request().url().endsWith(\"mode=good\");\n",
            "    if (!good) await new Promise((done) => setTimeout(done, 3000));\n",
            "    await route.fulfill({ body: good ? \"good\" : \"other\", contentType: \"text/plain\" });\n",
            "  });\n",
            "  const answered = page.waitForResponse(\"**/data*\");\n",
            "  await page.goto(\"/\");\n",
            "  await answered;\n",
            "  await expect(page.locator(\"#out\")).toHaveText(\"good\");\n",
            "});\n",
        ),
    );
    project.git(&["init", "-q"]);
    project.commit("an expect that starts late");
    let roots = [("SUPERCOV_SOURCE_ROOTS", "public")];
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots[0], ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let ran = project.supercov_with(&["runs", "latest", "mutants", "test", "--json"], &roots);
    let said = ran.stderr();
    let reply = ran.json();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let shown = mutants
        .iter()
        .map(|mutant| format!("{} {} {}", mutant["id"], mutant["status"], mutant["strong"]))
        .collect::<Vec<_>>()
        .join("\n");
    let context = format!("{reply}\n{shown}\n{said}");
    let verdict = |prefix: &str, ending: &str| {
        let found = mutants
            .iter()
            .filter(|mutant| {
                let id = mutant["id"].as_str().unwrap();
                id.starts_with(prefix) && id.ends_with(ending)
            })
            .collect::<Vec<_>>();
        assert_eq!(found.len(), 1, "{prefix} {ending}\n{context}");
        found[0]["strong"].clone()
    };
    // Each mutant that sends the page to the other mode is killed by the
    // assertion, which started three seconds late and failed by its own
    // timeout past the limit: none of them is a timeout.
    for (prefix, ending) in [
        ("public/app.js:2:10-", ":ConditionalExpression:false"),
        ("public/app.js:2:10-", ":EqualityOperator:<="),
        ("public/app.js:2:22-", ":StringLiteral:empty"),
    ] {
        let late = verdict(prefix, ending);
        assert_eq!(late["status"], "killed", "{ending}\n{context}");
        assert!(
            late["reason"].as_str().is_some_and(
                |reason| reason.contains("toHaveText") && reason.contains("Timeout: 5000ms")
            ),
            "{ending}\n{context}"
        );
        assert!(
            late["durationMs"].as_u64().unwrap() > 6_500,
            "{ending}: it ran past its limit\n{context}"
        );
    }
    // The address emptied: the page asks for nothing the test waits for,
    // and a wait with no timeout of its own still ends at the limit.
    let hang = verdict("public/app.js:4:7-", ":StringLiteral:empty");
    assert_eq!(hang["status"], "timeout", "{context}");
    assert_eq!(reply["summary"]["timeout"], 1, "{context}");
}

/// `mutants test` over Playwright tests that drive a pipeline through a cron
/// route, which answers at once and leaves the work running: each test posts
/// to the route, carrying its name as any request does, and polls until its
/// job is done. A mock batch server, a process of its own, plays the provider
/// the work sends batches to and polls. One kind of work is sent, polled and
/// read after the response, in the request's own continuation; the other is
/// read by one poller the process's first call started, so every later
/// call's batch is finished in a continuation an earlier request began. Each
/// way's mutant is killed by the tests that wait for it, though no request's
/// mutant reaches the poller: such work runs with the server started with
/// the mutant.
#[cfg(unix)]
#[test]
fn mutants_test_kills_server_mutants_work_after_a_response_reaches() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let free = || common::free_port();
    let (port, batches) = (free(), free());
    let project = Project::empty("strong-playwright-after-response");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-after-response", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    // The provider: a batch is in progress for its first two polls, then
    // done, its output its input plus one.
    project.write(
        "support/batches.js",
        "import http from \"node:http\";\nconst batches = new Map();\nhttp.createServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  if (path === \"/ready\") return response.end(\"ready\");\n  if (request.method === \"POST\" && path === \"/batches\") {\n    let body = \"\";\n    request.on(\"data\", (chunk) => (body += chunk)).on(\"end\", () => {\n      const id = `batch-${batches.size + 1}`;\n      batches.set(id, { input: JSON.parse(body).input, polls: 0 });\n      response.end(JSON.stringify({ id }));\n    });\n    return;\n  }\n  const batch = batches.get(path.slice(\"/batches/\".length));\n  batch.polls += 1;\n  response.end(JSON.stringify(batch.polls > 2 ? { status: \"completed\", output: batch.input + 1 } : { status: \"in_progress\" }));\n}).listen(Number(process.env.BATCH_PORT));\n",
    );
    // The cron route answers before the work is done.
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { pipeline } from \"./pipeline.js\";\nhttp.createServer((request, response) => {\n  const url = new URL(request.url, \"http://local\");\n  const job = url.searchParams.get(\"job\");\n  if (url.pathname === \"/ready\") return response.end(\"ready\");\n  if (request.method === \"POST\" && url.pathname === \"/cron\") {\n    pipeline[url.searchParams.get(\"how\")](job, Number(url.searchParams.get(\"q\")));\n    response.statusCode = 202;\n    return response.end(\"accepted\");\n  }\n  response.end(String(pipeline.result(job) ?? \"pending\"));\n}).listen(Number(process.env.PORT));\n",
    );
    // The pipeline: the work after the response, and one poller for the
    // process, which the first call starts.
    project.write(
        "support/pipeline.js",
        "import { afterResponse, byPoller } from \"../server/finish.js\";\nconst provider = `http://127.0.0.1:${process.env.BATCH_PORT}/batches`;\nconst results = new Map();\nconst waiting = new Map();\nlet poller;\nconst sleep = (ms) => new Promise((done) => setTimeout(done, ms));\nasync function submit(input) {\n  const response = await fetch(provider, { method: \"POST\", body: JSON.stringify({ input }) });\n  return (await response.json()).id;\n}\nasync function retrieve(id) {\n  return (await fetch(`${provider}/${id}`)).json();\n}\nasync function poll() {\n  for (;;) {\n    for (const [job, submitted] of waiting) {\n      const batch = await retrieve(await submitted);\n      if (batch.status === \"completed\") {\n        waiting.delete(job);\n        results.set(job, byPoller(batch.output));\n      }\n    }\n    await sleep(20);\n  }\n}\nexport const pipeline = {\n  afterResponse(job, q) {\n    void (async () => {\n      const id = await submit(q);\n      for (;;) {\n        const batch = await retrieve(id);\n        if (batch.status === \"completed\") return results.set(job, afterResponse(batch.output));\n        await sleep(20);\n      }\n    })();\n  },\n  nextCall(job, q) {\n    waiting.set(job, submit(q));\n    poller ??= poll();\n  },\n  result(job) {\n    return results.get(job);\n  },\n};\n",
    );
    // What each way does with a finished batch: the code under test.
    project.write(
        "server/finish.js",
        "export function afterResponse(output) {\n  return output * 2;\n}\nexport function byPoller(output) {\n  return output * 3;\n}\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: [\n    {{ command: \"node support/batches.js\", url: \"http://127.0.0.1:{batches}/ready\", reuseExistingServer: false, timeout: 20000, env: {{ BATCH_PORT: \"{batches}\" }} }},\n    {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/ready\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\", BATCH_PORT: \"{batches}\" }} }},\n  ],\n}};\n"
        ),
    );
    project.write(
        "tests/pipeline.spec.js",
        concat!(
            "import { test, expect } from \"@playwright/test\";\n",
            "async function run(request, how, job, q) {\n",
            "  const posted = await request.post(`/cron?how=${how}&job=${job}&q=${q}`);\n",
            "  expect(posted.status()).toBe(202);\n",
            "  await expect.poll(async () => (await request.get(`/status?job=${job}`)).text(), { timeout: 5000 }).not.toBe(\"pending\");\n",
            "  return (await request.get(`/status?job=${job}`)).text();\n",
            "}\n",
            "test(\"a job read after the response\", async ({ request }) => {\n",
            "  expect(await run(request, \"afterResponse\", `after-${Math.random()}`, 5)).toBe(\"12\");\n",
            "});\n",
            "test(\"the first job the poller reads\", async ({ request }) => {\n",
            "  expect(await run(request, \"nextCall\", `first-${Math.random()}`, 5)).toBe(\"18\");\n",
            "});\n",
            "test(\"a later job the same poller reads\", async ({ request }) => {\n",
            "  expect(await run(request, \"nextCall\", `later-${Math.random()}`, 6)).toBe(\"21\");\n",
            "});\n",
        ),
    );
    project.git(&["init", "-q"]);
    project.commit("a pipeline a cron route leaves running");
    let roots = [("SUPERCOV_SOURCE_ROOTS", "server")];
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots[0], ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let ran = project.supercov_with(&["runs", "latest", "mutants", "test", "--json"], &roots);
    let said = ran.stderr();
    let reply = ran.json();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let shown = mutants
        .iter()
        .map(|mutant| format!("{} {} {}", mutant["id"], mutant["status"], mutant["strong"]))
        .collect::<Vec<_>>()
        .join("\n");
    let context = format!("{reply}\n{shown}\n{said}");
    let strong = |line: u32| {
        let found = mutants
            .iter()
            .filter(|mutant| {
                let id = mutant["id"].as_str().unwrap();
                id.starts_with(&format!("server/finish.js:{line}:"))
                    && id.ends_with(":ArithmeticOperator:/")
            })
            .collect::<Vec<_>>();
        assert_eq!(found.len(), 1, "{line}\n{context}");
        found[0]["strong"].clone()
    };
    // Read after the response, and by the poller an earlier call started:
    // each is killed, with the server started with it, since its work went
    // on after its request was answered.
    for (line, way) in [(2, "after the response"), (5, "by the poller")] {
        let verdict = strong(line);
        assert_eq!(verdict["status"], "killed", "{way}\n{context}");
        assert!(
            verdict["reason"].as_str().is_some_and(|reason| reason.contains(
                "ran alone, with the server started with it switched on: its code ran in server work no request was waiting for"
            )),
            "{way}\n{context}"
        );
    }
}

/// `mutants test` over a Playwright test whose server hands its work to one
/// worker process, which the first request that needs it starts: the worker
/// carries that request's attempt, as a child process does, and does every
/// later request's work as that attempt's. In a strong pass that attempt is
/// the test's first run, with no mutant, so no attempt's mutant reaches the
/// worker, and every candidate passes. Such a survivor, which its candidates
/// reached when measured and none of its attempts ran, is in doubt: it runs
/// again alone, with the server started with it switched on, and is killed,
/// and the pass says so.
#[cfg(unix)]
#[test]
fn mutants_test_runs_alone_a_survivor_no_attempt_ran() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright-unreached");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-unreached", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { fork } from \"node:child_process\";\nlet worker;\nconst waiting = new Map();\nlet next = 0;\nhttp.createServer((request, response) => {\n  const url = new URL(request.url, \"http://local\");\n  if (url.pathname === \"/ready\") return response.end(\"ready\");\n  // One worker for the process, started by the first request that needs it.\n  if (!worker) {\n    worker = fork(new URL(\"./worker.js\", import.meta.url));\n    worker.on(\"message\", ({ id, value }) => waiting.get(id)(value));\n  }\n  const id = next++;\n  waiting.set(id, (value) => response.end(String(value)));\n  worker.send({ id, q: Number(url.searchParams.get(\"q\")) });\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "support/worker.js",
        "import { double } from \"../server/compute.js\";\nprocess.on(\"message\", ({ id, q }) => process.send({ id, value: double(q) }));\n",
    );
    project.write(
        "server/compute.js",
        "export function double(q) {\n  return q * 2;\n}\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: [{{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/ready\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }}],\n}};\n"
        ),
    );
    project.write(
        "tests/compute.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"the worker doubles\", async ({ request }) => {\n  expect(await (await request.get(\"/work?q=5\")).text()).toBe(\"10\");\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("a server that hands its work to one worker");
    let roots = [("SUPERCOV_SOURCE_ROOTS", "server")];
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots[0], ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let ran = project.supercov_with(&["runs", "latest", "mutants", "test", "--json"], &roots);
    let said = ran.stderr();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let context = format!("{}\n{said}", serde_json::to_string_pretty(mutants).unwrap());
    let divided = mutants
        .iter()
        .find(|mutant| {
            mutant["id"]
                .as_str()
                .unwrap()
                .ends_with(":ArithmeticOperator:/")
        })
        .unwrap_or_else(|| panic!("{context}"));
    assert_eq!(divided["strong"]["status"], "killed", "{context}");
    assert!(
        divided["strong"]["reason"].as_str().is_some_and(|reason| reason.contains(
            "ran alone, with the server started with it switched on: its candidates passed on the shared server, yet no attempt of theirs ran it there"
        )),
        "{context}"
    );
    contains_all(
        &said,
        &[
            "[supercov] warning: 2 mutant(s) lived through every candidate test on the shared server, though no attempt ran them there",
            "Each runs again alone, with the server started with it switched on: server/compute.js:",
            "[supercov] warning: 1 mutant(s) the shared server let live were killed alone, with the server started with them switched on; their verdicts are the kills: server/compute.js:2:",
        ],
    );
}

/// A survivor of the shared server that no attempt ran, sent alone, whose
/// round alone the budget stops before it runs: the passes its candidates
/// made on the shared server passed without it, so the pass leaves it with
/// no verdict and no progress, and the next pass runs it on the shared server
/// and then alone, where it is killed. Before, those passes were kept as its
/// progress, and the next pass, finding every candidate passed, called it
/// `survived` without running it.
#[cfg(unix)]
#[test]
fn a_survivor_no_attempt_ran_keeps_no_progress_when_the_budget_stops_it_alone() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = std::net::TcpListener::bind("127.0.0.1:0")
        .unwrap()
        .local_addr()
        .unwrap()
        .port();
    let project = Project::empty("strong-playwright-unreached-budget");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-unreached-budget", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(
        ".gitignore",
        "node_modules\n.supercov\nsupport/slow-alone\n",
    );
    // As in `mutants_test_runs_alone_a_survivor_no_attempt_ran`, the worker
    // the first request starts carries that request's attempt. And a server
    // started with a mutant switched on is slow to be ready while
    // `support/slow-alone` is there: the round alone outlasts the budget.
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { existsSync } from \"node:fs\";\nimport { fork } from \"node:child_process\";\nconst slow = Boolean(process.env.SUPERCOV_ACTIVE_MUTANT) && existsSync(new URL(\"./slow-alone\", import.meta.url));\nlet worker;\nconst waiting = new Map();\nlet next = 0;\nhttp.createServer((request, response) => {\n  const url = new URL(request.url, \"http://local\");\n  if (url.pathname === \"/ready\") {\n    if (slow) response.statusCode = 503;\n    return response.end(slow ? \"starting\" : \"ready\");\n  }\n  if (!worker) {\n    worker = fork(new URL(\"./worker.js\", import.meta.url));\n    worker.on(\"message\", ({ id, value }) => waiting.get(id)(value));\n  }\n  const id = next++;\n  waiting.set(id, (value) => response.end(String(value)));\n  worker.send({ id, q: Number(url.searchParams.get(\"q\")) });\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "support/worker.js",
        "import { double } from \"../server/compute.js\";\nprocess.on(\"message\", ({ id, q }) => process.send({ id, value: double(q) }));\n",
    );
    project.write(
        "server/compute.js",
        "export function double(q) {\n  return q * 2;\n}\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: [{{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/ready\", reuseExistingServer: false, timeout: 600000, env: {{ PORT: \"{port}\" }} }}],\n}};\n"
        ),
    );
    project.write(
        "tests/compute.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"the worker doubles\", async ({ request }) => {\n  expect(await (await request.get(\"/work?q=5\")).text()).toBe(\"10\");\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("a server that hands its work to one worker");
    let roots = [("SUPERCOV_SOURCE_ROOTS", "server")];
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots[0], ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let run = project.supercov(&["runs", "latest", "--json"]).json()["data"]["run"]
        .as_str()
        .unwrap()
        .to_owned();
    let divided_id = || -> (String, serde_json::Value) {
        let listed = project
            .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
            .json();
        let divided = listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| {
                mutant["id"]
                    .as_str()
                    .unwrap()
                    .ends_with(":ArithmeticOperator:/")
            })
            .cloned()
            .unwrap_or_else(|| panic!("{listed}"));
        (divided["id"].as_str().unwrap().to_owned(), divided)
    };
    let saved = || -> serde_json::Value {
        serde_json::from_str(
            &std::fs::read_to_string(
                project
                    .root
                    .join(format!(".supercov/runs/{run}/strong-mutation.json")),
            )
            .unwrap_or_else(|_| "{}".into()),
        )
        .unwrap()
    };
    // The budget ends while the round alone waits for its server.
    project.write("support/slow-alone", "");
    let stopped = project.supercov_with(
        &[
            "runs", "latest", "mutants", "test", "--json", "--budget", "60",
        ],
        &[roots[0], ("SUPERCOV_VERBOSE", "1")],
    );
    let said = stopped.stderr();
    let (id, divided) = divided_id();
    let context = format!("{divided}\n{}\n{said}", saved());
    contains_all(
        &said,
        &[
            "[supercov] warning: 2 mutant(s) lived through every candidate test on the shared server, though no attempt ran them there",
            "mutant(s), alone",
            "budget spent, ",
        ],
    );
    // No verdict, and nothing passed with it.
    assert!(saved()["mutants"].get(&id).is_none(), "{context}");
    assert!(saved()["progress"].get(&id).is_none(), "{context}");
    assert_ne!(divided["strong"]["status"], "survived", "{context}");
    // The next pass runs it on the shared server, then alone, where it is
    // killed.
    std::fs::remove_file(project.root.join("support/slow-alone")).unwrap();
    let ran = project.supercov_with(&["runs", "latest", "mutants", "test", "--json"], &roots);
    let said = ran.stderr();
    let (_, divided) = divided_id();
    let context = format!("{divided}\n{}\n{said}", saved());
    assert!(
        !said.contains("passed every candidate in earlier passes"),
        "{context}"
    );
    assert_eq!(divided["strong"]["status"], "killed", "{context}");
    assert!(
        divided["strong"]["reason"].as_str().is_some_and(|reason| reason.contains(
            "ran alone, with the server started with it switched on: its candidates passed on the shared server, yet no attempt of theirs ran it there"
        )),
        "{context}"
    );
}

/// A Playwright mutant attempt is stopped at its time limit, its test's
/// baseline x 1.5 + 5 s, or sooner where it stalls: a mutant that keeps an
/// element from appearing ends as a `timeout` once the attempt is past every
/// passing run of its test (baseline x 1.5 + 1 s) and waits, its page quiet,
/// on a click with no timeout of its own (the test asks for 90 s) or an
/// `expect` given 60 s; a slow test's window grows with its baseline, so its
/// survivor, woken by a timer in the page, lives; an `expect` whose own
/// timeout ends it before the limit still kills, though after the window; a
/// page that keeps sending requests is not stalled, and its timeout runs to
/// the limit; a page that polls on a timer every 4 s, quiet between polls,
/// is not stalled either while its next poll is due before the limit: the
/// mutant that leaves its first poll unanswered lives through the test, which
/// a later poll satisfies, and the one that answers no poll stalls once no
/// poll is due before the limit; a page with a request its server has not
/// answered is never stalled, and the mutant that keeps it from saying done
/// runs to its limit, a timeout confirmed there; and the summary and the
/// progress lines say so.
#[cfg(unix)]
#[test]
fn a_playwright_attempt_ends_at_its_baseline_s_time_limit() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright-limit");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-limit", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { readFileSync } from \"node:fs\";\nhttp.createServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  if (path === \"/health\") return response.end(\"ok\");\n  if (path === \"/hang\") return;\n  const file = path === \"/\" ? \"index.html\" : path.slice(1);\n  response.setHeader(\"content-type\", file.endsWith(\".js\") ? \"text/javascript\" : \"text/html\");\n  response.end(readFileSync(new URL(`../public/${file}`, import.meta.url)));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "public/index.html",
        "<!doctype html><body><script src=\"/ready.js\"></script></body>\n",
    );
    project.write(
        "public/ready.js",
        "function ready(flag) {\n  return flag === \"go\";\n}\nif (ready(\"go\")) {\n  const button = document.createElement(\"button\");\n  button.id = \"ready\";\n  document.body.append(button);\n}\n",
    );
    project.write(
        "public/slow.html",
        "<!doctype html><body><p id=\"slow\"></p><script src=\"/slow.js\"></script></body>\n",
    );
    project.write(
        "public/slow.js",
        "const box = document.getElementById(\"slow\");\nsetTimeout(() => {\n  box.textContent = \"Done\";\n  console.log(\"shown\");\n}, 3000);\n",
    );
    project.write(
        "public/note.html",
        "<!doctype html><body><script src=\"/note.js\"></script></body>\n",
    );
    project.write(
        "public/note.js",
        "function shown(state) {\n  return state === \"saved\";\n}\nif (shown(\"saved\")) {\n  const note = document.createElement(\"p\");\n  note.id = \"note\";\n  note.textContent = \"Saved\";\n  document.body.append(note);\n}\n",
    );
    project.write(
        "public/poll.html",
        "<!doctype html><body><p id=\"poll\"></p><script src=\"/poll.js\"></script></body>\n",
    );
    project.write(
        "public/poll.js",
        "const status = document.getElementById(\"poll\");\nlet count = 0;\nasync function tick() {\n  await fetch(\"/health\");\n  count += 1;\n  if (count === 3) status.textContent = \"Done\";\n  else setTimeout(tick, 150);\n}\ntick();\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 2,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/health\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    // Polls its server soon after it loads, then every 4 s: the first poll
    // says ready, unless a mutant makes it wait for the next.
    project.write(
        "public/later.html",
        "<!doctype html><body><script src=\"/later.js\"></script></body>\n",
    );
    project.write(
        "public/later.js",
        "let count = 0;\nfunction answered(polls) {\n  return polls >= 1;\n}\nfunction poll() {\n  count += 1;\n  fetch(`/health?ready=${answered(count) ? 1 : 0}`);\n}\nsetTimeout(poll, 300);\nsetInterval(poll, 4000);\n",
    );
    // Asks its server for what it never answers, and says done.
    project.write(
        "public/hang.html",
        "<!doctype html><body><p id=\"state\"></p><script src=\"/hang.js\"></script></body>\n",
    );
    project.write(
        "public/hang.js",
        "function ready(state) {\n  return state === \"ok\";\n}\nfetch(\"/hang\");\ndocument.getElementById(\"state\").textContent = ready(\"ok\") ? \"Done\" : \"Waiting\";\n",
    );
    project.write(
        "tests/hang.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"waits for done\", async ({ page }) => {\n  await page.goto(\"/hang.html\");\n  await expect(page.locator(\"#state\")).toHaveText(\"Done\", { timeout: 60_000 });\n});\n",
    );
    // Waits for the poll that says ready, with no timeout of its own.
    project.write(
        "tests/later.spec.js",
        "import { test } from \"@playwright/test\";\ntest(\"waits for the ready poll\", async ({ page }) => {\n  await page.goto(\"/later.html\");\n  await page.waitForResponse((response) => response.url().includes(\"ready=1\"));\n});\n",
    );
    project.write(
        "tests/ready.spec.js",
        "import { test } from \"@playwright/test\";\ntest(\"clicks when ready\", async ({ page }) => {\n  test.setTimeout(90_000);\n  await page.goto(\"/\");\n  await page.locator(\"#ready\").click();\n});\n",
    );
    project.write(
        "tests/slow.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"waits for the slow text\", async ({ page }) => {\n  await page.goto(\"/slow.html\");\n  await expect(page.locator(\"#slow\")).toHaveText(\"Done\", { timeout: 60_000 });\n});\n",
    );
    // An `expect` that gives up after 4 s, sooner than the limit (6.5 s at
    // least) and later than the window (2.5 s at least) of a quick test.
    project.write(
        "tests/note.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"shows the note\", async ({ page }) => {\n  await page.goto(\"/note.html\");\n  await expect(page.locator(\"#note\")).toBeVisible({ timeout: 4_000 });\n});\n",
    );
    project.write(
        "tests/poll.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"waits for the polled status\", async ({ page }) => {\n  await page.goto(\"/poll.html\");\n  await expect(page.locator(\"#poll\")).toHaveText(\"Done\", { timeout: 60_000 });\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("strong playwright limit");
    let roots = [("SUPERCOV_SOURCE_ROOTS", "public")];
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots[0], ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let ran = project.supercov_with(
        &["runs", "latest", "mutants", "test", "--json"],
        // The command's output too, with each attempt's line.
        &[
            roots[0],
            ("SUPERCOV_PROGRESS_INTERVAL_MS", "300"),
            ("SUPERCOV_VERBOSE", "1"),
        ],
    );
    let said = ran.stderr();
    let reply = ran.json();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let context = format!(
        "{reply}\n{}\n{said}",
        mutants
            .iter()
            .map(|mutant| format!("{} {}", mutant["id"], mutant["strong"]))
            .collect::<Vec<_>>()
            .join("\n")
    );
    let strong = |file: &str, line: u32, ending: &str| {
        let found = mutants
            .iter()
            .filter(|mutant| {
                let id = mutant["id"].as_str().unwrap();
                id.starts_with(&format!("{file}:{line}:")) && id.ends_with(ending)
            })
            .collect::<Vec<_>>();
        assert_eq!(found.len(), 1, "{file}:{line} {ending}\n{context}");
        found[0]["strong"].clone()
    };
    let duration = |verdict: &serde_json::Value| verdict["durationMs"].as_u64().unwrap_or(0);
    let reason = |verdict: &serde_json::Value| verdict["reason"].as_str().unwrap_or("").to_owned();
    // The limit a verdict's reason states, in ms: `... of its 6.9 s time
    // limit` or `... time limit of 6.9 s`.
    let limit_ms = |verdict: &serde_json::Value| {
        let said = reason(verdict);
        let seconds = said
            .split_once("of its ")
            .or_else(|| said.split_once("time limit of "))
            .and_then(|(_, rest)| rest.split(' ').next())
            .and_then(|number| number.parse::<f64>().ok())
            .unwrap_or_else(|| panic!("no limit in {said}\n{context}"));
        (seconds * 1000.0) as u64
    };
    // The button never appears: the click, with no timeout of its own, waits
    // on a quiet page past every passing run of its test, and the attempt
    // ends there, 4 s before its limit (1.5 x a baseline of a second or two
    // + 5 s), not at the 90 s the test asked for nor Playwright's 30 s.
    let never = strong("public/ready.js", 2, ":EqualityOperator:!==");
    assert_eq!(never["status"], "timeout", "{context}");
    assert!(
        reason(&never).starts_with("stopped at ")
            && reason(&never).contains("1.5 × its ")
            && reason(&never).contains("waiting on Locator.click (#ready)"),
        "{context}"
    );
    assert!(
        (2_000..limit_ms(&never) - 3_000).contains(&duration(&never)),
        "{never}\n{context}"
    );
    // The slow test's baseline is over 3 s, so is its window: the mutant
    // that keeps its text from showing waits that long on an `expect` given
    // 60 s, and ends there, before its limit.
    let blank = strong("public/slow.js", 3, ":StringLiteral:empty");
    assert_eq!(blank["status"], "timeout", "{context}");
    assert!(
        reason(&blank).starts_with("stopped at ")
            && reason(&blank).contains("waiting on expect(#slow) to.have.text"),
        "{context}"
    );
    assert!(
        (6_000..limit_ms(&blank) - 3_000).contains(&duration(&blank)),
        "{blank}\n{context}"
    );
    // Slow but passing, woken by a timer in a quiet page: no timeout.
    let logged = strong("public/slow.js", 4, ":StringLiteral:empty");
    assert_eq!(logged["status"], "survived", "{context}");
    // The note never shows: its `expect` gives up after 4 s, past the
    // test's window but before its limit, and the test fails: a kill, as
    // without the window.
    let hidden = strong("public/note.js", 2, ":EqualityOperator:!==");
    assert_eq!(hidden["status"], "killed", "{context}");
    assert!(
        reason(&hidden).contains("toBeVisible"),
        "{hidden}\n{context}"
    );
    assert!(duration(&hidden) >= 4_000, "{hidden}\n{context}");
    // A page that keeps asking its server is busy, not stalled: the mutant
    // that keeps it from ever being done runs to its limit.
    let busy = strong("public/poll.js", 6, ":ConditionalExpression:false");
    assert_eq!(busy["status"], "timeout", "{context}");
    assert!(
        reason(&busy).starts_with("ran past its time limit of ")
            && reason(&busy).contains("waiting on expect(#poll) to.have.text"),
        "{busy}\n{context}"
    );
    assert!(
        duration(&busy) + 1_000 >= limit_ms(&busy),
        "{busy}\n{context}"
    );
    // The first poll left unanswered: the page's next poll, 4 s later,
    // answers the wait before the limit, though the page was quiet past the
    // window. It lives.
    let later = strong("public/later.js", 3, ":EqualityOperator:>");
    assert_eq!(later["status"], "survived", "{later}\n{context}");
    // No poll ever answers: a timeout. Where no poll is due before the limit
    // (a quick baseline's limit falls before the second interval poll), it
    // stops there; where one is (a slow machine's longer baseline), it runs
    // to the limit and says so.
    let unanswered = strong("public/later.js", 3, ":ConditionalExpression:false");
    assert_eq!(unanswered["status"], "timeout", "{context}");
    assert!(
        reason(&unanswered).contains("waiting on Page.waitForResponse at tests/later.spec.js:")
            && ((reason(&unanswered).starts_with("stopped at ")
                && reason(&unanswered)
                    .contains("its pages quiet with nothing due before the limit"))
                || (reason(&unanswered).starts_with("ran past its time limit of ")
                    && reason(&unanswered).contains("with a timer due in ")
                    && reason(&unanswered).contains("so it ran to its limit to confirm"))),
        "{unanswered}\n{context}"
    );
    // A request still unanswered could end the wait: never stalled, its
    // timeout runs to the limit, and says so.
    let hanging = strong("public/hang.js", 2, ":ConditionalExpression:false");
    assert_eq!(hanging["status"], "timeout", "{context}");
    assert!(
        reason(&hanging).starts_with("ran past its time limit of ")
            && reason(&hanging).contains("waiting on expect(#state) to.have.text at tests/hang.spec.js:")
            && reason(&hanging).contains(", with 1 unanswered request(s) that could still end the wait, so it ran to its limit to confirm"),
        "{hanging}\n{context}"
    );
    assert!(
        duration(&hanging) + 1_000 >= limit_ms(&hanging),
        "{hanging}\n{context}"
    );
    assert!(
        reply["timeLimit"]["confirmedAtLimit"].as_u64() >= Some(1),
        "{context}"
    );
    assert!(
        said.contains("past a stall at ")
            && said.contains("with 1 unanswered request(s) that could still end the wait"),
        "{context}"
    );
    eprintln!(
        "stalled: {} ms of {} ms, {} ms of {} ms; at the limit: {} ms of {} ms",
        duration(&never),
        limit_ms(&never),
        duration(&blank),
        limit_ms(&blank),
        duration(&busy),
        limit_ms(&busy)
    );
    // The answer counts the timeouts at the limit and those that stalled,
    // and says the limit.
    assert_eq!(reply["timeLimit"]["factor"], 1.5, "{context}");
    assert!(
        reply["timeLimit"]["timedOut"].as_u64() >= Some(1)
            && reply["timeLimit"]["stalled"].as_u64() >= Some(2),
        "{context}"
    );
    // While an attempt waits near its limit, the progress lines say so;
    // each attempt's line says what a timeout waited on.
    assert!(said.contains(", near its time limit: "), "{context}");
    assert!(
        said.contains("stalled before its ")
            && said.contains(", waiting on Locator.click (#ready) at tests/ready.spec.js:"),
        "{context}"
    );
    // The factor is the pass's to set: a factor no number is refused.
    let refused = project.supercov_with(
        &["runs", "latest", "mutants", "test"],
        &[roots[0], ("SUPERCOV_STRONG_TIMEOUT_FACTOR", "slow")],
    );
    assert!(
        refused
            .stderr()
            .contains("SUPERCOV_STRONG_TIMEOUT_FACTOR takes a number above 0, not slow"),
        "{}",
        refused.stderr()
    );
}

/// A Playwright mutant tries its cheap candidates before its slow one: a
/// test that polls for seconds until the page says it is active is declared
/// first in its file, beside three fast tests that each read one text. The
/// mutants a fast test kills are decided by it, in under a second each, and
/// the slow test never runs them; it runs only the mutants every fast test
/// let live, and a survivor runs all four of its candidates. While it runs,
/// the progress lines name the slow test as the costliest left and say the
/// time its round has left.
#[cfg(unix)]
#[test]
fn a_playwright_mutant_tries_its_cheap_candidates_before_its_slow_one() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright-order");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-order", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { readFileSync } from \"node:fs\";\nhttp.createServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  if (path === \"/health\") return response.end(\"ok\");\n  const file = path === \"/\" ? \"index.html\" : path.slice(1);\n  response.setHeader(\"content-type\", file.endsWith(\".js\") ? \"text/javascript\" : \"text/html\");\n  response.end(readFileSync(new URL(`../public/${file}`, import.meta.url)));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "public/index.html",
        "<!doctype html><body><p id=\"first\"></p><p id=\"second\"></p><p id=\"third\"></p><p id=\"state\"></p><script src=\"/app.js\"></script></body>\n",
    );
    project.write(
        "public/app.js",
        "function show(id, text) {\n  document.getElementById(id).textContent = text;\n}\nshow(\"first\", \"First\");\nshow(\"second\", \"Second\");\nshow(\"third\", \"Third\");\nconsole.log(\"loaded\");\nsetTimeout(() => show(\"state\", \"Active\"), 3000);\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/health\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    // The slow test first: a pass that ran a file's tests in their order,
    // each test all its mutants, would run every mutant with it first.
    project.write(
        "tests/app.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"waits until it is active\", async ({ page }) => {\n  await page.goto(\"/\");\n  await expect(page.locator(\"#state\")).toHaveText(\"Active\", { timeout: 60_000 });\n});\nfor (const [id, text] of [[\"first\", \"First\"], [\"second\", \"Second\"], [\"third\", \"Third\"]]) {\n  test(`shows the ${id}`, async ({ page }) => {\n    await page.goto(\"/\");\n    expect(await page.locator(`#${id}`).textContent()).toBe(text);\n  });\n}\n",
    );
    project.git(&["init", "-q"]);
    project.commit("strong playwright order");
    let roots = ("SUPERCOV_SOURCE_ROOTS", "public");
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots, ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let plan = project
        .supercov_with(
            &["runs", "latest", "mutants", "test", "--plan", "--json"],
            &[roots],
        )
        .json();
    let tests = plan["tests"].as_array().unwrap();
    let slow = tests
        .iter()
        .find(|test| test["title"] == "waits until it is active")
        .unwrap_or_else(|| panic!("no slow test in {plan}"))["id"]
        .as_str()
        .unwrap()
        .to_owned();
    // The command's output, with each attempt's line: SUPERCOV_VERBOSE.
    let ran = project.supercov_with(
        &["runs", "latest", "mutants", "test"],
        &[
            roots,
            ("SUPERCOV_PROGRESS_INTERVAL_MS", "300"),
            ("SUPERCOV_VERBOSE", "1"),
        ],
    );
    let said = format!("{}\n{}", ran.stdout(), ran.stderr());
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let context = format!(
        "{}\n{}\n{said}",
        mutants
            .iter()
            .map(|mutant| format!("{} {}", mutant["id"], mutant["strong"]))
            .collect::<Vec<_>>()
            .join("\n"),
        serde_json::json!({ "tests": plan["tests"], "mutants": plan["mutants"] })
    );
    let on_line = |line: u32| {
        mutants
            .iter()
            .filter(|mutant| {
                mutant["id"]
                    .as_str()
                    .unwrap()
                    .starts_with(&format!("public/app.js:{line}:"))
            })
            .collect::<Vec<_>>()
    };
    // Each mutant of `show` and of the three texts breaks what a fast test
    // reads: a fast test kills it, and no more than the three fast ones ran
    // it. (Its time said so too, under three seconds, until a loaded runner
    // took 3.5 s over one fast kill.)
    let mut fast_kills = Vec::new();
    for line in 1..=6 {
        for mutant in on_line(line) {
            let strong = &mutant["strong"];
            assert_eq!(strong["status"], "killed", "{mutant}\n{context}");
            assert_ne!(strong["killedBy"], slow.as_str(), "{mutant}\n{context}");
            assert!(
                (1..=3).contains(&strong["tests"].as_u64().unwrap_or(0)),
                "{mutant}\n{context}"
            );
            fast_kills.push(mutant["id"].as_str().unwrap().to_owned());
        }
    }
    assert!(fast_kills.len() >= 4, "{context}");
    // The slow test ran none of them: each attempt's line names its mutant
    // and its test.
    let slow_ran = said
        .lines()
        .filter(|line| line.contains(": \"waits until it is active\" "))
        .filter_map(|line| line.split("[supercov] ").nth(1))
        .filter_map(|line| line.split(": \"").next())
        .collect::<Vec<_>>();
    assert!(!slow_ran.is_empty(), "{context}");
    for id in &slow_ran {
        assert!(!fast_kills.iter().any(|fast| fast == id), "{id}\n{context}");
    }
    // Nothing a fast test reads: every fast test lets it live, then the
    // slow one, all four candidates run.
    let loaded = on_line(7);
    assert_eq!(loaded.len(), 1, "{context}");
    assert_eq!(loaded[0]["strong"]["status"], "survived", "{context}");
    assert_eq!(loaded[0]["strong"]["tests"], 4, "{context}");
    // What only the slow test reads (the state it waits for): it runs out
    // of its time limit there, once the fast tests let it live.
    let detected_by_slow = on_line(8)
        .into_iter()
        .filter(|mutant| mutant["strong"]["status"] == "timeout")
        .inspect(|mutant| {
            assert_eq!(
                mutant["strong"]["killedBy"],
                slow.as_str(),
                "{mutant}\n{context}"
            )
        })
        .count();
    assert!(detected_by_slow >= 1, "{context}");
    // The progress lines name the costliest test left and the round's time.
    assert!(
        said.contains("costliest test left: \"waits until it is active\", "),
        "{context}"
    );
    assert!(said.contains(" left in this round"), "{context}");
}

/// A test's first run in an invocation takes a mutant where the mutant
/// already lived through a candidate: a test whose mutants live needs no run
/// without one, and a failure is judged by the control after it. Here the
/// app's server fails the first request to each page in a strong pass (a
/// cold cache), and the only mutant is a log line nothing reads, with two
/// candidates in two files. The first file's test runs without it first
/// (no candidate let it live yet, so a cold failure is likely): the cold
/// page fails that run, the next passes, and then the mutant lives. The
/// second file's test takes the mutant at once, and fails on its cold page;
/// that failure decides nothing: the control after it passes, the test runs
/// the mutant again, and it survives, where a kill confirmed by that control
/// would have been false.
#[cfg(unix)]
#[test]
fn a_playwright_test_takes_a_mutant_first_and_a_cold_failure_runs_again() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright-cold");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-cold", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    // Notes each page it serves and the mutant the request's attempt named
    // (`-`: a control), outside the project.
    let served = project.root.with_extension("served.jsonl");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { appendFileSync, readFileSync } from \"node:fs\";\n// A strong pass's server fails the first request to each page: a cold cache.\nconst warm = new Set();\nhttp.createServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  if (path === \"/health\") return response.end(\"ok\");\n  const cookie = /(?:^|;\\s*)__supercov_scope=([^;]*)/.exec(request.headers.cookie ?? \"\");\n  const scope = new URLSearchParams(request.headers[\"x-supercov-scope\"] ?? (cookie ? decodeURIComponent(cookie[1]) : \"\"));\n  if (path.endsWith(\".html\")) {\n    const cold = Boolean(process.env.SUPERCOV_STRONG_PLAN) && !warm.has(path);\n    warm.add(path);\n    appendFileSync(process.env.SERVED_LOG, JSON.stringify({ path, mutant: scope.get(\"m\"), cold }) + \"\\n\");\n    if (cold) {\n      response.statusCode = 503;\n      return response.end(\"warming up\");\n    }\n  }\n  const file = path.slice(1);\n  response.setHeader(\"content-type\", file.endsWith(\".js\") ? \"text/javascript\" : \"text/html\");\n  response.end(readFileSync(new URL(`../public/${file}`, import.meta.url)));\n}).listen(Number(process.env.PORT));\n",
    );
    for page in ["first", "second"] {
        project.write(
            &format!("public/{page}.html"),
            "<!doctype html><body><p id=\"out\">Ready</p><script src=\"/app.js\"></script></body>\n",
        );
    }
    project.write("public/app.js", "console.log(\"shown\");\n");
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/health\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\", SERVED_LOG: {:?} }} }},\n}};\n",
            served.display().to_string()
        ),
    );
    // One test a file: a worker runs the first file's before the second's.
    for (at, page) in [(1, "first"), (2, "second")] {
        project.write(
            &format!("tests/{at}-{page}.spec.js"),
            &format!("import {{ test, expect }} from \"@playwright/test\";\ntest(\"shows the {page} page\", async ({{ page }}) => {{\n  const response = await page.goto(\"/{page}.html\");\n  expect(response.status()).toBe(200);\n  await expect(page.locator(\"#out\")).toHaveText(\"Ready\");\n}});\n"),
        );
    }
    project.git(&["init", "-q"]);
    project.commit("strong playwright cold");
    let roots = ("SUPERCOV_SOURCE_ROOTS", "public");
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots, ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let _ = std::fs::remove_file(&served);
    let ran = project.supercov_with(
        &["runs", "latest", "mutants", "test"],
        &[roots, ("SUPERCOV_VERBOSE", "1")],
    );
    let said = format!("{}\n{}", ran.stdout(), ran.stderr());
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let pages = std::fs::read_to_string(&served).unwrap_or_default();
    let context = format!(
        "{}\n{pages}\n{said}",
        mutants
            .iter()
            .map(|mutant| format!("{} {}", mutant["id"], mutant["strong"]))
            .collect::<Vec<_>>()
            .join("\n")
    );
    let logged = mutants
        .iter()
        .filter(|mutant| {
            mutant["id"]
                .as_str()
                .unwrap()
                .starts_with("public/app.js:1:")
        })
        .collect::<Vec<_>>();
    assert_eq!(logged.len(), 1, "{context}");
    // The second page's attempt failed cold, and said it runs again.
    assert!(
        said.contains("before any control here: runs again after one"),
        "{context}"
    );
    // Both candidates let it live: it survives.
    assert_eq!(logged[0]["strong"]["status"], "survived", "{context}");
    assert_eq!(logged[0]["strong"]["tests"], 2, "{context}");
    let runs = pages
        .lines()
        .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
        .collect::<Vec<_>>();
    let served = |path: &str| {
        runs.iter()
            .filter(|run| run["path"] == path)
            .map(|run| {
                let mutant = run["mutant"].as_str().unwrap_or("");
                let with = if mutant == "-" {
                    "control"
                } else if mutant.starts_with("public/app.js#") {
                    "mutant"
                } else {
                    "other"
                };
                (with, run["cold"] == true)
            })
            .collect::<Vec<_>>()
    };
    // The first page: without the mutant, cold, and again, then with it.
    assert_eq!(
        served("/first.html"),
        [("control", true), ("control", false), ("mutant", false)],
        "{context}"
    );
    // The second: with the mutant, cold; the control; with it again.
    assert_eq!(
        served("/second.html"),
        [("mutant", true), ("control", false), ("mutant", false)],
        "{context}"
    );
}

/// A pass its budget stopped keeps, for each mutant it left open, the
/// candidates that already passed with it, and the next pass resumes there:
/// in a spec file with a serial describe of six tests that each wait for
/// the page to become active, a mutant no test detects (what the page logs)
/// runs, in the pass to its end, exactly the candidates no pass before
/// recorded, never one it passed again,
/// and survives with all six (a test the stop itself failed, its server
/// gone, kills nothing); one only the file's last test detects is killed by
/// it, whichever pass got there.
#[cfg(unix)]
#[test]
fn a_playwright_pass_resumes_where_its_budget_stopped_it() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright-resume");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-resume", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { readFileSync } from \"node:fs\";\nhttp.createServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  if (path === \"/health\") return response.end(\"ok\");\n  const file = path === \"/\" ? \"index.html\" : path.slice(1);\n  response.setHeader(\"content-type\", file.endsWith(\".js\") ? \"text/javascript\" : \"text/html\");\n  response.end(readFileSync(new URL(`../${file.startsWith(\"public/\") ? \"\" : \"static/\"}${file}`, import.meta.url)));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "static/index.html",
        "<!doctype html><body><p id=\"state\"></p><script src=\"/public/log.js\"></script><script src=\"/app.js\"></script></body>\n",
    );
    // The page becomes active after a while: every test waits for it, long
    // enough that a pass stopped at 32 s runs only some of the six with a
    // mutant (a test's first run takes one: there is no baseline first).
    project.write(
        "static/app.js",
        "setTimeout(() => { document.getElementById(\"state\").textContent = \"Active\"; }, 5000);\n",
    );
    // The mutants: what the page logs (no test reads it) and a flag only
    // the last test reads.
    project.write(
        "public/log.js",
        "console.log(\"loaded\");\nwindow.ready = true;\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/health\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    project.write(
        "tests/purchase.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest.describe.configure({ mode: \"serial\" });\nfor (const step of [1, 2, 3, 4, 5]) {\n  test(`waits ${step}`, async ({ page }) => {\n    await page.goto(\"/\");\n    await expect(page.locator(\"#state\")).toHaveText(\"Active\", { timeout: 20_000 });\n  });\n}\ntest(\"waits 6 and is ready\", async ({ page }) => {\n  await page.goto(\"/\");\n  await expect(page.locator(\"#state\")).toHaveText(\"Active\", { timeout: 20_000 });\n  expect(await page.evaluate(() => window.ready)).toBe(true);\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("strong playwright resume");
    let roots = ("SUPERCOV_SOURCE_ROOTS", "public");
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots, ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let plan = project
        .supercov_with(
            &["runs", "latest", "mutants", "test", "--plan", "--json"],
            &[roots],
        )
        .json();
    let titles = plan["tests"]
        .as_array()
        .unwrap()
        .iter()
        .map(|test| {
            (
                test["id"].as_str().unwrap().to_owned(),
                test["title"].as_str().unwrap_or_default().to_owned(),
            )
        })
        .collect::<std::collections::BTreeMap<_, _>>();
    let run = project.supercov(&["runs", "latest", "--json"]).json()["data"]["run"]
        .as_str()
        .unwrap()
        .to_owned();
    let saved = || -> serde_json::Value {
        serde_json::from_str(
            &std::fs::read_to_string(
                project
                    .root
                    .join(format!(".supercov/runs/{run}/strong-mutation.json")),
            )
            .unwrap_or_else(|_| "{}".into()),
        )
        .unwrap()
    };
    let listed = || -> Vec<serde_json::Value> {
        project
            .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
            .json()["data"]["mutants"]
            .as_array()
            .unwrap()
            .clone()
    };
    let on_line = |line: u32| {
        listed()
            .into_iter()
            .filter(|mutant| {
                mutant["id"]
                    .as_str()
                    .unwrap()
                    .starts_with(&format!("public/log.js:{line}:"))
            })
            .collect::<Vec<_>>()
    };
    let loaded = on_line(1);
    assert_eq!(loaded.len(), 1, "{plan}");
    let loaded = loaded[0]["id"].as_str().unwrap().to_owned();
    // Each attempt's line: `<mutant>: "<test>" lives`, with the command's
    // output (SUPERCOV_VERBOSE).
    let lives = |said: &str| {
        said.lines()
            .filter_map(|line| line.split("[supercov] ").nth(1))
            .filter(|line| {
                line.starts_with(&format!("{loaded}: \"")) && line.contains("\" lives (")
            })
            .map(|line| line.split('"').nth(1).unwrap().to_owned())
            .collect::<Vec<_>>()
    };
    let mut log = String::new();
    let mut ran = Vec::new();
    let mut resumed_from = std::collections::BTreeSet::new();
    // Passes stopped by their budget, until one left the mutant some
    // candidates passed and others not; then a pass to its end.
    for pass in 0..4 {
        let budget = pass < 3
            && resumed_from.is_empty()
            && saved()["progress"][&loaded]
                .as_array()
                .is_none_or(Vec::is_empty);
        let before = saved()["progress"][&loaded]
            .as_array()
            .into_iter()
            .flatten()
            .map(|id| titles[id.as_str().unwrap()].clone())
            .collect::<std::collections::BTreeSet<_>>();
        // The web server a stopped pass started may take a moment to end.
        for _ in 0..100 {
            if std::net::TcpListener::bind(("127.0.0.1", port.number())).is_ok() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(200));
        }
        let mut args = vec!["runs", "latest", "mutants", "test"];
        if budget {
            args.extend(["--budget", "32"]);
        }
        let out = project.supercov_with(
            &args,
            &[
                roots,
                ("SUPERCOV_VERBOSE", "1"),
                ("SUPERCOV_STRONG_KEEP", "1"),
            ],
        );
        let said = format!("{}\n{}", out.stdout(), out.stderr());
        log.push_str(&format!("=== pass {pass} (budget: {budget})\n{said}\n"));
        // What the pass's driver wrote, should an assertion below fail.
        for work in std::fs::read_dir(project.root.join(".supercov/strong"))
            .into_iter()
            .flatten()
            .flatten()
        {
            for file in std::fs::read_dir(work.path())
                .into_iter()
                .flatten()
                .flatten()
            {
                let name = file.file_name().to_string_lossy().into_owned();
                if name == "results.jsonl" || name.ends_with(".log") {
                    let text = std::fs::read_to_string(file.path()).unwrap_or_default();
                    let start = (text.len().saturating_sub(3_000)..=text.len())
                        .find(|at| text.is_char_boundary(*at))
                        .unwrap_or(0);
                    let tail = &text[start..];
                    log.push_str(&format!("--- {name}\n{tail}\n"));
                }
            }
        }
        log.push_str(&format!("--- saved\n{}\n", saved()));
        let lived = lives(&said);
        // No candidate it passed before runs again.
        for title in &lived {
            assert!(!before.contains(title), "{title} ran again\n{log}");
        }
        if !before.is_empty() {
            resumed_from = before.clone();
            assert!(
                said.contains("mutant(s) resume where earlier passes left them, with "),
                "{log}"
            );
        }
        if !budget {
            // The pass to its end runs exactly the candidates no pass
            // before it recorded.
            let mut left = [
                "waits 1",
                "waits 2",
                "waits 3",
                "waits 4",
                "waits 5",
                "waits 6 and is ready",
            ]
            .into_iter()
            .filter(|title| !before.contains(*title))
            .map(str::to_owned)
            .collect::<Vec<_>>();
            let mut last = lived.clone();
            last.sort();
            left.sort();
            assert_eq!(last, left, "{log}");
        }
        ran.extend(lived);
        if !budget {
            break;
        }
    }
    assert!(!resumed_from.is_empty(), "no pass stopped part way\n{log}");
    // Over all the passes, every candidate let it live. One a stopped pass
    // ran may run again: what ended after the pass began to stop is not
    // recorded.
    ran.sort();
    ran.dedup();
    assert_eq!(
        ran,
        [
            "waits 1",
            "waits 2",
            "waits 3",
            "waits 4",
            "waits 5",
            "waits 6 and is ready"
        ],
        "{log}"
    );
    let verdicts = listed();
    let strong =
        |id: &str| verdicts.iter().find(|mutant| mutant["id"] == id).unwrap()["strong"].clone();
    assert_eq!(strong(&loaded)["status"], "survived", "{log}");
    assert_eq!(strong(&loaded)["tests"], 6, "{log}");
    let ready = on_line(2);
    let mut killed = 0;
    for mutant in &ready {
        let verdict = strong(mutant["id"].as_str().unwrap());
        if verdict["status"] == "killed" {
            killed += 1;
            assert_eq!(
                titles[verdict["killedBy"].as_str().unwrap()],
                "waits 6 and is ready",
                "{log}"
            );
        } else {
            assert_eq!(verdict["status"], "survived", "{mutant}\n{log}");
        }
    }
    assert!(killed >= 1, "{ready:?}\n{log}");
    // Nothing is left open, so no progress is kept.
    assert!(saved().get("progress").is_none(), "{log}");
}

/// A mutant with more candidates than a first tier holds (32) runs first
/// against its likeliest 32, every such mutant before any runs the rest:
/// what the page logs (no test reads it) lives through its tier, then the
/// rest, and survives with all 34; the flag only the slowest test reads,
/// last in its order, is killed by it in the rest. A pass that stops after
/// a first tier leaves `survived so far`: never a survivor or in the score,
/// listed with the survivors as such, and run to its end by the next pass.
#[cfg(unix)]
#[test]
fn a_playwright_mutant_runs_its_first_tier_before_the_rest() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let port = common::free_port();
    let project = Project::empty("strong-playwright-first-tier");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-first-tier", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { readFileSync } from \"node:fs\";\nhttp.createServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  if (path === \"/health\") return response.end(\"ok\");\n  const file = path === \"/\" ? \"index.html\" : path.slice(1);\n  response.setHeader(\"content-type\", file.endsWith(\".js\") ? \"text/javascript\" : \"text/html\");\n  response.end(readFileSync(new URL(`../${file.startsWith(\"public/\") ? \"\" : \"static/\"}${file}`, import.meta.url)));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "static/index.html",
        "<!doctype html><body><p id=\"state\">Active</p><script src=\"/public/log.js\"></script></body>\n",
    );
    project.write(
        "public/log.js",
        "console.log(\"loaded\");\nwindow.ready = true;\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  workers: 2,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/health\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    // 33 quick tests that load the page, and a slow one that reads the flag.
    project.write(
        "tests/page.spec.js",
        "import { test, expect } from \"@playwright/test\";\nfor (let step = 1; step <= 33; step++) {\n  test(`loads ${step}`, async ({ page }) => {\n    await page.goto(\"/\");\n    await expect(page.locator(\"#state\")).toHaveText(\"Active\");\n  });\n}\ntest(\"is ready, after a while\", async ({ page }) => {\n  await page.goto(\"/\");\n  await page.waitForTimeout(2_000);\n  expect(await page.evaluate(() => window.ready)).toBe(true);\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("strong playwright first tier");
    let roots = ("SUPERCOV_SOURCE_ROOTS", "public");
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots, ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let plan = project
        .supercov_with(
            &["runs", "latest", "mutants", "test", "--plan", "--json"],
            &[roots],
        )
        .json();
    let titles = plan["tests"]
        .as_array()
        .unwrap()
        .iter()
        .map(|test| {
            (
                test["id"].as_str().unwrap().to_owned(),
                test["title"].as_str().unwrap_or_default().to_owned(),
            )
        })
        .collect::<std::collections::BTreeMap<_, _>>();
    let run = project.supercov(&["runs", "latest", "--json"]).json()["data"]["run"]
        .as_str()
        .unwrap()
        .to_owned();
    let saved_path = project
        .root
        .join(format!(".supercov/runs/{run}/strong-mutation.json"));
    let out = project.supercov_with(
        &["runs", "latest", "mutants", "test"],
        &[roots, ("SUPERCOV_VERBOSE", "1")],
    );
    let log = format!("{}\n{}", out.stdout(), out.stderr());
    assert_eq!(out.code(), 0, "{log}");
    let listed = || -> Vec<serde_json::Value> {
        project
            .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
            .json()["data"]["mutants"]
            .as_array()
            .unwrap()
            .clone()
    };
    let verdicts = listed();
    let on_line = |line: u32| {
        verdicts
            .iter()
            .filter(|mutant| {
                mutant["id"]
                    .as_str()
                    .unwrap()
                    .starts_with(&format!("public/log.js:{line}:"))
            })
            .cloned()
            .collect::<Vec<_>>()
    };
    let logged = on_line(1)
        .into_iter()
        .find(|mutant| mutant["mutator"] == "StringLiteral")
        .unwrap_or_else(|| panic!("{plan}"));
    let logged_id = logged["id"].as_str().unwrap().to_owned();
    assert_eq!(logged["strong"]["status"], "survived", "{log}");
    assert_eq!(logged["strong"]["tests"], 34, "{log}");
    let flag = on_line(2)
        .into_iter()
        .find(|mutant| mutant["mutator"] == "BooleanLiteral")
        .unwrap_or_else(|| panic!("{plan}"));
    assert_eq!(flag["strong"]["status"], "killed", "{log}");
    assert_eq!(
        titles[flag["strong"]["killedBy"].as_str().unwrap()],
        "is ready, after a while",
        "{log}"
    );
    // The flag's tier ran before the rest: 32 candidates let it live before
    // the slow test ran with it.
    let flag_id = flag["id"].as_str().unwrap();
    let lived = log
        .lines()
        .filter(|line| line.contains(&format!("{flag_id}: \"")) && line.contains("\" lives ("))
        .count();
    assert_eq!(lived, 33, "{log}");
    // A pass that stopped after the survivor's first tier: what it passed
    // is kept, and no verdict.
    let mut document: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&saved_path).unwrap()).unwrap();
    document["mutants"]
        .as_object_mut()
        .unwrap()
        .remove(&logged_id);
    let tier = titles
        .iter()
        .filter(|(_, title)| title.starts_with("loads ") && title != &"loads 33")
        .map(|(id, _)| id.clone())
        .collect::<Vec<_>>();
    assert_eq!(tier.len(), 32);
    document["progress"] = serde_json::json!({ logged_id.clone(): tier });
    std::fs::write(&saved_path, document.to_string()).unwrap();
    let survivors = project
        .supercov(&[
            "runs", "latest", "mutants", "--status", "survived", "--json",
        ])
        .json();
    let so_far = survivors["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["id"] == logged_id.as_str())
        .unwrap_or_else(|| panic!("{survivors}"))
        .clone();
    assert_eq!(so_far["strong"]["status"], "survived-so-far", "{survivors}");
    assert_eq!(so_far["strong"]["tests"], 32, "{survivors}");
    assert_eq!(
        survivors["data"]["summary"]["strong"]["survived-so-far"], 1,
        "{survivors}"
    );
    let only = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--status",
            "survived-so-far",
            "--json",
        ])
        .json();
    assert_eq!(
        only["data"]["mutants"].as_array().unwrap().len(),
        1,
        "{only}"
    );
    let killed = project
        .supercov(&["runs", "latest", "mutants", "--status", "killed", "--json"])
        .json();
    assert!(
        killed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .all(|mutant| mutant["strong"]["status"] == "killed"),
        "{killed}"
    );
    // A pass whose budget is spent before it reaches it leaves it so.
    let stopped = project.supercov_with(
        &["runs", "latest", "mutants", "test", "--budget", "1"],
        &[roots],
    );
    let said = format!("{}\n{}", stopped.stdout(), stopped.stderr());
    assert!(
        said.contains("  survived so far 1: lived through a first tier (32 candidates or 60 s of their tests' time, whichever comes first)"),
        "{said}"
    );
    // The next pass runs the rest alone, and it survives with all 34, once
    // the web server the stopped pass started has ended.
    for _ in 0..100 {
        if std::net::TcpListener::bind(("127.0.0.1", port.number())).is_ok() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(200));
    }
    let out = project.supercov_with(&["runs", "latest", "mutants", "test", "--json"], &[roots]);
    let reply = out.json();
    assert_eq!(reply["resumed"]["mutants"], 1, "{reply}");
    let verdicts = listed();
    let logged = verdicts
        .iter()
        .find(|mutant| mutant["id"] == logged_id.as_str())
        .unwrap();
    assert_eq!(logged["strong"]["status"], "survived", "{reply}");
    assert_eq!(logged["strong"]["tests"], 34, "{reply}");
}

/// A Playwright pass whose harness runs two slots, one given a spec file
/// with a serial describe that the pass spreads to the other, stops at its
/// budget, run as a later round's shard is: the harness starts each slot's
/// `playwright test` in a process group of its own and, told to stop, only
/// waits for them, yet the stop reaches both slots and their servers, and
/// the command ends within seconds of its budget (about 1 s here).
#[cfg(unix)]
#[test]
fn a_playwright_pass_with_serial_files_stops_at_its_budget() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let ports = [0, 1].map(|_| common::free_port());
    let project = Project::empty("strong-playwright-budget");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-budget", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { readFileSync } from \"node:fs\";\nhttp.createServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  if (path === \"/health\") return response.end(\"ok\");\n  const file = path === \"/\" ? \"static/index.html\" : path.slice(1);\n  response.setHeader(\"content-type\", file.endsWith(\".js\") ? \"text/javascript\" : \"text/html\");\n  response.end(readFileSync(new URL(`../${file}`, import.meta.url)));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "static/index.html",
        "<!doctype html><body><p id=\"state\"></p><script src=\"/public/log.js\"></script><script>setTimeout(() => { document.getElementById(\"state\").textContent = \"Active\"; }, 1500);</script></body>\n",
    );
    // What the page logs: no test reads it, so every mutant survives every
    // candidate.
    project.write(
        "public/log.js",
        &(1..=20)
            .map(|at| format!("console.log(\"line {at}\");\n"))
            .collect::<String>(),
    );
    project.write(
        "playwright.config.js",
        "const port = Number(process.env.SLOT_PORT);\nexport default {\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: { baseURL: `http://127.0.0.1:${port}` },\n  webServer: { command: \"node support/server.js\", url: `http://127.0.0.1:${port}/health`, reuseExistingServer: false, timeout: 20000, env: { PORT: String(port) } },\n};\n",
    );
    project.write(
        "tests/serial.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest.describe.configure({ mode: \"serial\" });\nfor (const step of [1, 2, 3, 4, 5, 6]) {\n  test(`serial ${step}`, async ({ page }) => {\n    await page.goto(\"/\");\n    await expect(page.locator(\"#state\")).toHaveText(\"Active\");\n  });\n}\n",
    );
    project.write(
        "tests/zz-other.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"other\", async ({ page }) => {\n  await page.goto(\"/\");\n  await expect(page.locator(\"#state\")).toHaveText(\"Active\");\n});\n",
    );
    // Two slots, each a `playwright test` of its own share with its own
    // server; each lists its share first, as a harness that shares tests out
    // does.
    project.write(
        "harness.mjs",
        &format!(
            "import {{ spawn, spawnSync }} from \"node:child_process\";\n// Like a harness that tears its slots down itself: a termination does not\n// end it, and each slot is in a process group of its own.\nprocess.on(\"SIGTERM\", () => console.log(\"[harness] told to stop; waiting for the slots\"));\nconst slots = [[{}, \"tests/serial.spec.js\"], [{}, \"tests/zz-other.spec.js\"]];\n// The second slot starts first, and the first (the one given the serial file)\n// once the second has run a mutant: what the second takes of the serial file\n// is then the same however fast either starts.\nlet release;\nconst secondRan = new Promise((resolve) => {{\n  release = resolve;\n  setTimeout(resolve, 60_000);\n  // Measuring, nothing waits.\n  if (!process.env.SUPERCOV_STRONG_PLAN) resolve();\n}});\nconst run = ([port, file], at) => {{\n  const env = {{ ...process.env, SLOT_PORT: String(port) }};\n  const listed = spawnSync(\"npx\", [\"playwright\", \"test\", \"--list\", file], {{ env, encoding: \"utf8\" }});\n  for (const line of listed.stdout.split(\"\\n\")) if (line.includes(\".spec.js\")) console.log(`[list ${{at + 1}}] ${{line}}`);\n  return new Promise((done) => {{\n    const child = spawn(\"npx\", [\"playwright\", \"test\", file], {{ env, detached: true }});\n    const say = (chunk) => {{\n      for (const line of String(chunk).split(\"\\n\")) {{\n        if (!line.trim()) continue;\n        console.log(`[slot ${{at + 1}}] ${{line}}`);\n        if (at === 1 && line.includes('\" lives (')) release();\n      }}\n    }};\n    child.stdout.on(\"data\", say);\n    child.stderr.on(\"data\", say);\n    child.on(\"close\", (code) => {{\n      release();\n      done(code ?? 1);\n    }});\n  }});\n}};\nconst codes = await Promise.all([secondRan.then(() => run(slots[0], 0)), run(slots[1], 1)]);\nprocess.exit(Math.max(...codes));\n",
            ports[0], ports[1]
        ),
    );
    project.git(&["init", "-q"]);
    project.commit("strong playwright spread");
    let roots = ("SUPERCOV_SOURCE_ROOTS", "public");
    project
        .supercov_with(
            &["--", "node", "harness.mjs"],
            &[roots, ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    // A budget far shorter than the pass: it stops within the budget and a
    // short grace, and keeps what it decided and what its open mutants
    // passed.
    let budget = 25;
    let started = std::time::Instant::now();
    let out = project.supercov_with(
        &[
            "mutants",
            "--shard",
            "1/1",
            "--budget",
            &budget.to_string(),
            "--",
            "node",
            "harness.mjs",
        ],
        &[roots, ("SUPERCOV_VERBOSE", "1")],
    );
    let took = started.elapsed();
    let said = format!("{}\n{}", out.stdout(), out.stderr());
    eprintln!("budget {budget} s; the command took {took:?}");
    assert!(
        took < std::time::Duration::from_secs(budget + 15),
        "took {took:?}\n{said}"
    );
    assert!(
        said.contains(&format!("budget of {budget} s spent")),
        "{said}"
    );
}

/// A harness that runs two `playwright test` slots, each with its own
/// server, and keeps a spec file with a serial describe in the first: in a
/// strong pass that file runs in the second slot too, with the harness and
/// its command unchanged, and the slots share its mutants -- each mutant
/// meets each candidate once, whichever slot ran it -- while the harness's
/// `--list` still sees the slot's own file alone.
#[cfg(unix)]
#[test]
fn a_playwright_serial_file_is_spread_over_the_harness_s_slots() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let available = std::process::Command::new("node")
        .args(["--input-type=module", "-e", "import { chromium } from '@playwright/test'; import { existsSync } from 'node:fs'; process.exit(existsSync(chromium.executablePath()) ? 0 : 1)"])
        .current_dir(modules.parent().unwrap())
        .output()
        .is_ok_and(|output| output.status.success());
    if !available {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_BROWSER").is_none(),
            "Playwright and Chromium are required"
        );
        eprintln!("skipping: Playwright or Chromium is unavailable");
        return;
    }
    let ports = [0, 1].map(|_| common::free_port());
    let project = Project::empty("strong-playwright-spread");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-spread", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { readFileSync } from \"node:fs\";\nhttp.createServer((request, response) => {\n  const path = new URL(request.url, \"http://local\").pathname;\n  if (path === \"/health\") return response.end(\"ok\");\n  const file = path === \"/\" ? \"static/index.html\" : path.slice(1);\n  response.setHeader(\"content-type\", file.endsWith(\".js\") ? \"text/javascript\" : \"text/html\");\n  response.end(readFileSync(new URL(`../${file}`, import.meta.url)));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "static/index.html",
        "<!doctype html><body><p id=\"state\"></p><script src=\"/public/log.js\"></script><script>setTimeout(() => { document.getElementById(\"state\").textContent = \"Active\"; }, 700);</script></body>\n",
    );
    // What the page logs: no test reads it, so every mutant survives every
    // candidate.
    project.write(
        "public/log.js",
        "console.log(\"one\");\nconsole.log(\"two\");\nconsole.log(\"three\");\n",
    );
    project.write(
        "playwright.config.js",
        "const port = Number(process.env.SLOT_PORT);\nexport default {\n  testDir: \"tests\",\n  workers: 1,\n  reporter: \"line\",\n  use: { baseURL: `http://127.0.0.1:${port}` },\n  webServer: { command: \"node support/server.js\", url: `http://127.0.0.1:${port}/health`, reuseExistingServer: false, timeout: 20000, env: { PORT: String(port) } },\n};\n",
    );
    project.write(
        "tests/serial.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest.describe.configure({ mode: \"serial\" });\nfor (const step of [1, 2, 3, 4]) {\n  test(`serial ${step}`, async ({ page }) => {\n    await page.goto(\"/\");\n    await expect(page.locator(\"#state\")).toHaveText(\"Active\");\n  });\n}\n",
    );
    project.write(
        "tests/zz-other.spec.js",
        "import { test, expect } from \"@playwright/test\";\ntest(\"other\", async ({ page }) => {\n  await page.goto(\"/\");\n  await expect(page.locator(\"#state\")).toHaveText(\"Active\");\n});\n",
    );
    // Two slots, each a `playwright test` of its own share with its own
    // server; each lists its share first, as a harness that shares tests out
    // does.
    project.write(
        "harness.mjs",
        &format!(
            "import {{ spawn, spawnSync }} from \"node:child_process\";\nconst slots = [[{}, \"tests/serial.spec.js\"], [{}, \"tests/zz-other.spec.js\"]];\n// The second slot starts first, and the first (the one given the serial file)\n// once the second has run a mutant: what the second takes of the serial file\n// is then the same however fast either starts.\nlet release;\nconst secondRan = new Promise((resolve) => {{\n  release = resolve;\n  setTimeout(resolve, 60_000);\n  // Measuring, nothing waits.\n  if (!process.env.SUPERCOV_STRONG_PLAN) resolve();\n}});\nconst run = ([port, file], at) => {{\n  const env = {{ ...process.env, SLOT_PORT: String(port) }};\n  const listed = spawnSync(\"npx\", [\"playwright\", \"test\", \"--list\", file], {{ env, encoding: \"utf8\" }});\n  for (const line of listed.stdout.split(\"\\n\")) if (line.includes(\".spec.js\")) console.log(`[list ${{at + 1}}] ${{line}}`);\n  return new Promise((done) => {{\n    const child = spawn(\"npx\", [\"playwright\", \"test\", file], {{ env }});\n    const say = (chunk) => {{\n      for (const line of String(chunk).split(\"\\n\")) {{\n        if (!line.trim()) continue;\n        console.log(`[slot ${{at + 1}}] ${{line}}`);\n        if (at === 1 && line.includes('\" lives (')) release();\n      }}\n    }};\n    child.stdout.on(\"data\", say);\n    child.stderr.on(\"data\", say);\n    child.on(\"close\", (code) => {{\n      release();\n      done(code ?? 1);\n    }});\n  }});\n}};\nconst codes = await Promise.all([secondRan.then(() => run(slots[0], 0)), run(slots[1], 1)]);\nprocess.exit(Math.max(...codes));\n",
            ports[0], ports[1]
        ),
    );
    project.git(&["init", "-q"]);
    project.commit("strong playwright spread");
    let roots = ("SUPERCOV_SOURCE_ROOTS", "public");
    project
        .supercov_with(
            &["--", "node", "harness.mjs"],
            &[roots, ("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let out = project.supercov_with(
        &["runs", "latest", "mutants", "test"],
        &[
            roots,
            ("SUPERCOV_VERBOSE", "1"),
            ("SUPERCOV_PROGRESS_INTERVAL_MS", "300"),
        ],
    );
    let said = format!("{}\n{}", out.stdout(), out.stderr());
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap().clone();
    let context = format!(
        "{}\n{said}",
        mutants
            .iter()
            .map(|mutant| format!("{} {}", mutant["id"], mutant["strong"]))
            .collect::<Vec<_>>()
            .join("\n")
    );
    // The second slot ran the serial file too, and said so.
    assert!(
        said.contains("[slot 2] [supercov] strong pass: 1 spec file(s) with a serial describe run in this invocation too, each taking its own mutants of them: tests/serial.spec.js"),
        "{context}"
    );
    let serial_in_second = said
        .lines()
        .filter(|line| line.starts_with("[slot 2] [supercov] public/log.js:"))
        .filter(|line| line.contains(": \"serial "))
        .count();
    assert!(serial_in_second >= 1, "{context}");
    // Its own file's mutants had run against no candidate yet, so there it
    // took only mutants no copy had taken yet, anywhere: each at most once.
    for at in 1..=3 {
        let taken = said
            .lines()
            .filter(|line| line.starts_with(&format!("[slot 2] [supercov] public/log.js:{at}:")))
            .filter(|line| line.contains(": \"serial "))
            .count();
        assert!(taken <= 1, "{at}\n{context}");
    }
    // Its list was the slot's own file alone.
    assert!(said.contains("[list 2] "), "{context}");
    assert!(
        !said
            .lines()
            .any(|line| line.starts_with("[list 2] ") && line.contains("serial.spec.js")),
        "{context}"
    );
    // Each mutant met each candidate once, whichever slot ran it, and
    // survived all five.
    let on_log = mutants
        .iter()
        .filter(|mutant| mutant["id"].as_str().unwrap().starts_with("public/log.js:"))
        .collect::<Vec<_>>();
    assert_eq!(on_log.len(), 3, "{context}");
    for mutant in on_log {
        let id = mutant["id"].as_str().unwrap();
        assert_eq!(mutant["strong"]["status"], "survived", "{context}");
        assert_eq!(mutant["strong"]["tests"], 5, "{context}");
        let mut ran = said
            .lines()
            .filter_map(|line| line.split("[supercov] ").nth(1))
            .filter(|line| line.starts_with(&format!("{id}: \"")) && line.contains("\" lives ("))
            .map(|line| line.split('"').nth(1).unwrap().to_owned())
            .collect::<Vec<_>>();
        ran.sort();
        assert_eq!(
            ran,
            ["other", "serial 1", "serial 2", "serial 3", "serial 4"],
            "{id}\n{context}"
        );
    }
    // Nothing was confined to one slot.
    assert!(
        !said.contains("has a serial describe, and 1 of the"),
        "{context}"
    );
}

/// A measured Playwright run's plan carries each test's span, from the
/// fixture's record of the attempt (the reporter's record of the same
/// attempt has none), and a file whose tests ran side by side in a
/// `fullyParallel` project runs its strong attempts side by side too.
#[cfg(unix)]
#[test]
fn a_playwright_plan_has_spans_and_overlapping_tests_stay_parallel() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let port = common::free_port();
    let project = Project::empty("strong-playwright-spans");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-spans", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { double } from \"../server/app.js\";\nhttp.createServer((request, response) => {\n  const url = new URL(request.url, \"http://local\");\n  response.end(String(double(Number(url.searchParams.get(\"n\")))));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "server/app.js",
        "export function double(n) {\n  return n * 2;\n}\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "export default {{\n  testDir: \"tests\",\n  fullyParallel: true,\n  workers: 2,\n  reporter: \"line\",\n  use: {{ baseURL: \"http://127.0.0.1:{port}\" }},\n  webServer: {{ command: \"node support/server.js\", url: \"http://127.0.0.1:{port}/?n=1\", reuseExistingServer: false, timeout: 20000, env: {{ PORT: \"{port}\" }} }},\n}};\n"
        ),
    );
    // Each holds its worker a while: the two run at once. Measured, each
    // waits for the other to have started (`MEET`, a folder each notes its
    // start in): they overlap however late a loaded machine starts the
    // second worker. With 1.5 s alone, a second worker that started after
    // the first test had ended left the spans apart.
    project.write(
        "tests/double.spec.js",
        "import { test, expect } from \"@playwright/test\";\nimport { existsSync, writeFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nconst meet = async (n) => {\n  const folder = process.env.MEET;\n  if (!folder) return;\n  writeFileSync(join(folder, String(n)), \"\");\n  const other = join(folder, String(5 - n));\n  while (!existsSync(other)) await new Promise((done) => setTimeout(done, 20));\n};\nfor (const n of [2, 3]) {\n  test(`doubles ${n}`, async ({ request }) => {\n    await meet(n);\n    await new Promise((done) => setTimeout(done, 1500));\n    expect(await (await request.get(`/?n=${n}`)).text()).toBe(String(n * 2));\n  });\n}\n",
    );
    project.git(&["init", "-q"]);
    project.commit("spans");
    let roots = [("SUPERCOV_SOURCE_ROOTS", "server")];
    let meet = project.root.with_extension("meet");
    std::fs::create_dir_all(&meet).unwrap();
    let meeting = meet.display().to_string();
    project
        .supercov_with(
            &["--", "npx", "playwright", "test"],
            &[roots[0], ("MEET", meeting.as_str())],
        )
        .succeeds();
    let _ = std::fs::remove_dir_all(&meet);
    let plan = project
        .supercov_with(
            &["runs", "latest", "mutants", "test", "--plan", "--json"],
            &roots,
        )
        .json();
    let spans = plan["tests"]
        .as_array()
        .unwrap()
        .iter()
        .map(|test| {
            let span = &test["span"];
            (
                span[0]
                    .as_i64()
                    .unwrap_or_else(|| panic!("no span: {plan}")),
                span[1].as_i64().unwrap(),
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(spans.len(), 2, "{plan}");
    assert!(
        spans[0].0 < spans[1].1 && spans[1].0 < spans[0].1,
        "the two tests ran at once: {spans:?}"
    );
    let ran = project.supercov_with(&["runs", "latest", "mutants", "test", "--json"], &roots);
    let reply = ran.json();
    let main = reply["passes"]
        .as_array()
        .unwrap()
        .iter()
        .find(|pass| pass["pass"] == "main")
        .unwrap_or_else(|| panic!("no main pass\n{reply}\n{}", ran.stderr()))
        .clone();
    assert_eq!(main["serialFiles"], 0, "{main}\n{reply}");
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    assert_eq!(
        reply["summary"]["error"],
        0,
        "{reply}\n{listed}\n{}",
        ran.stderr()
    );
}

/// A Playwright plan of thousands of mutants, each with every test a
/// candidate, run under a 256 MB heap by a harness that lists the tests
/// first (`playwright test --list --reporter=json`) and then runs a
/// Playwright process a spec file at once, each with a server of its own,
/// started a second apart. The list reads no plan and lists each test once;
/// the main pass holds only as many copies of the tests as an invocation
/// may, and the mutants past them run in further invocations; each process
/// runs its first test within seconds, none undoes another's work, and each
/// mutant gets one verdict from whichever process ran it. Before, the list
/// and the runner each made every repetition of every test, as many as the
/// busiest file had mutants, and ran out of heap; and each process cleared
/// the pass's files as it started, so the others waited on baselines that
/// were gone. A process that does run out of heap is named.
#[cfg(unix)]
#[test]
fn a_large_playwright_plan_runs_in_a_small_heap() {
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    let held = (0..3).map(|_| common::free_port()).collect::<Vec<_>>();
    let ports = held.iter().map(ToString::to_string).collect::<Vec<_>>();
    let project = Project::empty("strong-playwright-heap");
    project.write(
        "package.json",
        r#"{ "name": "strong-playwright-heap", "private": true, "type": "module" }"#,
    );
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    project.write(".gitignore", "node_modules\n.supercov\n");
    // About ten thousand mutants, every one reached by every test.
    const FUNCTIONS: usize = 1500;
    let mut app = String::new();
    for index in 0..FUNCTIONS {
        app.push_str(&format!(
            "function f{index}(n) {{\n  return n > {index} ? n + {index} : n - 1;\n}}\n"
        ));
    }
    app.push_str(&format!(
        "const all = [{}];\nexport function total(n) {{\n  let sum = 0;\n  for (const f of all) sum += f(n);\n  return sum;\n}}\n",
        (0..FUNCTIONS)
            .map(|index| format!("f{index}"))
            .collect::<Vec<_>>()
            .join(", ")
    ));
    project.write("server/app.js", &app);
    project.write(
        "support/server.js",
        "import http from \"node:http\";\nimport { total } from \"../server/app.js\";\nhttp.createServer((request, response) => {\n  const url = new URL(request.url, \"http://local\");\n  response.end(String(total(Number(url.searchParams.get(\"n\")))));\n}).listen(Number(process.env.PORT));\n",
    );
    project.write(
        "playwright.config.js",
        &format!(
            "const port = process.env.SLOT_PORT ?? \"{}\";\nexport default {{\n  testDir: \"tests\",\n  workers: 4,\n  reporter: \"line\",\n  use: {{ baseURL: `http://127.0.0.1:${{port}}` }},\n  webServer: {{ command: \"node support/server.js\", url: `http://127.0.0.1:${{port}}/?n=1`, reuseExistingServer: false, timeout: 20000, env: {{ PORT: port }} }},\n}};\n",
            ports[0]
        ),
    );
    // Three files of ten tests, each asking for a total of its own.
    for file in 0..3 {
        project.write(
            &format!("tests/total{file}.spec.js"),
            &format!(
                "import {{ test, expect }} from \"@playwright/test\";\nconst expected = (n) => {{\n  let sum = 0;\n  for (let i = 0; i < {FUNCTIONS}; i++) sum += n > i ? n + i : n - 1;\n  return sum;\n}};\nfor (const n of [{}]) {{\n  test(`totals ${{n}}`, async ({{ request }}) => {{\n    expect(await (await request.get(`/?n=${{n}}`)).text()).toBe(String(expected(n)));\n  }});\n}}\n",
                (0..10)
                    .map(|test| (file * 10 + test) * 53 % FUNCTIONS)
                    .map(|n| n.to_string())
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
        );
    }
    // The harness: Playwright's list of the tests, then a process a file,
    // each with its own server, started a second apart, as a harness that
    // copies a build for each slot starts them. It notes when it listed.
    let listed = project.root.with_extension("listed.txt");
    project.write(
        "e2e.mjs",
        &format!(
            "import {{ execFileSync, spawn }} from \"node:child_process\";\nimport {{ appendFileSync }} from \"node:fs\";\nconst listed = JSON.parse(execFileSync(\"npx\", [\"playwright\", \"test\", \"--list\", \"--reporter=json\"], {{ maxBuffer: 1 << 30 }}).toString());\nlet count = 0;\nconst visit = (suite) => {{\n  for (const spec of suite.specs ?? []) count += spec.tests.length;\n  (suite.suites ?? []).forEach(visit);\n}};\nlisted.suites.forEach(visit);\nappendFileSync(process.env.LISTED, `${{count}} ${{Date.now()}}\\n`);\nconst ports = {ports:?};\nconst codes = await Promise.all(ports.map((port, slot) => new Promise((done) => setTimeout(() => {{\n  const child = spawn(\"npx\", [\"playwright\", \"test\", `tests/total${{slot}}.spec.js`], {{ stdio: \"inherit\", env: {{ ...process.env, SLOT_PORT: port }} }});\n  child.on(\"close\", done);\n}}, slot * 1000))));\nprocess.exit(codes.every((code) => code === 0) ? 0 : 1);\n"
        ),
    );
    // A process that runs out of heap however large its heap.
    project.write(
        "support/hog.js",
        "const kept = [];\nfor (;;) kept.push({ at: kept.length });\n",
    );
    project.git(&["init", "-q"]);
    project.commit("a large plan");
    let listed_env = listed.display().to_string();
    let roots = [
        ("SUPERCOV_SOURCE_ROOTS", "server"),
        ("LISTED", listed_env.as_str()),
    ];
    // How long the suite takes on this machine, list and all.
    let measuring = std::time::Instant::now();
    project
        .supercov_with(&["--", "node", "e2e.mjs"], &roots)
        .succeeds();
    let measuring = measuring.elapsed().as_secs();
    let _ = std::fs::remove_file(&listed);
    let planning = std::time::Instant::now();
    let plan = project
        .supercov_with(
            &["runs", "latest", "mutants", "test", "--plan", "--json"],
            &roots,
        )
        .json();
    let planning = planning.elapsed().as_secs();
    let planned = plan["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|mutant| mutant["decided"].is_null())
        .count();
    assert!(planned > 5_000, "{planned} mutants to run");
    // Every process of the pass in a 256 MB heap; sixty copies of the tests
    // an invocation (about seven mutants), so that a minute sees several
    // even on a slow runner: with six hundred an ARM runner's first
    // invocation used the whole minute, and with a hundred and twenty a
    // macOS runner's. The budget counts planning too, which takes a slow
    // runner most of a minute here: the pass gets its minute after it, or
    // four times the suite's own run where that is longer. A fixed minute
    // was spent by the first round on a slow arm64 or macOS runner, and the
    // budget ended the second invocation before it had listed the tests.
    let budget = (60.max(4 * measuring) + 2 * planning).to_string();
    let ran = project.supercov_with(
        &[
            "runs", "latest", "mutants", "test", "--json", "--budget", &budget,
        ],
        &[
            roots[0],
            roots[1],
            ("NODE_OPTIONS", "--max-old-space-size=256"),
            ("SUPERCOV_PLAYWRIGHT_COPIES", "60"),
            // Its attempts, kept to time them.
            ("SUPERCOV_STRONG_KEEP", "1"),
        ],
    );
    let said = ran.stderr();
    let reply = ran.json();
    let context = format!("{reply}\n{said}");
    assert!(!said.contains("ran out of memory"), "{context}");
    assert!(!said.contains("heap out of memory"), "{context}");
    // Each slot's server is checked for readiness while the slots before it
    // run their tests: such a request names no test, but none of those
    // tests is this server's, so the mutants it ran are not taken for ones
    // a test reached without its name. Taken so, 6,351 of them went to run
    // alone, and that round ran out of heap.
    let main_pass = reply["passes"]
        .as_array()
        .and_then(|passes| passes.iter().find(|pass| pass["pass"] == "main"))
        .cloned()
        .unwrap_or_default();
    assert!(
        main_pass["next"]["alone"].as_u64() < Some(10),
        "{main_pass}\n{context}"
    );
    // The list saw the project's thirty tests, once each, every time it
    // finished: the budget ends the invocation it falls in, which may be
    // listing. That the pass went on to further invocations is asserted
    // below from its own record.
    let counts = std::fs::read_to_string(&listed).unwrap_or_default();
    let _ = std::fs::remove_file(&listed);
    let listings = counts
        .lines()
        .map(|line| line.split_once(' ').unwrap())
        .collect::<Vec<_>>();
    assert!(!listings.is_empty(), "{counts}\n{context}");
    assert!(
        listings.iter().all(|(count, _)| *count == "30"),
        "{counts}\n{context}"
    );
    // The main pass's three processes each began its tests within seconds
    // of being started (a second apart, after the list), whatever the
    // plan's size: each runner's status says when (one whose tests' mutants
    // were all decided by then runs none of them).
    let listed_at = listings[0].1.parse::<i64>().unwrap();
    let status = std::fs::read_dir(project.root.join(".supercov/strong"))
        .unwrap()
        .flatten()
        .map(|work| work.path().join("playwright/status"))
        .find(|status| status.is_dir())
        .unwrap_or_else(|| panic!("no status kept\n{context}"));
    let mut began = std::collections::BTreeMap::new();
    for runner in std::fs::read_dir(&status).unwrap().flatten() {
        let runner: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(runner.path()).unwrap()).unwrap();
        if runner["round"] == "main" {
            began.insert(
                runner["pid"].to_string(),
                runner["startedAt"].as_i64().unwrap(),
            );
        }
    }
    assert_eq!(began.len(), 3, "{began:?}\n{context}");
    let waits = began
        .values()
        .map(|started| started - listed_at)
        .collect::<Vec<_>>();
    eprintln!("first test of each process, ms after the list: {waits:?}");
    assert!(
        waits.iter().all(|wait| *wait < 20_000),
        "{waits:?}\n{context}"
    );
    // One verdict a mutant, and none an error: no baseline went missing.
    assert_eq!(reply["summary"]["error"], 0, "{context}");
    // The main pass went on in further invocations, and killed mutants in
    // them.
    let mains = reply["passes"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|pass| pass["kind"] == "main")
        .count();
    assert!(mains >= 2, "{context}");
    assert!(
        said.contains("main (more copies than one invocation holds)"),
        "{context}"
    );
    assert!(reply["summary"]["killed"].as_u64() > Some(5), "{context}");
    // A command that runs out of heap: the process is named, and so is
    // why each mutant has no verdict.
    let ran = project.supercov_with(
        &[
            "runs",
            "latest",
            "mutants",
            "test",
            "--json",
            "--",
            "node",
            "--max-old-space-size=64",
            "support/hog.js",
        ],
        &roots,
    );
    let said = ran.stderr();
    let reply = ran.json();
    let context = format!("{reply}\n{said}");
    assert!(
        said.contains("[supercov] a Node process ran out of memory at its")
            && said.contains("support/hog.js (pid "),
        "{context}"
    );
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let reasons = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|mutant| mutant["strong"]["reason"].as_str())
        .filter(|reason| {
            reason.contains("before this mutant's verdict: a Node process ran out of memory")
        })
        .collect::<Vec<_>>();
    assert!(
        !reasons.is_empty()
            && reasons
                .iter()
                .all(|reason| reason.contains("support/hog.js")),
        "{reasons:?}\n{context}"
    );
}

/// A test that passes only after an earlier test of its file ran: its file
/// runs whole for the mutants it can kill, so the mutant it kills is killed,
/// as StrykerJS (which runs the file's tests in order) kills it.
#[cfg(unix)]
#[test]
fn a_test_that_leans_on_an_earlier_one_still_kills_its_mutants() {
    let project = vitest_mutants_project("strong-ordered-tests");
    project.write(
        "src/registry.js",
        "let built = false;\nexport function build() {\n  built = true;\n}\nexport function add() {\n  if (built) {\n    throw new Error(\"already built\");\n  }\n  return 1;\n}\n",
    );
    project.write(
        "test/registry.test.js",
        "import { expect, it } from \"vitest\";\nimport { add, build } from \"../src/registry.js\";\nit(\"adds before the build\", () => expect(add()).toBe(1));\nit(\"builds\", () => build());\nit(\"refuses to add after the build\", () => expect(() => add()).toThrow(\"already built\"));\n",
    );
    project.commit("registry");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/registry.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let throw = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        // `if (built)` to `if (false)`: only the last test, after the second
        // built, can tell.
        .find(|mutant| mutant["id"] == "src/registry.js:6:7-6:12:ConditionalExpression:false")
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(throw["strong"]["status"], "killed", "{throw}");
}

/// A mutant only a later test reaches, where that test leans on an earlier
/// one the mutant's copy leaves out: the later test fails alone with or
/// without the mutant, so that failure is no kill. The file runs whole for
/// the mutant, where the test passes: the mutant survives, as it does in a
/// run of the whole suite.
#[cfg(unix)]
#[test]
fn a_test_that_fails_without_its_predecessor_kills_no_mutant() {
    let project = vitest_mutants_project("strong-subset-false-kill");
    // `if (item)` gives the first test mutants of its own, so the file's
    // baseline runs both tests and the second passes there.
    project.write(
        "src/items.js",
        "const items = [];\nexport function register(item) {\n  if (item) items.push(item);\n}\nexport function count() {\n  return items.length > 0 ? items.length : 0;\n}\n",
    );
    project.write(
        "test/items.test.js",
        "import { expect, it } from \"vitest\";\nimport { count, register } from \"../src/items.js\";\nit(\"registers\", () => register(\"a\"));\nit(\"counts what was registered\", () => expect(count()).toBe(1));\n",
    );
    project.commit("items");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    let pass = &reply["passes"][0];
    assert!(pass["overturned"].as_u64().unwrap_or(0) > 0, "{reply}");
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/items.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    // `items.length > 0` to `items.length >= 0`: the count is the same.
    let equal = mutants
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/items.js:6:") && id.contains(":EqualityOperator:")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(equal["strong"]["status"], "survived", "{equal}");
    // `items.length > 0 ? ... : 0` to `... false ...`: the count is 0, and
    // the test fails with its predecessor run too.
    let never = mutants
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/items.js:6:") && id.ends_with(":ConditionalExpression:false")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(never["strong"]["status"], "killed", "{never}");
}

/// The same, where no mutant of module-level code has the file run whole
/// already: a kill a test left out caused is overturned, and the mutant runs
/// the file whole once its whole baseline, run for it, is known.
#[cfg(unix)]
#[test]
fn an_overturned_kill_runs_its_file_whole_after_its_whole_baseline() {
    let project = vitest_mutants_project("strong-overturn-whole");
    project.write(
        "src/items.js",
        "const state = {};\nexport function register(item) {\n  if (item) (state.items ??= []).push(item);\n}\nexport function count() {\n  const items = state.items ?? [];\n  return items.length > 0 ? items.length : 0;\n}\n",
    );
    project.write(
        "test/items.test.js",
        "import { expect, it } from \"vitest\";\nimport { count, register } from \"../src/items.js\";\nit(\"registers\", () => register(\"a\"));\nit(\"counts what was registered\", () => expect(count()).toBe(1));\n",
    );
    project.commit("items");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    assert!(
        reply["passes"][0]["overturned"].as_u64().unwrap_or(0) > 0,
        "{reply}"
    );
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/items.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let equal = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/items.js:7:") && id.contains(":EqualityOperator:")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(equal["strong"]["status"], "survived", "{equal}");
}

/// A mutant that makes work a test left running loop forever (a timer that
/// fires after the test passed): its evaluations pass the limit outside any
/// test, and the mutant is a timeout, not a survivor.
#[cfg(unix)]
#[test]
fn a_mutant_that_loops_forever_after_its_test_passed_is_a_timeout() {
    let project = vitest_mutants_project("strong-outside-tests");
    project.write(
        "src/poll.js",
        "export function poll(items) {\n  setTimeout(() => {\n    let i = 0;\n    while (i < items.length) {\n      i++;\n    }\n  }, 1);\n  return items.length;\n}\n",
    );
    project.write(
        "test/poll.test.js",
        "import { expect, it } from \"vitest\";\nimport { poll } from \"../src/poll.js\";\nit(\"polls\", async () => {\n  expect(poll([1, 2])).toBe(2);\n  await new Promise((resolve) => setTimeout(resolve, 20));\n});\nit(\"waits\", async () => {\n  await new Promise((resolve) => setTimeout(resolve, 50));\n});\n",
    );
    project.commit("poll");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/poll.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let endless = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["id"] == "src/poll.js:5:7-5:10:UpdateOperator:--")
        .unwrap_or_else(|| panic!("{listed}"));
    assert!(
        matches!(
            endless["strong"]["status"].as_str(),
            Some("timeout" | "killed")
        ),
        "{endless}"
    );
}

/// A mutant that leaves a module's top-level `await` waiting forever: its
/// test file never loads, so no test's limit can end it. Once its copy is
/// past its limit (three times its file's baseline, and ten seconds), the
/// copy's worker is stopped and the mutant is a timeout, in the same pass:
/// the stage goes on, no deadline to wait out, no second pass.
#[cfg(unix)]
#[test]
fn a_mutant_that_leaves_an_import_waiting_forever_is_a_timeout_in_the_same_pass() {
    let project = vitest_mutants_project("strong-import-waits");
    project.write(
        "src/ready.js",
        "export const ready = await new Promise((resolve) => {\n  if (globalThis.Date) resolve(true);\n});\n\nexport function double(n) {\n  return n * 2;\n}\n",
    );
    project.write(
        "test/ready.test.js",
        "import { expect, it } from \"vitest\";\nimport { double, ready } from \"../src/ready.js\";\nit(\"is ready\", () => expect(ready).toBe(true));\nit(\"doubles\", () => expect(double(2)).toBe(4));\n",
    );
    project.commit("ready");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    let passes = reply["passes"].as_array().unwrap();
    assert_eq!(passes.len(), 1, "{reply}");
    assert_eq!(passes[0]["stalled"], false, "{reply}");
    assert!(
        passes[0]["profile"]["hungCopies"].as_u64().unwrap_or(0) >= 1,
        "{reply}"
    );
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/ready.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let never = mutants
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/ready.js:2:") && id.ends_with(":ConditionalExpression:false")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(never["strong"]["status"], "timeout", "{never}");
    // The stage went on past the stopped copy: every mutant of the file
    // has a verdict of its own.
    let doubled = mutants
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/ready.js:6:") && id.contains(":ArithmeticOperator:")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(doubled["strong"]["status"], "killed", "{doubled}");
}

/// A pass says how far it got while it runs (here every 100 ms): before any
/// verdict, how many mutants it has to run; once there are verdicts, how
/// they stand and the time left at this pace. `inc`'s mutants survive the
/// quick file, which runs first, and run again in the slow one in a later
/// stage, after `dbl`'s verdicts.
#[cfg(unix)]
#[test]
fn a_running_pass_says_how_far_it_got() {
    let project = vitest_mutants_project("strong-progress");
    project.write(
        "src/steps.js",
        "export function inc(n) {\n  return n + 1;\n}\n\nexport function dbl(n) {\n  return n * 2;\n}\n",
    );
    project.write(
        "test/quick.test.js",
        "import { expect, it } from \"vitest\";\nimport { dbl, inc } from \"../src/steps.js\";\nit(\"runs inc\", () => {\n  inc(1);\n});\nit(\"doubles\", () => expect(dbl(2)).toBe(4));\n",
    );
    project.write(
        "test/slow.test.js",
        "import { expect, it } from \"vitest\";\nimport { inc } from \"../src/steps.js\";\nit(\"increments\", async () => {\n  await new Promise((resolve) => setTimeout(resolve, 400));\n  expect(inc(1)).toBe(2);\n});\n",
    );
    project.commit("steps");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let ran = project.supercov_with(
        &["runs", "latest", "mutants", "test", "--json"],
        &[("SUPERCOV_PROGRESS_INTERVAL_MS", "100")],
    );
    let reply = ran.json();
    let said = ran.stderr();
    let lines = said
        .lines()
        .filter(|line| line.starts_with("[supercov] strong pass: ") && line.contains(" mutants ("))
        .collect::<Vec<_>>();
    let to_run = reply["summary"]["ran"].as_u64().unwrap();
    assert!(
        lines.iter().any(|line| line.starts_with(&format!(
            "[supercov] strong pass: 0 of {to_run} mutants (0 killed, 0 timed out, 0 survived, 0 errors), "
        )) && !line.contains(" left")),
        "{said}"
    );
    assert!(
        lines.iter().any(|line| !line.contains(": 0 of ")
            && line.contains("; about ")
            && line.ends_with(" left")),
        "{said}"
    );
}

/// A pass runs in stages, each one run of all it holds: every mutant's
/// cheapest file beside that file's baseline, and each mutant's next batch
/// of other files, the likeliest killer first (nothing learned yet: the
/// cheapest), held back after them until the mutant's copy before has ended.
/// `inc`'s mutants survive `a`, which only calls it; the next batch is one
/// file, the quick `c`, which kills each of them, so the slow `b` never runs:
/// two copies each (the fixture's `cart.js` mutants have one test file, and
/// one copy each). A held-back copy whose mutant was killed first ends with
/// no process.
#[cfg(unix)]
#[test]
fn a_mutant_runs_its_later_files_in_batches_likeliest_killer_first() {
    let project = vitest_mutants_project("strong-skip");
    project.write(
        "vitest.config.js",
        "export default { test: { maxWorkers: 1 } };\n",
    );
    project.write(
        "src/steps.js",
        "export function inc(n) {\n  return n + 1;\n}\n",
    );
    project.write(
        "test/a.test.js",
        "import { it } from \"vitest\";\nimport { inc } from \"../src/steps.js\";\nit(\"runs inc\", () => {\n  inc(1);\n});\n",
    );
    project.write(
        "test/b.test.js",
        "import { expect, it } from \"vitest\";\nimport { inc } from \"../src/steps.js\";\nit(\"increments slowly\", async () => {\n  await new Promise((resolve) => setTimeout(resolve, 600));\n  expect(inc(1)).toBe(2);\n});\n",
    );
    project.write(
        "test/c.test.js",
        "import { expect, it } from \"vitest\";\nimport { inc } from \"../src/steps.js\";\nit(\"increments\", async () => {\n  await new Promise((resolve) => setTimeout(resolve, 50));\n  expect(inc(1)).toBe(2);\n});\n",
    );
    project.commit("steps");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    let passes = reply["passes"].as_array().unwrap();
    assert_eq!(passes.len(), 1, "{reply}");
    let ran = reply["summary"]["ran"].as_u64().unwrap();
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/steps.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let killed = mutants
        .iter()
        .filter(|mutant| mutant["strong"]["status"] == "killed")
        .count() as u64;
    assert!(killed >= 2, "{listed}");
    assert!(
        mutants
            .iter()
            .all(|mutant| mutant["strong"]["status"] != "survived"),
        "{listed}"
    );
    // One more copy for each kill a confirmation overturned (the mutant
    // runs its file whole), and each a worker took beside its mutant's
    // running copy, no other mutant waiting: the cheapest run first, so
    // `inc`'s chains come last, with the one worker otherwise idle.
    assert!(
        passes[0]["profile"]["mutantCopies"].as_u64().unwrap_or(0)
            <= ran
                + killed
                + passes[0]["overturned"].as_u64().unwrap_or(0)
                + passes[0]["profile"]["besideCopies"].as_u64().unwrap_or(0),
        "{reply}"
    );
    assert!(
        passes[0]["profile"]["skippedCopies"].as_u64().unwrap_or(0) <= killed,
        "{reply}"
    );
    assert!(passes[0]["stages"].as_u64().unwrap_or(0) <= 2, "{reply}");
}

/// A mutant that makes a module throw while it loads: its copy's test file
/// never loads, and its worker ends without the copy's end. That is a kill
/// as soon as the worker is gone (the test file did not finish), not a copy
/// that stopped reporting: no worker is stopped and none counts as hung.
#[cfg(unix)]
#[test]
fn a_mutant_that_breaks_its_test_file_s_load_is_killed_once_its_worker_ends() {
    let project = vitest_mutants_project("strong-load-throws");
    project.write(
        "src/config.js",
        "const settings = { strict: true };\nif (!settings.strict) throw new Error(\"not strict\");\nexport const strict = settings.strict;\n",
    );
    project.write(
        "test/config.test.js",
        "import { expect, it } from \"vitest\";\nimport { strict } from \"../src/config.js\";\nit(\"is strict\", () => expect(strict).toBe(true));\n",
    );
    project.commit("config");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    let passes = reply["passes"].as_array().unwrap();
    assert_eq!(passes.len(), 1, "{reply}");
    assert_eq!(passes[0]["profile"]["killedCopies"], 0, "{reply}");
    assert_eq!(passes[0]["profile"]["hungCopies"], 0, "{reply}");
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/config.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    let throws = mutants
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/config.js:2:") && id.ends_with(":ConditionalExpression:true")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(throws["strong"]["status"], "killed", "{throws}");
    assert_eq!(
        throws["strong"]["reason"], "the test file did not finish",
        "{throws}"
    );
}

/// Vitest 4 and later fork the strong pass's workers through Supercov's
/// spawner, a small process of its own, not from Vitest's (which a fork
/// copies, a gigabyte on a large suite); `SUPERCOV_STRONG_DIRECT_FORK=1`
/// forks them from Vitest's. Either way each mutant gets the same verdict.
#[cfg(unix)]
#[test]
fn a_strong_pass_forks_its_workers_through_a_spawner_with_the_same_verdicts() {
    let project = vitest_mutants_project("strong-spawner");
    let verdicts = |direct: bool| {
        project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
        let env: &[(&str, &str)] = if direct {
            &[("SUPERCOV_STRONG_DIRECT_FORK", "1")]
        } else {
            &[]
        };
        let reply = project
            .supercov_with(&["runs", "latest", "mutants", "test", "--json"], env)
            .json();
        let listed = project
            .supercov(&[
                "runs",
                "latest",
                "mutants",
                "src/cart.js",
                "--json",
                "--limit",
                "0",
            ])
            .json();
        let statuses = listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .map(|mutant| {
                (
                    mutant["id"].as_str().unwrap().to_owned(),
                    mutant["strong"]["status"].to_string(),
                )
            })
            .collect::<std::collections::BTreeMap<_, _>>();
        (
            reply["passes"][0]["profile"]["spawnedWorkers"].as_u64(),
            statuses,
        )
    };
    let (spawned, through) = verdicts(false);
    assert!(spawned.unwrap_or(0) > 0, "{spawned:?}");
    let (none, direct) = verdicts(true);
    assert_eq!(none, Some(0));
    assert!(!through.is_empty());
    assert_eq!(through, direct);
}

/// The spawner keeps workers started ahead of Vitest's requests, and a copy
/// that gets one sees the process a fresh worker is: Vitest's worker entry
/// as its script, nothing of Supercov's in its environment (a test file that
/// sees otherwise fails to load, and kills what survives). Started ahead or
/// not (`SUPERCOV_STRONG_WORKERS_AHEAD=0`), each mutant gets the same verdict.
#[cfg(unix)]
#[test]
fn a_copy_in_a_worker_started_ahead_gets_the_verdict_a_fresh_worker_gives() {
    let project = vitest_mutants_project("strong-ahead");
    project.write(
        "test/cart.test.js",
        "import { describe, expect, it } from \"vitest\";\nimport { shipping, label } from \"../src/cart.js\";\nif (!/[\\\\/]workers[\\\\/]forks\\.js$/.test(process.argv[1] ?? \"\")) throw new Error(`not Vitest's worker: ${process.argv[1]}`);\nif (\"SUPERCOV_STRONG_WORKER\" in process.env) throw new Error(\"Supercov's worker variable is set\");\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\n  it(\"charges small orders\", () => expect(shipping(10)).toBe(5));\n  it(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n});\n",
    );
    project.commit("worker checks");
    let verdicts = |ahead: &str| {
        // One worker: its copies run one after another, so most get a
        // worker started while the one before ran.
        project
            .supercov(&["--", "npx", "vitest", "run", "--maxWorkers=1"])
            .succeeds();
        let reply = project
            .supercov_with(
                &["runs", "latest", "mutants", "test", "--json"],
                &[("SUPERCOV_STRONG_WORKERS_AHEAD", ahead)],
            )
            .json();
        assert_eq!(reply["summary"]["error"], 0, "{reply}");
        let listed = project
            .supercov(&[
                "runs",
                "latest",
                "mutants",
                "src/cart.js",
                "--json",
                "--limit",
                "0",
            ])
            .json();
        let statuses = listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .map(|mutant| {
                (
                    mutant["id"].as_str().unwrap().to_owned(),
                    mutant["strong"]["status"].to_string(),
                )
            })
            .collect::<std::collections::BTreeMap<_, _>>();
        (
            reply["passes"][0]["profile"]["usedAhead"].as_u64(),
            statuses,
        )
    };
    let (used, ahead) = verdicts("4");
    assert!(used.unwrap_or(0) > 0, "{used:?}");
    let (none, fresh) = verdicts("0");
    assert_eq!(none.unwrap_or(0), 0);
    assert!(ahead.values().any(|status| status == "\"killed\""));
    assert!(ahead.values().any(|status| status == "\"survived\""));
    assert_eq!(ahead, fresh);
}

/// A mutant that makes a worker drop its channel to Vitest (here it
/// disconnects): Vitest cannot hear the file finish, so it did not, and the
/// mutant is killed whatever the copy wrote. Nothing reports a closed
/// channel as an error of the run, and the pass runs once.
#[cfg(unix)]
#[test]
fn a_worker_that_drops_its_channel_fails_its_file_and_the_pass_runs_once() {
    let project = vitest_mutants_project("strong-channel-closed");
    project.write(
        "src/bye.js",
        "export function bye(flag) {\n  if (flag) process.disconnect?.();\n  return 1;\n}\n",
    );
    project.write(
        "test/bye.test.js",
        "import { expect, it } from \"vitest\";\nimport { bye } from \"../src/bye.js\";\nit(\"stays\", () => expect(bye(false)).toBe(1));\n",
    );
    project.commit("bye");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let ran = project.supercov(&["runs", "latest", "mutants", "test", "--json"]);
    let said = ran.stderr();
    let reply = ran.json();
    assert!(!said.contains("Channel closed"), "{said}");
    assert!(!said.contains("Unhandled"), "{said}");
    assert_eq!(reply["passes"].as_array().map(Vec::len), Some(1), "{reply}");
    assert_eq!(
        said.matches("strong pass: switches in").count(),
        1,
        "{said}"
    );
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/bye.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let disconnects = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/bye.js:2:") && id.ends_with(":ConditionalExpression:true")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(disconnects["strong"]["status"], "killed", "{disconnects}");
}

/// Under Vitest 3 the workers are tinypool's processes. A worker that loses
/// its channel (one the pass stops once a failed test decided its copy, or
/// one a mutant disconnects or ends) made tinypool 1.1's next write to it
/// fail with "Channel closed", which ended Vitest 3.2's run and left most
/// mutants errors in every pass. Its exit tells tinypool it is gone: the pass
/// runs once, with no error, and those mutants are killed.
#[cfg(unix)]
#[test]
fn a_vitest_3_worker_that_loses_its_channel_ends_no_pass() {
    let project = Project::empty("strong-vitest-3-channel");
    project.write(
        "package.json",
        r#"{ "name": "mutants", "type": "module", "scripts": { "test": "vitest run" } }"#,
    );
    let installed = std::process::Command::new("npm")
        .args([
            "install",
            "--no-audit",
            "--no-fund",
            "--silent",
            "vitest@3.2.4",
        ])
        .current_dir(&project.root)
        .output()
        .is_ok_and(|output| output.status.success());
    if !installed {
        assert!(
            std::env::var_os("SUPERCOV_REQUIRE_VITEST_3").is_none(),
            "Vitest 3 could not be installed"
        );
        eprintln!("skipping: Vitest 3 could not be installed");
        return;
    }
    project.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "src/cart.js",
        "export function shipping(sum) {\n  if (sum >= 50) {\n    return 0;\n  }\n  return 5;\n}\n\nexport function label(name) {\n  return name.trim().toUpperCase();\n}\n\nexport function bye(flag) {\n  if (flag) process.disconnect?.();\n  return 1;\n}\n\nexport function quit(flag) {\n  if (flag) process.exit(3);\n  return 2;\n}\n",
    );
    project.write(
        "test/cart.test.js",
        "import { describe, expect, it } from \"vitest\";\nimport { shipping, label, bye, quit } from \"../src/cart.js\";\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\n  it(\"charges small orders\", () => expect(shipping(10)).toBe(5));\n  it(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n  it(\"stays\", () => expect(bye(false)).toBe(1));\n  it(\"keeps going\", () => expect(quit(false)).toBe(2));\n  for (let i = 0; i < 20; i++) it(`waits ${i}`, async () => { await new Promise((done) => setTimeout(done, 20)); expect(shipping(10)).toBe(5); });\n});\n",
    );
    project.git(&["init", "-q"]);
    project.commit("mutants");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let ran = project.supercov(&["runs", "latest", "mutants", "test", "--json"]);
    let said = ran.stderr();
    let reply = ran.json();
    assert!(!said.contains("Unhandled"), "{said}");
    assert_eq!(reply["passes"].as_array().map(Vec::len), Some(1), "{reply}");
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/cart.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    for line in ["src/cart.js:13:", "src/cart.js:18:"] {
        let dropping = mutants
            .iter()
            .find(|mutant| {
                let id = mutant["id"].as_str().unwrap_or_default();
                id.starts_with(line) && id.ends_with(":ConditionalExpression:true")
            })
            .unwrap_or_else(|| panic!("{listed}"));
        assert_eq!(dropping["strong"]["status"], "killed", "{dropping}");
    }
    assert!(
        mutants
            .iter()
            .filter(|mutant| mutant["strong"]["status"] == "killed")
            .count()
            > 4,
        "{listed}"
    );
}

/// A continuous pass gives each Vitest run a bounded number of slots (Vitest
/// reads every slot's file as the run starts): a pass that needs more runs
/// again, in the same pass, with the verdicts one run gives.
#[cfg(unix)]
#[test]
fn a_pass_with_more_copies_than_a_run_has_slots_runs_again_with_the_same_verdicts() {
    let project = vitest_mutants_project("strong-run-slots");
    project.write(
        "test/refund.test.js",
        "import { expect, it } from \"vitest\";\nimport { refund } from \"../src/cart.js\";\nit(\"refunds big orders less\", () => expect(refund(200)).toBe(180));\nit(\"refunds small orders whole\", () => expect(refund(50)).toBe(50));\n",
    );
    project.commit("refunds");
    let verdicts = |slots: &str| {
        project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
        let reply = project
            .supercov_with(
                &["runs", "latest", "mutants", "test", "--json"],
                &[("SUPERCOV_STRONG_RUN_SLOTS", slots)],
            )
            .json();
        let listed = project
            .supercov(&[
                "runs",
                "latest",
                "mutants",
                "src/cart.js",
                "--json",
                "--limit",
                "0",
            ])
            .json();
        let statuses = listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .map(|mutant| {
                (
                    mutant["id"].as_str().unwrap_or_default().to_owned(),
                    mutant["strong"]["status"].clone(),
                )
            })
            .collect::<std::collections::BTreeMap<_, _>>();
        (reply, statuses)
    };
    let (one_run, expected) = verdicts("");
    let (runs, statuses) = verdicts("1");
    assert_eq!(
        one_run["passes"][0]["profile"]["continuousRuns"], 1,
        "{one_run}"
    );
    assert!(
        runs["passes"][0]["profile"]["continuousRuns"]
            .as_u64()
            .unwrap_or(0)
            > 1,
        "{runs}"
    );
    assert_eq!(runs["passes"].as_array().map(Vec::len), Some(1), "{runs}");
    assert_eq!(runs["summary"]["error"], 0, "{runs}");
    assert!(
        expected.values().any(|status| status == "killed"),
        "{expected:?}"
    );
    assert_eq!(statuses, expected);
}

/// A copy that runs none, or only some, of the tests it was to run proves
/// nothing: here `labels` exists in the measured run only, so the copies of
/// `label`'s mutants run no test. They are errors that say so, never
/// survivors, with the stages and without.
#[cfg(unix)]
#[test]
fn a_copy_that_runs_none_of_its_tests_makes_its_mutant_an_error() {
    let project = vitest_mutants_project("strong-ran-none");
    project.write(
        "test/cart.test.js",
        "import { describe, expect, it } from \"vitest\";\nimport { shipping, label } from \"../src/cart.js\";\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\n  it(\"charges small orders\", () => expect(shipping(10)).toBe(5));\n  if (!process.env.SUPERCOV_STRONG) it(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n});\n",
    );
    project.commit("labels in the measured run only");
    for stages in ["", "1"] {
        project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
        let reply = project
            .supercov_with(
                &["runs", "latest", "mutants", "test", "--json"],
                &[("SUPERCOV_STRONG_STAGES", stages)],
            )
            .json();
        assert!(
            reply["summary"]["error"].as_u64().unwrap_or(0) > 0,
            "{reply}"
        );
        let listed = project
            .supercov(&[
                "runs",
                "latest",
                "mutants",
                "src/cart.js",
                "--json",
                "--limit",
                "0",
            ])
            .json();
        let mutants = listed["data"]["mutants"].as_array().unwrap();
        let of_label = mutants
            .iter()
            .filter(|mutant| {
                mutant["id"]
                    .as_str()
                    .unwrap_or_default()
                    .starts_with("src/cart.js:9:")
            })
            .collect::<Vec<_>>();
        assert!(!of_label.is_empty(), "{listed}");
        for mutant in of_label {
            if mutant["strong"].is_null() {
                continue;
            }
            assert_ne!(mutant["strong"]["status"], "survived", "{mutant}");
            if mutant["strong"]["status"] == "error" {
                assert!(
                    mutant["strong"]["reason"]
                        .as_str()
                        .unwrap_or_default()
                        .contains("ran none of the tests it was to run"),
                    "{mutant}"
                );
            }
        }
        assert!(
            mutants
                .iter()
                .any(|mutant| mutant["strong"]["status"] == "killed"),
            "{listed}"
        );
    }
}

/// A test file that does not finish without a mutant (here it throws while
/// it loads, in the strong pass only) cannot test the mutants it alone
/// covers: they are errors, not survivors.
#[cfg(unix)]
#[test]
fn mutants_only_an_unfinished_test_file_covers_are_errors() {
    let project = vitest_mutants_project("strong-baseline-unfinished");
    project.write(
        "test/cart.test.js",
        "import { describe, expect, it } from \"vitest\";\nimport { shipping, label } from \"../src/cart.js\";\nif (process.env.SUPERCOV_STRONG) throw new Error(\"not in a strong pass\");\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => expect(shipping(80)).toBe(0));\n  it(\"charges small orders\", () => expect(shipping(10)).toBe(5));\n  it(\"labels\", () => expect(label(\" a \")).toBe(\"A\"));\n});\n",
    );
    project.commit("unfinished");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    assert!(reply["summary"]["ran"].as_u64().unwrap_or(0) > 0, "{reply}");
    assert_eq!(
        reply["summary"]["error"], reply["summary"]["ran"],
        "{reply}"
    );
    assert_eq!(reply["summary"]["killed"], 0, "{reply}");
}

/// A mutant that leaves work re-arming itself after the tests (a ticker that
/// should stop after three ticks and never does): no single evaluation runs
/// away, but the mutant keeps running after the tests ended, as a run
/// waiting on its worker would never end. It is a timeout.
#[cfg(unix)]
#[test]
fn a_mutant_whose_work_keeps_rearming_after_the_tests_is_a_timeout() {
    let project = vitest_mutants_project("strong-left-running");
    project.write(
        "src/ticker.js",
        "export function tick(done) {\n  let n = 0;\n  const step = () => {\n    n++;\n    if (n < 3) {\n      setImmediate(step);\n    } else {\n      done(n);\n    }\n  };\n  setImmediate(step);\n}\n",
    );
    project.write(
        "test/ticker.test.js",
        "import { expect, it } from \"vitest\";\nimport { tick } from \"../src/ticker.js\";\nit(\"ticks\", async () => {\n  const seen = [];\n  tick((n) => seen.push(n));\n  await new Promise((resolve) => setTimeout(resolve, 20));\n  expect(seen.length).toBeLessThan(2);\n});\n",
    );
    project.commit("ticker");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/ticker.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let endless = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["id"] == "src/ticker.js:5:9-5:14:ConditionalExpression:true")
        .unwrap_or_else(|| panic!("{listed}"));
    assert!(
        matches!(
            endless["strong"]["status"].as_str(),
            Some("timeout" | "killed")
        ),
        "{endless}"
    );
}

/// Code under test that catches every error (a stream turning a failure into
/// a frame) also catches the hit limit's: the loop the mutant made endless
/// ends, the test passes, and the mutant is a timeout all the same.
#[cfg(unix)]
#[test]
fn a_mutant_whose_endless_loop_is_caught_by_the_code_is_a_timeout() {
    let project = vitest_mutants_project("strong-swallowed-limit");
    project.write(
        "src/drain.js",
        "export async function drain(source) {\n  const out = [];\n  try {\n    for (;;) {\n      const r = await source.next();\n      if (r.done) break;\n      out.push(r.value);\n    }\n  } catch {\n    return out;\n  }\n  return out;\n}\n",
    );
    project.write(
        "test/drain.test.js",
        "import { expect, it } from \"vitest\";\nimport { drain } from \"../src/drain.js\";\nasync function* two() {\n  yield 1;\n  yield 2;\n}\nit(\"drains\", async () => {\n  const out = await drain(two());\n  expect(out).toContain(2);\n});\n",
    );
    project.commit("drain");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/drain.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let endless = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/drain.js:6:") && id.ends_with(":ConditionalExpression:false")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(endless["strong"]["status"], "timeout", "{endless}");
}

/// `supercov mutants` with no run measures one first and tests its mutants;
/// a plain run before it lists none and says nothing of mutants; after a
/// source changes, it measures again rather than read a run of other code.
#[cfg(unix)]
#[test]
fn supercov_mutants_measures_when_it_must_and_plain_runs_know_no_mutants() {
    let project = vitest_mutants_project("supercov-mutants-command");
    project.write(
        "src/double.js",
        "export function double(n) {\n  return n * 2;\n}\n",
    );
    project.write(
        "test/double.test.js",
        "import { expect, it } from \"vitest\";\nimport { double } from \"../src/double.js\";\nit(\"doubles\", () => expect(double(3)).toBe(6));\n",
    );
    project.commit("double");
    // No run yet: it measures first, with the command given.
    let first = project.supercov(&["mutants", "--json", "--", "npx", "vitest", "run"]);
    assert!(
        first.stderr().contains("measuring first (no run yet)"),
        "{}",
        first.stderr()
    );
    let reply = first.json();
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    assert!(
        reply["summary"]["killed"].as_u64().unwrap_or(0) > 0,
        "{reply}"
    );
    // Its run is current and has its mutants' values: read as it is.
    let again = project.supercov(&["mutants", "--json"]);
    assert!(
        !again.stderr().contains("measuring first"),
        "{}",
        again.stderr()
    );
    assert!(again.json()["summary"]["killed"].as_u64().unwrap_or(0) > 0);
    // A plain run lists no mutants and its summary says nothing of them;
    // `supercov mutants` after it measures with the mutants' probes.
    let plain = project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    assert!(!plain.contains("Mutants "), "{plain}");
    let valued = project.supercov(&["mutants", "--json"]);
    assert!(
        valued
            .stderr()
            .contains("measuring first (the latest run recorded no values for its mutants)"),
        "{}",
        valued.stderr()
    );
    // A changed source is measured again, with the latest run's command.
    project.write(
        "src/double.js",
        "export function double(n) {\n  return n + n;\n}\n",
    );
    let changed = project.supercov(&["mutants", "--json"]);
    assert!(
        changed
            .stderr()
            .contains("measuring first (the checkout changed since the latest run)"),
        "{}",
        changed.stderr()
    );
    let reply = changed.json();
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/double.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let mutants = listed["data"]["mutants"].as_array().unwrap();
    assert!(
        mutants.iter().any(|mutant| mutant["original"] == "n + n"),
        "{reply} {listed}"
    );
}

/// A test file that fakes the clock and leaves it faked: the look for work
/// left running after the tests waits on the real clock, so the file still
/// finishes and a mutant its test cannot tell apart survives.
#[cfg(unix)]
#[test]
fn a_test_file_that_leaves_the_clock_faked_still_finishes_under_a_mutant() {
    let project = vitest_mutants_project("strong-faked-clock-left");
    project.write(
        "src/double.js",
        "export function double(n) {\n  return n * 2;\n}\n",
    );
    project.write(
        "test/double.test.js",
        "import { expect, it, vi } from \"vitest\";\nimport { double } from \"../src/double.js\";\nit(\"doubles zero\", () => {\n  vi.useFakeTimers();\n  expect(double(0)).toBe(0);\n});\n",
    );
    project.commit("double");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/double.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let division = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| {
            let id = mutant["id"].as_str().unwrap_or_default();
            id.starts_with("src/double.js:2:") && id.contains(":ArithmeticOperator:")
        })
        .unwrap_or_else(|| panic!("{listed}"));
    assert_eq!(division["strong"]["status"], "survived", "{division}");
}

/// `mutants test` reads its options before anything else: each mistake is
/// named, with the usage on the terminal and as a JSON error with --json,
/// and a run it cannot find or a store it cannot list is said to be so.
/// `supercov mutants` explains itself, and with no run and no command has
/// nothing to measure.
#[test]
fn mutants_test_names_each_mistake_in_its_options_before_it_reads_a_run() {
    let project = Project::cart("mutants-test-options");
    for (arguments, said) in [
        (&["--file"][..], "--file needs a path"),
        (&["--file", ""], "--file needs a path"),
        (&["--diff"], "--diff needs a base revision"),
        (&["--fail-on"], "--fail-on needs statuses"),
        (
            &["--fail-on", "survived,,killed"],
            "--fail-on takes survived, timeout, no-coverage, error, not killed",
        ),
        (&["--shard"], "--shard needs k/n"),
        (
            &["--shard", "2"],
            "--shard takes k/n with 1 <= k <= n, not 2",
        ),
        (&["--shard", "x/2"], "not x/2"),
        (&["--shard", "1/y"], "not 1/y"),
        (&["--shard", "1/0"], "not 1/0"),
        (&["--shard", "3/2"], "not 3/2"),
        (&["--critical"], "--critical needs a glob"),
        (&["--critical", ""], "--critical needs a glob"),
        (&["--plan", "--"], "-- needs a command after it"),
        (&["--sideways"], "Unknown option: --sideways"),
    ] {
        let mut command = vec!["runs", "latest", "mutants", "test"];
        command.extend(arguments);
        let human = project.supercov(&command).exits(2);
        contains_all(
            &human,
            &[said, "Usage: supercov runs <run-id> mutants test"],
        );
        command.insert(4, "--json");
        let json = project.supercov(&command);
        assert_eq!(json.code(), 2, "{arguments:?}");
        let json = json.json();
        assert!(
            json["error"]["message"].as_str().unwrap().contains(said),
            "{arguments:?}: {json}"
        );
    }
    for help in [
        &["runs", "latest", "mutants", "test", "--help"][..],
        &["runs", "latest", "mutants", "test", "-h"],
    ] {
        contains_all(
            &project.supercov(help).succeeds(),
            &[
                "Usage: supercov runs <run-id> mutants test",
                "--shard <k>/<n>",
            ],
        );
    }
    for help in [
        &["mutants", "--help"][..],
        &["mutants", "-h"],
        &["help", "mutants"],
    ] {
        contains_all(
            &project.supercov(help).succeeds(),
            &[
                "Usage: supercov mutants [options] [-- <test command>]",
                // Every language with mutants is named, with its tool, and
                // the ones in preview say so.
                "StrykerJS",
                "in preview",
                "mutmut",
                "cargo-mutants",
                "Gremlins",
                "mutant for Ruby",
            ],
        );
    }
    // The run's own command is an option, listed with the others.
    let test_help = project
        .supercov(&["runs", "latest", "mutants", "test", "--help"])
        .succeeds();
    let options = test_help
        .split("Options:")
        .nth(1)
        .and_then(|rest| rest.split("\n\n").next())
        .unwrap_or_default();
    assert!(options.contains("-- <command>"), "{test_help}");
    let weak_help = project
        .supercov(&["runs", "latest", "mutants", "--help"])
        .succeeds();
    contains_all(
        &weak_help,
        &["in preview", "cargo-mutants", "Gremlins", "mutant for Ruby"],
    );
    let overview = project.supercov(&["--help"]).succeeds();
    assert!(
        overview.contains(
            "Test the tests with mutants (JavaScript, TypeScript; Python, Rust, Go and Ruby in preview)"
        ),
        "{overview}"
    );

    // Options that parse, and no run to read: said on the standard error
    // with exit 1, or as a JSON error with --json.
    let options = [
        "--shard",
        "1/2",
        "--critical",
        "src/**",
        "--fail-on",
        ",",
        "--",
        "npx",
        "vitest",
        "run",
    ];
    let mut command = vec!["runs", "nope", "mutants", "test"];
    command.extend(options);
    let unknown = project.supercov(&command).exits(1);
    assert!(unknown.contains("[supercov] "), "{unknown}");
    assert!(!unknown.contains("Usage:"), "{unknown}");
    command.insert(4, "--json");
    let unknown = project.supercov(&command);
    assert_eq!(unknown.code(), 2, "{}", unknown.stderr());
    assert_eq!(unknown.json()["ok"], false);

    // A store that cannot be listed.
    project.measure(&[]);
    let unlisted = project
        .supercov_with(
            &["runs", "latest", "mutants", "test", "--plan"],
            &[("SUPERCOV_TEST_FAULT", "fs.read_dir#run-store.discover-runs")],
        )
        .exits(1);
    assert!(unlisted.contains("run-store.discover-runs"), "{unlisted}");
    // A run whose evidence is cut short after its header, its size as
    // recorded, has no plan. Where the cut lands (a section's header or its
    // compressed body) depends on the run's sizes, so the reason may be either.
    let run = project.latest();
    let directory = project.root.join(format!(".supercov/runs/{run}"));
    let metadata: serde_json::Value =
        serde_json::from_slice(&std::fs::read(directory.join("run.json")).unwrap()).unwrap();
    let evidence = directory.join(metadata["rawEvidence"]["file"].as_str().unwrap());
    let mut bytes = std::fs::read(&evidence).unwrap();
    let half = bytes.len() / 2;
    bytes[half..].fill(b'x');
    std::fs::write(&evidence, bytes).unwrap();
    let unread = project
        .supercov(&["runs", "latest", "mutants", "test", "--plan"])
        .exits(1);
    assert!(unread.starts_with("[supercov] InvalidArchive("), "{unread}");

    // No run, and no command to measure one with.
    let empty = Project::empty("mutants-no-run");
    let nothing = empty.supercov(&["mutants", "--json"]).exits(2);
    assert!(
        nothing.contains(
            "No run to read mutants from: give the test command, supercov mutants -- <test command>"
        ),
        "{nothing}"
    );
}

/// `mutants test` narrowed: to a file, to the lines a change touched since
/// a base (a file git does not track yet is new whole), and to an even share
/// of what runs (the mutants decided unrun with the first). Its gate fails
/// on an asked mutant whose verdict `--fail-on` names, or on any survivor
/// in a `--critical` file, unless supercov.accepted.json accepts it, and
/// names the accepted ones since killed. What stops a pass is said: a
/// working directory or plan it cannot write, verdicts it cannot save, a
/// command it cannot run or the run did not record.
#[cfg(unix)]
#[test]
fn mutants_test_narrows_shares_and_gates_what_it_asks_about() {
    let project = vitest_mutants_project("strong-narrow-gate");
    // On the base and unchanged since.
    project.write(
        "src/tax.js",
        "export function tax(sum) {\n  return sum >= 10 ? sum * 0.2 : 0;\n}\n",
    );
    project.write(
        "test/tax.test.js",
        "import { expect, it } from \"vitest\";\nimport { tax } from \"../src/tax.js\";\nit(\"taxes\", () => expect(tax(20)).toBe(4));\n",
    );
    project.commit("tax");
    project.git(&["branch", "base"]);
    project.edit("src/cart.js", "return 5;", "return 6;");
    project.edit("test/cart.test.js", "toBe(5)", "toBe(6)");
    project.commit("dearer");
    // Not tracked yet: the run measures the working tree. `n > 0` to
    // `n >= 0` is equivalent: `n &&` already left 0 out.
    project.write(
        "src/extra.js",
        "export function positive(a, b) {\n  const n = a - b;\n  return Boolean(n && n > 0);\n}\n",
    );
    project.write(
        "test/extra.test.js",
        "import { expect, it } from \"vitest\";\nimport { positive } from \"../src/extra.js\";\nit(\"is positive\", () => expect(positive(3, 1)).toBe(true));\n",
    );
    // A command that writes its own verdicts: one record no verdict can be
    // read from for the first mutant, a kill for each other, and lines
    // that are no verdict at all.
    project.write(
        "fake-strong.mjs",
        "import { appendFileSync, readFileSync } from \"node:fs\";\nconst plan = JSON.parse(readFileSync(process.env.SUPERCOV_STRONG_PLAN, \"utf8\"));\nconst lines = [\"not json\", JSON.stringify({ summary: true, driver: \"fake\" }), JSON.stringify({ note: \"no id\" })];\nplan.mutants.forEach((mutant, index) => {\n  lines.push(JSON.stringify(index === 0 ? { id: mutant.id, status: 7 } : { id: mutant.id, status: \"killed\", tests: 1 }));\n});\nappendFileSync(process.env.SUPERCOV_STRONG_RESULTS, lines.join(\"\\n\") + \"\\n\");\n",
    );
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let run = project.latest();
    let ids = |reply: &serde_json::Value| {
        reply["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .map(|mutant| mutant["id"].as_str().unwrap().to_owned())
            .collect::<Vec<_>>()
    };
    let plan = |arguments: &[&str]| {
        let mut command = vec!["runs", "latest", "mutants", "test", "--plan", "--json"];
        command.extend(arguments);
        project.supercov(&command).json()
    };

    let all = plan(&[]);
    assert!(
        all["summary"]["decided"]["equivalent"].as_u64() >= Some(1),
        "{all}"
    );
    let human = project
        .supercov(&["runs", "latest", "mutants", "test", "--plan"])
        .succeeds();
    contains_all(
        &human,
        &[
            &format!("Strong mutation plan for {run}: "),
            "  to run        ",
            "  equivalent    ",
        ],
    );
    // A file's mutants.
    let tax = ids(&plan(&["--file", "src/tax.js"]));
    assert!(!tax.is_empty());
    assert!(
        tax.iter().all(|id| id.starts_with("src/tax.js:")),
        "{tax:?}"
    );
    // A change's: the new file whole, cart.js's changed line, not tax.js.
    let changed = ids(&plan(&["--diff", "base"]));
    assert!(
        changed.iter().any(|id| id.starts_with("src/extra.js:")),
        "{changed:?}"
    );
    assert!(
        changed.iter().any(|id| id.starts_with("src/cart.js:")),
        "{changed:?}"
    );
    assert!(
        changed
            .iter()
            .all(|id| !id.starts_with("src/tax.js:") && !id.starts_with("src/cart.js:9:")),
        "{changed:?}"
    );
    let unknown = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "test",
            "--plan",
            "--diff",
            "no-such-base",
        ])
        .exits(1);
    assert!(
        unknown.contains("git knows no commit by that name"),
        "{unknown}"
    );
    // Two shares: what runs split between them, the decided in the first.
    let first = plan(&["--shard", "1/2"]);
    let second = plan(&["--shard", "2/2"]);
    assert_eq!(second["summary"]["decided"]["survived"], 0, "{second}");
    assert_eq!(second["summary"]["decided"]["noCoverage"], 0, "{second}");
    assert_eq!(first["summary"]["decided"], all["summary"]["decided"]);
    assert_eq!(
        first["summary"]["toRun"].as_u64().unwrap() + second["summary"]["toRun"].as_u64().unwrap(),
        all["summary"]["toRun"].as_u64().unwrap()
    );

    // What stops a pass, before any of tax.js's mutants has a verdict.
    let tax_pass = ["runs", "latest", "mutants", "test", "--file", "src/tax.js"];
    project.write(".supercov/strong", "");
    let unmade = project.supercov(&tax_pass).exits(1);
    assert!(unmade.contains(".supercov/strong"), "{unmade}");
    std::fs::remove_file(project.root.join(".supercov/strong")).unwrap();
    let unwritten = project.supercov_with(
        &tax_pass,
        &[(
            "SUPERCOV_TEST_FAULT",
            "fs.write#mutants-test-command.run-language",
        )],
    );
    assert_eq!(unwritten.code(), 1, "{}", unwritten.stderr());
    assert!(
        fired_at(&unwritten.stderr(), "mutants-test-command.run-language"),
        "{}",
        unwritten.stderr()
    );
    // The store's ignore file, written as the pass takes its hold on the
    // store, cannot be: the pass does not start.
    std::fs::remove_file(project.root.join(".supercov/.gitignore")).unwrap();
    let unstarted = project.supercov_with(&tax_pass, &[("SUPERCOV_TEST_FAULT", "store-ignore")]);
    assert_eq!(unstarted.code(), 1, "{}", unstarted.stderr());
    assert!(
        fired_at(&unstarted.stderr(), "store-ignore"),
        "{}",
        unstarted.stderr()
    );
    let saved = project
        .root
        .join(format!(".supercov/runs/{run}/strong-mutation.json"));
    // What the stopped passes above decided is saved; a directory in its
    // place cannot be written.
    let _ = std::fs::remove_file(&saved);
    std::fs::create_dir(&saved).unwrap();
    let mut faked = tax_pass.to_vec();
    faked.extend(["--", "node", "fake-strong.mjs"]);
    let unsaved = project.supercov(&faked).exits(1);
    assert!(unsaved.contains("strong-mutation.json"), "{unsaved}");
    // Nothing to run, and still nowhere to save.
    let unsaved = project
        .supercov(&["runs", "latest", "mutants", "test", "--file", "src/none.js"])
        .exits(1);
    assert!(unsaved.contains("strong-mutation.json"), "{unsaved}");
    std::fs::remove_dir(&saved).unwrap();
    // Nothing asked: nothing runs, and nothing fails.
    project
        .supercov(&["runs", "latest", "mutants", "test", "--file", "src/none.js"])
        .succeeds();
    // A run that recorded no command, and none given.
    let metadata_path = project.root.join(format!(".supercov/runs/{run}/run.json"));
    let metadata = std::fs::read_to_string(&metadata_path).unwrap();
    let mut commandless: serde_json::Value = serde_json::from_str(&metadata).unwrap();
    commandless["command"] = serde_json::json!([]);
    std::fs::write(&metadata_path, commandless.to_string()).unwrap();
    let commandless = project.supercov(&tax_pass).exits(1);
    assert!(
        commandless.contains("the run recorded no command: give one after --"),
        "{commandless}"
    );
    std::fs::write(&metadata_path, metadata).unwrap();
    // A command that writes no verdict: each mutant it ran is an error.
    let mut silent = tax_pass.to_vec();
    silent.extend(["--json", "--", "node", "-e", "0"]);
    let silent = project.supercov(&silent).json();
    assert!(silent["summary"]["ran"].as_u64() > Some(0), "{silent}");
    assert_eq!(
        silent["summary"]["error"], silent["summary"]["ran"],
        "{silent}"
    );
    let errors = silent["summary"]["error"].as_u64().unwrap();

    // The command's own verdicts: a record no verdict is read from leaves
    // its mutant to the next pass, and a pass that decides nothing more
    // ends them; the mutant is then an error.
    let extra = plan(&["--file", "src/extra.js"]);
    let unread = extra["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["decided"].is_null())
        .unwrap()["id"]
        .as_str()
        .unwrap()
        .to_owned();
    let reply = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "test",
            "--file",
            "src/extra.js",
            "--json",
            "--",
            "node",
            "fake-strong.mjs",
        ])
        .json();
    // The summary counts extra.js's mutants alone, the ones asked about:
    // tax.js's errors above are not among them.
    assert_eq!(reply["summary"]["error"], 1, "{reply}");
    assert!(errors > 0);
    assert!(reply["summary"]["killed"].as_u64() > Some(0), "{reply}");
    assert!(reply["summary"]["equivalent"].as_u64() > Some(0), "{reply}");
    assert_eq!(reply["passes"][0]["driver"], "fake", "{reply}");
    assert_eq!(reply["passes"].as_array().unwrap().len(), 2, "{reply}");
    let listed = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/extra.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let errored = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["id"] == unread.as_str())
        .unwrap_or_else(|| panic!("{listed}"))["strong"]
        .clone();
    assert_eq!(errored["status"], "error", "{errored}");
    assert_eq!(
        errored["reason"],
        "the command ended (exit 0) before this mutant's verdict"
    );

    // cart.js's mutants, half first: the gate passes over those with no
    // verdict yet.
    let half = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "test",
            "--file",
            "src/cart.js",
            "--shard",
            "2/2",
        ])
        .succeeds();
    contains_all(
        &half,
        &[
            // The mutants asked about are named, and counted alone.
            &format!("Strong mutation for {run} ("),
            " mutants, in src/cart.js): mutation score ",
            "  killed        ",
        ],
    );
    let cart = ["runs", "latest", "mutants", "test", "--file", "src/cart.js"];
    let gated = |arguments: &[&str]| {
        let mut command = cart.to_vec();
        command.extend(arguments);
        project.supercov(&command)
    };
    gated(&[]).succeeds();
    let survivor = "src/cart.js:2:7-2:16:EqualityOperator:>";
    let failed = gated(&["--fail-on", "survived"]).exits(1);
    assert!(
        failed.contains(&format!("  survived {survivor}\n")),
        "{failed}"
    );
    let critical = gated(&["--critical", "src/cart.j?"]).exits(1);
    assert!(
        critical.contains(&format!("  survived {survivor} (critical)\n")),
        "{critical}"
    );
    // `?` is no `/`, and `*` stops at the end of the name.
    gated(&[
        "--critical",
        "src?cart.js",
        "--critical",
        "src/*z",
        "--fail-on",
        "timeout",
    ])
    .succeeds();

    // Accepted: the survivor passes; an accepted mutant since killed is
    // named for removal.
    let killed = "src/cart.js:9:10-9:21:MethodExpression:removed";
    project.write(
        "supercov.accepted.json",
        &serde_json::json!([
            {"id": survivor, "reason": "no order costs exactly 50"},
            {"id": killed, "reason": "once thought equivalent"},
        ])
        .to_string(),
    );
    let accepted = gated(&["--fail-on", "survived"]).succeeds();
    assert!(
        accepted.contains(
            "  1 accepted mutant(s) in supercov.accepted.json are killed or gone: remove them"
        ),
        "{accepted}"
    );
    let accepted = gated(&["--fail-on", "survived", "--json"]).json();
    assert_eq!(accepted["gate"]["failed"], false, "{accepted}");
    assert_eq!(
        accepted["gate"]["accepted"][0]["id"], survivor,
        "{accepted}"
    );
    assert_eq!(
        accepted["gate"]["staleAccepted"],
        serde_json::json!([killed])
    );
    for (contents, said) in [
        ("[{\"reason\": \"why\"}]", "an entry has no id"),
        (
            "[{\"id\": \"a\", \"reason\": \" \"}]",
            "a is accepted without a reason",
        ),
        ("{", "supercov.accepted.json: "),
    ] {
        project.write("supercov.accepted.json", contents);
        let refused = gated(&[]).exits(1);
        assert!(refused.contains(said), "{contents}: {refused}");
        let refused = gated(&["--json"]);
        assert_eq!(refused.code(), 2, "{contents}");
        assert!(
            refused.json()["error"]["message"]
                .as_str()
                .unwrap()
                .contains(said),
            "{contents}"
        );
    }
    // An empty list accepts nothing.
    project.write("supercov.accepted.json", "[]");
    gated(&[]).succeeds();
    std::fs::remove_file(project.root.join("supercov.accepted.json")).unwrap();

    // A source changed since a run whose mutants were never listed: its
    // mutants are left out, and said so.
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let run = project.latest();
    project.edit("src/tax.js", "sum * 0.2", "sum / 5");
    let stale = project.supercov(&["runs", "latest", "mutants", "test", "--plan", "--json"]);
    assert!(
        stale.stderr().contains(&format!(
            "1 file(s) changed since run {run}; their mutants are left out"
        )),
        "{}",
        stale.stderr()
    );
    assert!(
        ids(&stale.json())
            .iter()
            .all(|id| !id.starts_with("src/tax.js:")),
        "{}",
        stale.stdout()
    );
    // `supercov mutants` measures that checkout first, and says when it
    // cannot start the measurement.
    let unmeasured = project
        .supercov_with(
            &["mutants", "--json"],
            &[(
                "SUPERCOV_TEST_FAULT",
                "spawn#mutants-test-command.mutants-command",
            )],
        )
        .exits(2);
    assert!(
        unmeasured.contains("[supercov] could not measure: "),
        "{unmeasured}"
    );
}

/// A run whose one source holds no code (a comment alone) has no mutants
/// to test, and `mutants test` says so. `supercov mutants`, finding no
/// values for mutants in it, measures it again, and that run lists none:
/// nothing runs, and there is no score.
#[test]
fn a_run_whose_source_holds_no_code_has_no_mutants_to_test() {
    let project = Project::empty("mutants-no-source");
    project.write(
        "package.json",
        r#"{ "name": "sourceless", "private": true, "type": "module", "scripts": { "test": "node --test" } }"#,
    );
    project.write(
        "test/math.test.js",
        "import test from \"node:test\";\nimport assert from \"node:assert/strict\";\ntest(\"adds\", () => assert.equal(1 + 1, 2));\n",
    );
    project.write("src/later.js", "// Nothing here yet.\n");
    project.write(".gitignore", ".supercov\n");
    project.git(&["init", "-q"]);
    project.commit("tests alone");
    let run = project.measure(&[]);
    let none = project
        .supercov(&["runs", "latest", "mutants", "test", "--plan"])
        .exits(1);
    assert!(
        none.contains(&format!(
            "run {run} listed no mutants and measured no source to list them from"
        )),
        "{none}"
    );
    // Measured with the mutants' probes, the run lists its mutants: none,
    // and no score.
    let measured = project.supercov(&["mutants"]);
    assert!(
        measured.stderr().contains(
            "measuring first (the latest run recorded no values for its mutants): node --test"
        ),
        "{}",
        measured.stderr()
    );
    contains_all(
        &measured.succeeds(),
        &["mutation score -\n", "  ran 0 mutant(s) in "],
    );
    let plan = project
        .supercov(&["runs", "latest", "mutants", "test", "--plan", "--json"])
        .json();
    assert_eq!(plan["summary"]["mutants"], 0, "{plan}");
    // The report shows no mutants for it.
    project
        .supercov(&["report", "--no-open", "--output", "report.html"])
        .succeeds();
    let report = report_data(&project.read("report.html"));
    assert!(report["runs"][0]["mutants"].is_null(), "{report}");
}

/// The mutants commands started in a directory deleted under the shell
/// have no project to work in, and say so.
#[cfg(target_os = "linux")]
#[test]
fn the_mutants_commands_in_a_removed_directory_say_so() {
    let parent = std::env::temp_dir().join(format!("supercov-mutants-gone-{}", std::process::id()));
    std::fs::create_dir_all(&parent).unwrap();
    for (arguments, code, said) in [
        (&["mutants"][..], 2, "[supercov] "),
        (&["runs", "latest", "mutants", "test"], 1, "[supercov] "),
        (
            &["runs", "latest", "mutants", "--format", "jsonl"],
            2,
            "could not resolve the current directory",
        ),
        (
            &["runs", "latest", "mutants", "--stryker", "mutation.json"],
            2,
            "Could not resolve the current directory",
        ),
    ] {
        let gone = parent.join("gone");
        std::fs::create_dir_all(&gone).unwrap();
        let output = std::process::Command::new("sh")
            .arg("-c")
            .arg(r#"cd "$1" && rmdir "$1" && shift && exec "$@""#)
            .arg("sh")
            .arg(&gone)
            .arg(env!("CARGO_BIN_EXE_supercov"))
            .args(arguments)
            .output()
            .unwrap();
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert_eq!(output.status.code(), Some(code), "{arguments:?}: {stderr}");
        assert!(stderr.contains(said), "{arguments:?}: {stderr}");
        assert!(
            stderr.contains("No such file or directory"),
            "{arguments:?}: {stderr}"
        );
    }
    std::fs::remove_dir_all(parent).unwrap();
}

/// A mocha project kept below the top of its repository, its tests run
/// with uncommitted changes on top of a `base` branch: mutants at a clock
/// boundary, a change too long to show whole, a source with no mutants, a
/// source no test loads, and a file of thirty guards nothing calls.
#[cfg(unix)]
fn mutant_views_project(label: &str) -> (Project, Project) {
    let repository = Project::empty(label);
    let project = Project {
        root: repository.root.join("app"),
    };
    project.write(
        "package.json",
        r#"{ "name": "views", "type": "module", "scripts": { "test": "mocha" } }"#,
    );
    let modules = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../node_modules");
    std::os::unix::fs::symlink(
        modules.canonicalize().unwrap(),
        project.root.join("node_modules"),
    )
    .unwrap();
    repository.write(".gitignore", "node_modules\n.supercov\n");
    project.write(
        "src/cart.js",
        "export function shipping(sum) {\n  if (sum >= 50) {\n    return 0;\n  }\n  return 5;\n}\n\nexport function label(name) {\n  return name.trim().toUpperCase();\n}\n\nexport function refund(sum) {\n  return sum > 100 ? sum * 0.9 : sum;\n}\n",
    );
    project.write(
        "src/clock.js",
        "export function expired(deadline) {\n  return Date.now() > deadline;\n}\n\nexport function fresh(at) {\n  return Date.now() - at < 1000;\n}\n\nexport function shout(name) {\n  return `HEY ${name}`;\n}\n",
    );
    project.write(
        "src/greet.js",
        "export function greet(name) {\n  return \"Hello there, \" + name + \", and welcome back to the little store we have built for all of you\";\n}\n\nexport function full(order) {\n  return order.items.length + order.extras.length >= order.limit;\n}\n",
    );
    project.write("src/consts.js", "export const FREE_FROM = 50;\n");
    let mut guards = String::from("export function band(n) {\n");
    for bound in 0..30 {
        guards.push_str(&format!("  if (n > {bound}) return {bound};\n"));
    }
    guards.push_str("  return -1;\n}\n");
    project.write("src/unused.js", &guards);
    project.write(
        "test/cart.test.js",
        "import assert from \"node:assert/strict\";\nimport { shipping, label } from \"../src/cart.js\";\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", () => assert.equal(shipping(80), 0));\n  it(\"charges small orders\", () => assert.equal(shipping(10), 5));\n  it(\"labels\", () => assert.equal(label(\" a \"), \"A\"));\n});\n",
    );
    project.write(
        "test/more.test.js",
        "import assert from \"node:assert/strict\";\nimport { expired } from \"../src/clock.js\";\nimport { greet } from \"../src/greet.js\";\nimport { FREE_FROM } from \"../src/consts.js\";\ndescribe(\"more\", () => {\n  it(\"expires\", () => assert.equal(expired(0), true));\n  it(\"greets\", () => assert.ok(greet(\"Ann\").startsWith(\"Hello\")));\n  it(\"frees from fifty\", () => assert.equal(FREE_FROM, 50));\n});\n",
    );
    repository.git(&["init", "-q"]);
    repository.commit("views");
    repository.git(&["branch", "base"]);
    // Uncommitted: dearer small orders, and a smaller refund.
    project.edit("src/cart.js", "return 5;", "return 6;");
    project.edit("src/cart.js", "sum * 0.9", "sum * 0.8");
    project.edit("test/cart.test.js", "shipping(10), 5", "shipping(10), 6");
    (repository, project)
}

/// Every view of a run's mutants as a reader sees it: the summary's count
/// of mutants at a clock boundary; the table of files, with the one no
/// test ran, a filter's label and its pages; a file's and a line's
/// mutants, cut where too long, with their boundary, StrykerJS's status
/// and the gate; a change's (the run's working tree) with its pages; and
/// a source with no mutants, which notes so.
#[cfg(unix)]
#[test]
fn every_mutants_view_shows_what_the_run_says_of_them() {
    let (_repository, project) = mutant_views_project("mutant-views");
    project
        .supercov_with(&["--", "npx", "mocha"], &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let view = |arguments: &[&str]| {
        let mut command = vec!["runs", "latest", "mutants"];
        command.extend(arguments);
        project.supercov(&command).succeeds()
    };
    contains_all(
        &project.supercov(&["runs", "latest"]).succeeds(),
        &["(1 at a clock or random boundary)"],
    );

    // Read against the working tree while git sees no new file: only the
    // changed lines count.
    assert!(
        view(&["src/clock.js", "--diff", "base"])
            .contains("No mutant is on a line this change added or changed.")
    );
    // A report whose run's mutants cannot be read from its index says so.
    let unread = project.supercov_with(
        &["report", "--no-open", "--output", "report.html"],
        &[(
            "SUPERCOV_TEST_FAULT",
            "coverage-index-read#mutants-query.coverage-mutants-query",
        )],
    );
    let said = format!("{}{}", unread.stdout(), unread.stderr());
    assert_ne!(unread.code(), 0, "{said}");
    assert!(said.contains("could not read mutants for run "), "{said}");
    assert!(
        fired_at(&said, "mutants-query.coverage-mutants-query"),
        "{said}"
    );

    // The table of files.
    contains_all(
        &view(&[]),
        &[
            "1 file no test ran, with ",
            " is listed last",
            "list the mutants no test infects: ",
        ],
    );
    assert!(view(&["--limit", "1"]).contains("next page: "));
    let past = view(&["--offset", "100"]);
    assert!(!past.contains("inspect a file: "), "{past}");
    // One test's view: what it does not infect, none; what it never ran.
    let labels = view(&["--title", "labels"]);
    contains_all(
        &labels,
        &[
            "title containing \"labels\"",
            " files no test ran, with ",
            " are listed last",
        ],
    );
    assert!(
        !labels.contains("list the mutants no test infects"),
        "{labels}"
    );

    // A file's mutants: the clock boundary named where no test infected
    // the mutant, not where none reached it.
    let clock = view(&["src/clock.js"]);
    assert!(clock.contains("(clock boundary)"), "{clock}");
    assert!(
        clock
            .lines()
            .filter(|line| line.starts_with("6:"))
            .all(|line| !line.contains("boundary")),
        "{clock}"
    );
    assert!(
        view(&["src/clock.js:2"]).contains("  untestable in practice: "),
        "clock line"
    );
    let greet = view(&["src/greet.js"]);
    assert!(greet.contains('…'), "{greet}");
    let full = view(&["src/greet.js:6"]);
    assert!(full.contains("\n  in:  order.items.length"), "{full}");
    assert!(view(&["src/cart.js", "--limit", "2"]).contains("next page: "));
    assert!(view(&["src/cart.js", "--status", "equivalent"]).contains("No mutants match."));
    // Only infected mutants: none left alive to explain line by line.
    let infected = view(&["src/cart.js", "--status", "infected"]);
    assert!(
        !infected.contains("one line's mutants and why"),
        "{infected}"
    );
    let beyond = view(&["src/cart.js", "--offset", "100"]);
    assert!(!beyond.contains("No mutants match."), "{beyond}");
    assert!(
        view(&["src/cart.js", "--mutator", "EqualityOperator"])
            .contains("--mutator 'EqualityOperator'"),
        "mutator"
    );
    let gate = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/cart.js",
            "--fail-on",
            "not-infected",
        ])
        .exits(1);
    assert!(
        gate.contains("FAILED --fail-on not-infected: 1 mutant (exit 1)"),
        "{gate}"
    );
    // A source with no mutants says so, with StrykerJS's block or alone.
    let consts = view(&["src/consts.js"]);
    assert!(
        consts.contains("src/consts.js has no mutants in this run."),
        "{consts}"
    );
    assert!(!consts.contains("StrykerJS"), "{consts}");

    // StrykerJS's report: a survivor it agrees on, no violation.
    let source = project.read("src/cart.js");
    let report = |file: &str| {
        serde_json::json!({
            "schemaVersion": "1",
            "thresholds": {"high": 80, "low": 60},
            "files": {file: {"language": "javascript", "source": source, "mutants": [{
                "id": "1",
                "mutatorName": "ConditionalExpression",
                "replacement": "true",
                "location": {"start": {"line": 13, "column": 10}, "end": {"line": 13, "column": 19}},
                "status": "Survived",
            }]}},
        })
        .to_string()
    };
    project.write("reports/clean.json", &report("src/cart.js"));
    project.write("reports/nested/clean.json", &report("../../src/cart.js"));
    for number in 0..4 {
        project.write(
            &format!("reports/many/r{number}.json"),
            &report("src/cart.js"),
        );
    }
    let joined = view(&["src/cart.js", "--stryker", "reports/clean.json"]);
    contains_all(
        &joined,
        &[
            "  stryker: Survived",
            "  Soundness violations 0",
            "  Only in StrykerJS    0\n",
        ],
    );
    let rooted = view(&[
        "src/cart.js",
        "--stryker",
        "reports/nested/clean.json",
        "--stryker-root",
        "reports/nested",
        "--limit",
        "1",
    ]);
    assert!(
        rooted.contains("--stryker-root 'reports/nested'"),
        "{rooted}"
    );
    // Four reports on a line's view: no command shown stands for them.
    let many = view(&[
        "src/cart.js:13",
        "--stryker",
        "reports/many/r0.json",
        "reports/many/r1.json",
        "reports/many/r2.json",
        "reports/many/r3.json",
    ]);
    assert!(many.contains("StrykerJS (4 reports)"), "{many}");
    assert!(!many.contains("in these commands"), "{many}");
    // A directory after a report is read with it.
    let both = view(&[
        "src/cart.js:13",
        "--stryker",
        "reports/clean.json",
        "reports/many",
    ]);
    assert!(
        both.contains("StrykerJS (5 reports in reports/clean.json, reports/many)"),
        "{both}"
    );
    let consts = view(&["src/consts.js", "--stryker", "reports/clean.json"]);
    contains_all(
        &consts,
        &[
            "src/consts.js has no mutants in this run.",
            "StrykerJS (reports/clean.json)",
        ],
    );
    // More violations than are listed one by one.
    let unused = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/unused.js",
            "--json",
            "--limit",
            "0",
        ])
        .json();
    let killed = unused["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|mutant| mutant["mutator"] == "ConditionalExpression")
        .map(|mutant| {
            let id = mutant["id"].as_str().unwrap();
            let parts = id.split(':').collect::<Vec<_>>();
            let (start_column, end_line) = parts[2].split_once('-').unwrap();
            serde_json::json!({
                "id": id,
                "mutatorName": "ConditionalExpression",
                "replacement": parts[5],
                "location": {
                    "start": {"line": parts[1].parse::<u32>().unwrap(), "column": start_column.parse::<u32>().unwrap()},
                    "end": {"line": end_line.parse::<u32>().unwrap(), "column": parts[3].parse::<u32>().unwrap()},
                },
                "status": "Killed",
            })
        })
        .collect::<Vec<_>>();
    assert_eq!(killed.len(), 60, "{unused}");
    project.write(
        "reports/violations.json",
        &serde_json::json!({
            "schemaVersion": "1",
            "thresholds": {"high": 80, "low": 60},
            "files": {"src/unused.js": {"language": "javascript", "source": project.read("src/unused.js"), "mutants": killed}},
        })
        .to_string(),
    );
    let violated = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "src/unused.js",
            "--stryker",
            "reports/violations.json",
        ])
        .exits(1);
    contains_all(
        &violated,
        &[
            "SOUNDNESS VIOLATIONS 60",
            "    … and 10 more (--json lists them by mutant",
        ],
    );

    // A change's mutants, read against the working tree the run measured.
    let change = view(&["--diff", "base"]);
    contains_all(
        &change,
        &[
            "to the working tree: the run was measured with uncommitted changes, or records no commit",
            "Not reached",
            "src/cart.js:13:",
        ],
    );
    assert!(
        view(&["--diff", "base", "--stryker", "reports/clean.json"])
            .contains("  stryker: Survived")
    );
    assert!(view(&["--diff", "base", "--limit", "1"]).contains("next page: "));
    assert!(view(&["--diff", "base", "--limit", "1", "--offset", "1"]).contains("showing 2-2 of "));
    // The last page, from the second mutant on.
    let rest = view(&["--diff", "base", "--offset", "1"]);
    assert!(rest.contains("showing 2-"), "{rest}");
    assert!(!rest.contains("next page: "), "{rest}");
    assert!(
        view(&["--diff", "base", "--status", "not-infected"])
            .contains("No mutant on this change is left that way.")
    );
    assert!(
        view(&["src/clock.js", "--diff", "base"])
            .contains("No mutant is on a line this change added or changed.")
    );
    let every = view(&[
        "--diff",
        "base",
        "--status",
        "not-infected,not-reached,infected,unknown,equivalent",
    ]);
    assert!(!every.contains("Not listed: "), "{every}");
    // Each of git's asks failing in turn.
    let mut said = std::collections::BTreeSet::new();
    for nth in 1..=10 {
        let ran = project.supercov_with(
            &["runs", "latest", "mutants", "--diff", "base"],
            &[("SUPERCOV_TEST_FAULT", &format!("git@{nth}"))],
        );
        if ran.code() == 0 {
            continue;
        }
        let stderr = ran.stderr();
        for message in [
            "--diff needs git: could not run git",
            "Could not find where this change left base",
            "could not run git: injected fault at git",
        ] {
            if stderr.contains(message) {
                said.insert(message);
            }
        }
    }
    assert_eq!(said.len(), 3, "{said:?}");
}

/// A run's mutants written out: one JSON object per line, or a markdown
/// table for a pull request, to standard output or a file; mistakes and a
/// file or output that cannot be written are said, with exit 2.
#[cfg(unix)]
#[test]
fn mutants_export_as_lines_or_a_table_and_says_what_it_cannot_write() {
    let (_repository, project) = mutant_views_project("mutants-export");
    project
        .supercov_with(&["--", "npx", "mocha"], &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let export = |arguments: &[&str]| {
        let mut command = vec!["runs", "latest", "mutants"];
        command.extend(arguments);
        project.supercov(&command)
    };
    let bogus = export(&["--format", "jsonl", "--status", "bogus"]).exits(2);
    assert!(bogus.contains("--status bogus is not a status"), "{bogus}");
    let missing = export(&["src/nothing.js", "--format", "jsonl"]).exits(2);
    assert!(missing.contains("src/nothing.js"), "{missing}");
    // No mutants: no lines, and the note why.
    let none = export(&[
        "src/consts.js",
        "--format",
        "jsonl",
        "--json",
        "--limit",
        "5",
        "--offset",
        "0",
    ]);
    assert_eq!(none.succeeds(), "");
    assert!(
        none.stderr()
            .contains("src/consts.js has no mutants in this run."),
        "{}",
        none.stderr()
    );
    let unwritten = export(&["--format", "jsonl", "--output", "missing/mutants.jsonl"]).exits(2);
    assert!(unwritten.contains("missing/mutants.jsonl: "), "{unwritten}");
    let written = export(&["--format", "markdown", "--output", "mutants.md"]);
    assert!(
        written
            .stderr()
            .contains("wrote the mutants' table to mutants.md"),
        "{}",
        written.stderr()
    );
    assert!(project.read("mutants.md").starts_with("### Mutants\n\n**"));
    let reached = export(&[
        "src/cart.js",
        "--format",
        "markdown",
        "--status",
        "not-reached",
    ])
    .succeeds();
    assert!(reached.contains(" | not reached | "), "{reached}");
    assert!(!reached.contains(" | not infected | "), "{reached}");
    let empty = export(&["src/consts.js", "--format", "markdown"]).succeeds();
    contains_all(
        &empty,
        &[
            "**0 mutants**: weak score **—**\n",
            "No mutant is left alive: none is not infected or not reached.",
        ],
    );
    let clock = export(&["src/clock.js", "--format", "markdown"]).succeeds();
    contains_all(&clock, &["not infected (clock boundary)", "HEY"]);
    // A change with no mutant on its lines in the file asked about.
    let unchanged = export(&["src/clock.js", "--diff", "base", "--format", "markdown"]).succeeds();
    contains_all(
        &unchanged,
        &[
            "### Mutants on this change",
            "**0 mutants** on 0 of ",
            "weak score **—**\n",
        ],
    );
    // StrykerJS joined with no violation: the export passes.
    project.write(
        "reports/empty.json",
        r#"{"schemaVersion": "1", "thresholds": {"high": 80, "low": 60}, "files": {}}"#,
    );
    export(&[
        "src/cart.js",
        "--format",
        "jsonl",
        "--stryker",
        "reports/empty.json",
    ])
    .succeeds();
    let one = export(&["src/greet.js:1", "--format", "markdown"]).succeeds();
    assert!(one.contains("**1 mutant**"), "{one}");
    // A standard output with no room left.
    #[cfg(target_os = "linux")]
    {
        let full = std::fs::OpenOptions::new()
            .write(true)
            .open("/dev/full")
            .unwrap();
        let output = project
            .supercov_command(&["runs", "latest", "mutants", "--format", "jsonl"])
            .stdout(full)
            .output()
            .unwrap();
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert_eq!(output.status.code(), Some(2), "{stderr}");
        assert!(
            stderr.contains("could not write the mutants to standard output"),
            "{stderr}"
        );
    }
}

/// Every mutation report of one run, as its levels and languages grow: weak
/// mutation alone, then a change's mutants (`--diff`), then a second
/// language's mutants and a partial strong pass, in the HTML report's data,
/// the markdown table, StrykerJS's `mutation.json` and PIT's
/// `mutations.xml`.
#[cfg(unix)]
#[test]
fn mutation_reports_show_weak_strong_mixed_languages_and_a_change() {
    let (repository, project) = mutant_views_project("mutation-reports");
    let report = |name: &str, extra: &[&str]| {
        let mut command = vec!["report", "--no-open", "--output", name];
        command.extend(extra);
        project.supercov(&command).succeeds();
        report_data(&project.read(name))["runs"][0]["mutants"].clone()
    };
    let export = |arguments: &[&str]| {
        let mut command = vec!["runs", "latest", "mutants"];
        command.extend(arguments);
        project.supercov(&command)
    };
    // A plain run: its mutants are listed the first time they are asked for.
    project.supercov(&["--", "npx", "mocha"]).succeeds();
    let run = project.latest();
    export(&["--limit", "1"]).succeeds();

    // Weak mutation alone: every mutant pending, the survivors those no test
    // infects or reaches, one language.
    let weak = report("weak.html", &[]);
    assert_eq!(weak["strong"], false, "{weak}");
    assert_eq!(
        weak["languages"]
            .as_object()
            .unwrap()
            .keys()
            .collect::<Vec<_>>(),
        ["javascript"]
    );
    assert_eq!(weak["tally"]["mutants"], weak["summary"]["mutants"]);
    assert!(weak.get("diff").is_none());
    let alive = weak["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|mutant| mutant["alive"] == true)
        .count();
    assert!(alive > 0);
    assert_eq!(weak["tally"]["survivors"], alive);
    assert!(
        weak["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .all(|mutant| mutant["outcome"] == "pending")
    );
    let stryker = export(&["--format", "stryker"]).succeeds();
    let stryker: serde_json::Value = serde_json::from_str(&stryker).unwrap();
    assert_eq!(stryker["schemaVersion"], "2");
    assert_eq!(stryker["framework"]["name"], "Supercov");
    assert_eq!(
        stryker["files"]["src/cart.js"]["source"],
        project.read("src/cart.js")
    );
    for mutant in stryker["files"]["src/cart.js"]["mutants"]
        .as_array()
        .unwrap()
    {
        assert!(
            ["NoCoverage", "Survived", "Pending", "Ignored"]
                .contains(&mutant["status"].as_str().unwrap()),
            "{mutant}"
        );
    }

    // A change: only its lines' mutants, and what it was narrowed to.
    let change = report("change.html", &["--diff", "base"]);
    assert_eq!(change["diff"]["base"], "base", "{change}");
    let lines = change["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .map(|mutant| {
            (
                mutant["file"].as_str().unwrap().to_owned(),
                mutant["line"].as_u64().unwrap()..=mutant["endLine"].as_u64().unwrap(),
            )
        })
        .collect::<Vec<_>>();
    assert!(!lines.is_empty(), "{change}");
    for (file, span) in &lines {
        assert_eq!(file, "src/cart.js");
        assert!(span.contains(&5) || span.contains(&13), "{span:?}");
    }
    assert!(change["tally"]["mutants"].as_u64() < weak["tally"]["mutants"].as_u64());
    let refused = project.supercov(&[
        "report",
        "--no-open",
        "--output",
        "x.html",
        "--diff",
        "nowhere",
    ]);
    assert_ne!(refused.code(), 0);
    let missing = project.supercov(&["report", "--diff"]);
    assert_ne!(missing.code(), 0);
    assert!(
        missing.stderr().contains("--diff requires a base"),
        "{}",
        missing.stderr()
    );

    // A second language, listed beside the run, and a partial strong pass,
    // saved the way `mutants test` saves one.
    project.write("src/tax.py", "def tax(total):\n    return total * 2\n");
    let listed_path = format!(".supercov/runs/{run}/mutants-listed.json");
    let mut listed: serde_json::Value = serde_json::from_str(&project.read(&listed_path)).unwrap();
    listed["mutantSets"] =
        serde_json::json!({"javascript": listed["mutantSet"], "python": "mutmut@3.8.1"});
    listed["languages"] = serde_json::json!({"src/cart.js": "javascript", "src/tax.py": "python"});
    listed["files"]["src/tax.py"] = serde_json::json!([{"mutator": "ArithmeticOperator",
        "replacement": "total / 2", "start": [2, 12], "end": [2, 21], "original": "total * 2"}]);
    project.write(&listed_path, &listed.to_string());
    let ids = weak["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|mutant| mutant["file"] == "src/cart.js")
        .map(|mutant| mutant["id"].as_str().unwrap().to_owned())
        .collect::<Vec<_>>();
    let python = "src/tax.py:2:12-2:21:ArithmeticOperator:total / 2";
    project.write(
        &format!(".supercov/runs/{run}/strong-mutation.json"),
        &serde_json::json!({"schemaVersion": 1, "run": run, "mutantSet": "stryker-js@10.1.1", "mutants": {
            &ids[0]: {"status": "killed", "killedBy": "cart ships big orders free", "tests": 1, "durationMs": 5},
            &ids[1]: {"status": "survived", "tests": 2, "durationMs": 9},
            &ids[2]: {"status": "timeout", "tests": 1, "durationMs": 2000},
            python: {"status": "error", "tests": 0, "durationMs": 0, "reason": "no strong mutation driver for python yet"},
        }})
        .to_string(),
    );
    let strong = report("strong.html", &[]);
    assert_eq!(strong["strong"], true, "{strong}");
    assert_eq!(
        strong["languages"]
            .as_object()
            .unwrap()
            .keys()
            .collect::<Vec<_>>(),
        ["javascript", "python"]
    );
    assert_eq!(strong["tally"]["strong"]["killed"], 1);
    assert_eq!(strong["tally"]["strong"]["survived"], 1);
    assert_eq!(strong["tally"]["strong"]["timeout"], 1);
    assert_eq!(strong["tally"]["strong"]["notRun"], 1);
    assert!(strong["tally"]["strong"]["pending"].as_u64() > Some(0));
    assert_eq!(strong["tally"]["mutationScore"], 0.6667);
    assert_eq!(strong["languages"]["python"]["mutants"], 1);
    let by_id = |id: &str| {
        strong["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"] == id)
            .unwrap()
            .clone()
    };
    assert_eq!(by_id(&ids[0])["killedBy"], "cart ships big orders free");
    assert_eq!(by_id(&ids[1])["alive"], true);
    assert_eq!(by_id(python)["outcome"], "not-run");
    assert_eq!(by_id(python)["why"], "not run: no driver for python yet");
    // The static page shows the same mutation testing, and a change's.
    let page = |extra: &[&str]| {
        let mut command = vec!["runs", "latest", "report", "--format", "html", "--force"];
        command.extend(extra);
        project.supercov(&command).succeeds()
    };
    contains_all(
        &page(&[]),
        &[
            "<h2>Mutation testing</h2>",
            "javascript, python",
            "Strong mutation: 66.7%",
            "not run: no driver for python",
            "data-key=\"mutants\"",
            "<h3>Left alive: ",
        ],
    );
    let changed = page(&["--diff", "base"]);
    assert!(
        changed.contains("<strong>This change only:</strong>"),
        "{changed}"
    );
    let unknown = project
        .supercov(&[
            "runs", "latest", "report", "--format", "html", "--diff", "nowhere",
        ])
        .exits(2);
    assert!(unknown.contains("nowhere"), "{unknown}");
    // Mutants the run's index cannot give: the page is refused, and why said.
    let unread = project
        .supercov_with(
            &["runs", "latest", "report", "--format", "html"],
            &[("SUPERCOV_TEST_FAULT", "coverage-index@2")],
        )
        .exits(2);
    assert!(unread.contains("could not read run "), "{unread}");
    // A run whose index cannot be built again: refused the same way.
    for entry in std::fs::read_dir(project.root.join(format!(".supercov/runs/{run}"))).unwrap() {
        let path = entry.unwrap().path();
        if path
            .file_name()
            .unwrap()
            .to_string_lossy()
            .starts_with("query-index")
        {
            std::fs::remove_file(path).unwrap();
        }
    }
    let unopened = project
        .supercov_with(
            &["runs", "latest", "report", "--format", "html"],
            &[("SUPERCOV_TEST_FAULT", "fs.rename@1")],
        )
        .exits(2);
    assert!(unopened.contains("could not open run "), "{unopened}");
    let other = project
        .supercov(&[
            "runs", "latest", "report", "--format", "lcov", "--diff", "base",
        ])
        .exits(2);
    assert!(other.contains("give it with --format html"), "{other}");

    let markdown = export(&["--format", "markdown"]).succeeds();
    contains_all(
        &markdown,
        &[
            "Mutation score **66.7%** (of 3 of ",
            " mutants) · 1 killed · 1 timed out · 1 survived · 1 not run (no driver)",
            "| Where | Mutant | Weak | Strong | Tests on its line | Why |",
            " | survived | 2 | every test that reached it passed with it in place (2 tests ran) |",
        ],
    );
    let stryker: serde_json::Value =
        serde_json::from_str(&export(&["--format", "stryker"]).succeeds()).unwrap();
    assert_eq!(stryker["files"]["src/tax.py"]["language"], "python");
    let statuses = stryker["files"]["src/cart.js"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .map(|mutant| mutant["status"].as_str().unwrap().to_owned())
        .collect::<std::collections::BTreeSet<_>>();
    for status in ["Killed", "Survived", "Timeout"] {
        assert!(statuses.contains(status), "{statuses:?}");
    }
    let pit = export(&["--format", "pit", "--output", "mutations.xml"]);
    assert!(
        pit.stderr().contains("as a pit report to mutations.xml"),
        "{}",
        pit.stderr()
    );
    contains_all(
        &project.read("mutations.xml"),
        &[
            "<mutations partial=\"false\">",
            "status=\"KILLED\"",
            "status=\"TIMED_OUT\"",
            "<killingTest>cart ships big orders free</killingTest>",
            "<sourceFile>tax.py</sourceFile><mutatedClass>src.tax</mutatedClass>",
        ],
    );
    // A file the checkout no longer holds: left out of StrykerJS's report,
    // which needs every file's source, and said so.
    std::fs::remove_file(project.root.join("src/tax.py")).unwrap();
    let written = export(&["--format", "stryker", "--output", "mutation.json"]);
    assert!(
        written
            .stderr()
            .contains("src/tax.py could not be read: its mutants are left out of the report"),
        "{}",
        written.stderr()
    );
    let kept: serde_json::Value = serde_json::from_str(&project.read("mutation.json")).unwrap();
    assert!(kept["files"].get("src/tax.py").is_none());
    let bogus = export(&["--format", "bogus"]).exits(2);
    assert!(bogus.contains("jsonl, markdown, stryker or pit"), "{bogus}");
    // A file with no mutants: a report with no file.
    let empty: serde_json::Value =
        serde_json::from_str(&export(&["src/consts.js", "--format", "stryker"]).succeeds())
            .unwrap();
    assert_eq!(empty["files"], serde_json::json!({}));
    // Piped, the static HTML export is printed, as every format is.
    assert!(
        project
            .supercov(&["runs", "latest", "report", "--format", "html"])
            .succeeds()
            .starts_with("<!doctype html>")
    );
    // The static HTML export is not printed into a terminal: it is written
    // beside the store's reports, again each time, and the path said.
    for _ in 0..2 {
        let mut terminal =
            common::OnTerminal::start(&project, &["runs", "latest", "report", "--format", "html"]);
        terminal.wait_for("coverage-report.html (html)");
        let (code, seen) = terminal.finish();
        assert_eq!(code, 0, "{seen}");
        assert!(!seen.contains("<!doctype"), "{seen}");
    }
    assert!(
        project
            .read(".supercov/reports/coverage-report.html")
            .starts_with("<!doctype html>")
    );
    // A change with no mutant on its lines still says what it was narrowed to.
    repository.commit("everything");
    let unchanged = report("unchanged.html", &["--diff", "HEAD"]);
    assert_eq!(unchanged["tally"]["mutants"], 0, "{unchanged}");
    assert_eq!(unchanged["diff"]["base"], "HEAD", "{unchanged}");
}

/// `--stryker` and the other mutants options each name what they need, and
/// a report or directory of reports that cannot be read is said to be so.
#[cfg(unix)]
#[test]
fn mutants_options_and_stryker_reports_that_cannot_be_read_are_refused() {
    let (_repository, project) = mutant_views_project("mutants-stryker-refusals");
    project.supercov(&["--", "npx", "mocha"]).succeeds();
    // A source changed since a run whose mutants were never listed: its
    // mutants are not listed, and that is said.
    project.edit("src/greet.js", "Hello there", "Hi there");
    let changed = project.supercov(&["runs", "latest", "mutants"]);
    let said = format!("{}{}", changed.succeeds(), changed.stderr());
    assert!(said.contains("1 file(s) changed since run"), "{said}");
    for (flag, said) in [
        ("--status", "--status requires statuses"),
        ("--mutator", "--mutator requires a StrykerJS mutator"),
        (
            "--stryker",
            "--stryker requires a StrykerJS mutation.json report",
        ),
        ("--diff", "--diff requires a git ref"),
        ("--fail-on", "--fail-on requires statuses"),
        ("--stryker-root", "--stryker-root requires a directory"),
    ] {
        let refused = project
            .supercov(&["runs", "latest", "mutants", flag])
            .exits(2);
        assert!(refused.contains(said), "{flag}: {refused}");
    }
    // No status named: every mutant, as with no --status.
    project
        .supercov(&["runs", "latest", "mutants", "--status", ","])
        .succeeds();
    std::fs::create_dir_all(project.root.join("reports/void/deeper")).unwrap();
    let void = project
        .supercov(&["runs", "latest", "mutants", "--stryker", "reports/void"])
        .exits(2);
    assert!(
        void.contains("reports/void holds no .json report"),
        "{void}"
    );
    project.write("reports/broken.json", "not json");
    let broken = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--stryker",
            "reports/broken.json",
        ])
        .exits(2);
    assert!(
        broken.contains("Could not read reports/broken.json as a StrykerJS report"),
        "{broken}"
    );
    for fault in [
        "fs.read_dir#public-query.json-files",
        "fs.read_dir entry#public-query.json-files",
    ] {
        let unlisted = project
            .supercov_with(
                &["runs", "latest", "mutants", "--stryker", "reports"],
                &[("SUPERCOV_TEST_FAULT", fault)],
            )
            .exits(2);
        assert!(
            unlisted.contains("Could not read reports: "),
            "{fault}: {unlisted}"
        );
        assert!(
            fired_at(&unlisted, "public-query.json-files"),
            "{fault}: {unlisted}"
        );
    }
    // A report that is not UTF-8, and a directory's `.json.gz` file read as
    // the mutant gem's session results, which these bytes are not.
    std::fs::write(project.root.join("reports/bytes.json"), [0xff, 0xfe]).unwrap();
    let bytes = project
        .supercov(&[
            "runs",
            "latest",
            "mutants",
            "--stryker",
            "reports/bytes.json",
        ])
        .exits(2);
    assert!(
        bytes.contains("Could not read reports/bytes.json: "),
        "{bytes}"
    );
    std::fs::create_dir_all(project.root.join("reports/ruby")).unwrap();
    std::fs::write(
        project.root.join("reports/ruby/session.json.gz"),
        [0x1f, 0x8b, 0],
    )
    .unwrap();
    let session = project
        .supercov(&["runs", "latest", "mutants", "--stryker", "reports/ruby"])
        .exits(2);
    assert!(
        session.contains("Could not read reports/ruby/session.json.gz as mutant's session results"),
        "{session}"
    );
}

/// A Ruby method's mutants are the mutant gem's, listed from a plain run,
/// and the strong pass runs them in forks of the loaded Minitest suite: a
/// boundary the test checks is killed, a literal it cannot tell from 0
/// survives, and a method no test calls is no coverage.
#[cfg(unix)]
/// A Ruby process a test starts with `--disable-gems` (test-unit's
/// `assert_separately`) loads Supercov's runtime through RUBYOPT without
/// RubyGems, which loaded `rbconfig` for it: the runtime disabled itself
/// and said so on the child's error output, which such tests read.
#[test]
fn ruby_children_without_rubygems_keep_their_error_output_clean() {
    let Some(ruby) = ruby() else {
        return;
    };
    let project = Project::empty("ruby-disable-gems");
    project.write("lib/noop.rb", "def noop\n  1\nend\n");
    project.write(
        "test/child_test.rb",
        "require 'minitest/autorun'\nrequire 'open3'\nrequire 'noop'\n\nclass ChildTest < Minitest::Test\n  def test_child\n    noop\n    out, err, = Open3.capture3(RbConfig.ruby, '--disable-gems', '-e', 'print 1')\n    assert_equal ['1', ''], [out, err]\n  end\nend\n",
    );
    project.git(&["init", "-q"]);
    project.commit("fixture");
    project
        .supercov(&["--", ruby.as_str(), "-Ilib", "test/child_test.rb"])
        .succeeds();
}

/// A Ruby run measured for mutants records, per test, whether each mutant
/// a value probe computes would have given the original's value: a call's
/// other method, its receiver alone, a condition's truth.
#[cfg(unix)]
#[test]
fn ruby_value_probes_tell_which_mutants_no_test_infects() {
    let Some(ruby) = ruby() else {
        return;
    };
    let project = Project::empty("ruby-values");
    project.write(
        "lib/label.rb",
        "class Label\n  def tidy(s)\n    s.strip\n  end\n\n  def pick(flag)\n    flag ? :on : :off\n  end\n\n  def small?(n)\n    n < 10\n  end\nend\n",
    );
    project.write(
        "test/label_test.rb",
        "require 'minitest/autorun'\nrequire 'label'\n\nclass LabelTest < Minitest::Test\n  def test_tidy\n    assert_equal 'a', Label.new.tidy('a')\n  end\n\n  def test_pick\n    assert_equal :on, Label.new.pick(true)\n  end\n\n  def test_small\n    assert Label.new.small?(3)\n  end\nend\n",
    );
    project.git(&["init", "-q"]);
    project.commit("fixture");
    project
        .supercov_with(
            &["--", ruby.as_str(), "-Ilib", "test/label_test.rb"],
            &[("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let status = |id: &str| {
        listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"] == id)
            .map(|mutant| mutant["status"].as_str().unwrap_or_default().to_owned())
            .unwrap_or_else(|| format!("missing: {listed}"))
    };
    for (id, expected) in [
        // `"a".lstrip` and `"a"` are `"a".strip`; `nil` is not.
        ("lib/label.rb:3:5-3:12:Send:s.lstrip", "not-infected"),
        ("lib/label.rb:3:5-3:12:Send:s", "not-infected"),
        ("lib/label.rb:3:5-3:12:Send:nil", "infected"),
        // The flag was only ever true.
        ("lib/label.rb:7:5-7:9:NamedValue:true", "not-infected"),
        ("lib/label.rb:7:5-7:9:NamedValue:false", "infected"),
        // `3 < 10` is true; `3 == 10`, `10` and `nil` are not.
        ("lib/label.rb:11:5-11:11:Send:n == 10", "infected"),
        ("lib/label.rb:11:5-11:11:Send:10", "infected"),
        ("lib/label.rb:11:5-11:11:Send:nil", "infected"),
    ] {
        assert_eq!(status(id), expected, "{id}");
    }
}

#[cfg(unix)]
#[test]
fn ruby_mutants_are_mutant_gems_and_the_strong_pass_runs_them_in_minitest() {
    let Some(ruby) = ruby() else {
        return;
    };
    let project = Project::empty("ruby-strong");
    project.write(
        "lib/calc.rb",
        "class Calc\n  def add(a, b)\n    a + b\n  end\n\n  def big?(n)\n    n > 10\n  end\n\n  def unused(x)\n    x * 2\n  end\nend\n",
    );
    project.write(
        "test/calc_test.rb",
        "require 'minitest/autorun'\nrequire 'calc'\n\nclass CalcTest < Minitest::Test\n  def test_adds\n    assert_equal 3, Calc.new.add(1, 2)\n  end\n\n  def test_big\n    assert Calc.new.big?(20)\n    refute Calc.new.big?(3)\n  end\nend\n",
    );
    project.git(&["init", "-q"]);
    project.commit("fixture");
    project
        .supercov(&["--", ruby.as_str(), "-Ilib", "test/calc_test.rb"])
        .succeeds();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "500"])
        .json();
    assert_eq!(listed["data"]["mutantSet"], "mutant@0.17.1", "{listed}");
    let ids = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .map(|mutant| mutant["id"].as_str().unwrap().to_owned())
        .collect::<Vec<_>>();
    for id in [
        "lib/calc.rb:7:5-7:11:Send:n == 10",
        "lib/calc.rb:7:9-7:11:Integer:0",
        "lib/calc.rb:3:5-3:10:Send:a - b",
        "lib/calc.rb:11:5-11:10:Send:x / 2",
    ] {
        assert!(ids.iter().any(|each| each == id), "{id} in {ids:?}");
    }
    let ran = project.supercov(&["runs", "latest", "mutants", "test", "--json"]);
    let said = ran.stderr();
    let reply = ran.json();
    assert_eq!(reply["summary"]["error"], 0, "{reply}\n{said}");
    let strong = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "500"])
        .json();
    let status = |id: &str| {
        strong["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"] == id)
            .map(|mutant| {
                mutant["strong"]["status"]
                    .as_str()
                    .unwrap_or_default()
                    .to_owned()
            })
            .unwrap_or_default()
    };
    assert_eq!(
        status("lib/calc.rb:7:5-7:11:Send:n == 10"),
        "killed",
        "{strong}\n{said}"
    );
    assert_eq!(
        status("lib/calc.rb:3:5-3:10:Send:a - b"),
        "killed",
        "{strong}"
    );
    assert_eq!(
        status("lib/calc.rb:7:9-7:11:Integer:11"),
        "survived",
        "{strong}"
    );
    assert_eq!(
        status("lib/calc.rb:11:5-11:10:Send:x / 2"),
        "no-coverage",
        "{strong}"
    );
}

/// Go's strong pass: every Gremlins mutant of a module, run in test
/// binaries built once, each mutant against the tests that ran its code.
/// A mutant that does not compile is `unviable`; a constant Go needs as a
/// constant is built alone; a loop made endless is a `timeout`; code no
/// test runs is `no-coverage`.
#[cfg(unix)]
#[test]
fn go_mutants_are_killed_kept_or_found_not_to_compile() {
    let Some(go) = go() else {
        eprintln!("skipping: no Go toolchain found");
        return;
    };
    let project = Project::empty("go-strong");
    // A module older than Go 1.21: each file with a value probe is built
    // as 1.21.
    project.write("go.mod", "module example.com/calc\n\ngo 1.20\n");
    project.write(
        "calc.go",
        "package calc\n\nconst Limit = 2 + 3\n\nfunc Clamp(n int) int {\n\tif n > Limit {\n\t\treturn Limit\n\t}\n\treturn n\n}\n\nfunc Sum(n int) int {\n\ttotal := 0\n\tfor i := 0; i < n; i++ {\n\t\ttotal += i\n\t}\n\treturn total\n}\n\nfunc Join(a, b string) string { return a + b }\n\nfunc Half(n int) int { return n / 2 }\n\nfunc Unused(n int) int { return n - 1 }\n",
    );
    project.write(
        "calc_test.go",
        "package calc\n\nimport \"testing\"\n\nfunc TestClamp(t *testing.T) {\n\tif Clamp(5) != 5 || Clamp(6) != 5 || Clamp(1) != 1 {\n\t\tt.Fatal(\"clamp\")\n\t}\n}\n\nfunc TestSum(t *testing.T) {\n\tif Sum(4) != 6 {\n\t\tt.Fatal(\"sum\")\n\t}\n}\n\nfunc TestJoinAndHalf(t *testing.T) {\n\tif Join(\"a\", \"b\") != \"ab\" || Half(0) != 0 {\n\t\tt.Fatal(\"join\")\n\t}\n}\n",
    );
    project
        .supercov_with(
            &["mutants", "--json", "--", go, "test", "./..."],
            &[("SUPERCOV_MUTANT_HIT_LIMIT", "100000")],
        )
        .succeeds();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let status = |id: &str| {
        listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"] == id)
            .unwrap_or_else(|| panic!("no {id} in {listed}"))["strong"]["status"]
            .clone()
    };
    assert_eq!(listed["data"]["mutantSet"], "gremlins@0.6.0", "{listed}");
    // Built alone: a constant declaration has no place for a switch.
    assert_eq!(status("calc.go:3:17-3:18:ArithmeticOperator:-"), "killed");
    // At 5, `n > 5` and `n >= 5` both return 5: no test can tell them.
    assert_eq!(status("calc.go:6:7-6:8:EqualityOperator:>="), "survived");
    assert_eq!(status("calc.go:6:7-6:8:EqualityOperator:<="), "killed");
    // `i--` never ends the loop.
    assert_eq!(status("calc.go:14:22-14:24:UpdateOperator:--"), "timeout");
    // Strings have no `-`.
    assert_eq!(
        status("calc.go:20:42-20:43:ArithmeticOperator:-"),
        "unviable"
    );
    // `0 * 2` is `0 / 2`: no test tells them apart.
    assert_eq!(
        status("calc.go:22:33-22:34:ArithmeticOperator:*"),
        "survived"
    );
    assert_eq!(
        status("calc.go:24:35-24:36:ArithmeticOperator:+"),
        "no-coverage"
    );
}

/// A Go suite behind `make test`: the strong pass builds its test binaries
/// with the flags the Makefile gives `go test`, as the measured run recorded
/// them. Without the tag, the file behind it would not be built at all, and
/// its mutant could not be killed.
#[cfg(unix)]
#[test]
fn go_mutants_of_a_wrapped_command_are_built_with_its_flags() {
    let Some(go) = go() else {
        eprintln!("skipping: no Go toolchain found");
        return;
    };
    let project = Project::empty("go-strong-make");
    project.write("go.mod", "module example.com/tagged\n\ngo 1.22\n");
    project.write(
        "double.go",
        "//go:build tagged\n\npackage tagged\n\nfunc Double(n int) int { return n * 2 }\n",
    );
    project.write(
        "double_test.go",
        "//go:build tagged\n\npackage tagged\n\nimport \"testing\"\n\nfunc TestDouble(t *testing.T) {\n\tif Double(3) != 6 {\n\t\tt.Fatal(\"double\")\n\t}\n}\n",
    );
    let directory = std::path::Path::new(go)
        .parent()
        .map(|dir| dir.display().to_string())
        .unwrap_or_default();
    project.write(
        "Makefile",
        &format!("test:\n\tPATH=\"$$PATH:{directory}\" go test -tags tagged ./...\n"),
    );
    project
        .supercov(&["mutants", "--json", "--", "make", "test"])
        .succeeds();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutant = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .find(|mutant| mutant["id"] == "double.go:5:35-5:36:ArithmeticOperator:/")
        .unwrap_or_else(|| panic!("{listed}"))
        .clone();
    assert_eq!(mutant["strong"]["status"], "killed", "{mutant}");
}

/// Ctrl-C during a JavaScript strong pass, sent to Supercov's process group
/// as a terminal sends it: the resident runners and what their jobs started
/// stop, though each runs in a process group of its own, Supercov exits as
/// the signal does, and what the pass decided is saved.
#[cfg(unix)]
#[test]
fn an_interrupted_javascript_pass_leaves_no_process_running() {
    use std::os::unix::process::CommandExt;
    let project = mutants_project("js-strong-interrupted");
    // A function only this test runs: under a mutant (its value is not 4),
    // the test starts a process and waits, its pid and the runner's to the
    // marker.
    project.write("src/twice.js", "export const twice = (n) => n * 2;\n");
    project.write(
        "test/slow.test.js",
        "import assert from \"node:assert/strict\";\nimport { spawn } from \"node:child_process\";\nimport { renameSync, writeFileSync } from \"node:fs\";\nimport { twice } from \"../src/twice.js\";\ndescribe(\"slow\", () => {\n  it(\"waits under a mutant\", async function () {\n    this.timeout(0);\n    if (twice(2) === 4) return;\n    const sleeper = spawn(\"sleep\", [\"120\"], { stdio: \"ignore\" });\n    const marker = process.env.SUPERCOV_TEST_MARKER;\n    writeFileSync(`${marker}.tmp`, `${process.pid} ${sleeper.pid}`);\n    renameSync(`${marker}.tmp`, marker);\n    await new Promise((done) => setTimeout(done, 120000));\n  });\n});\n",
    );
    project.commit("slow");
    project
        .supercov_with(&["--", "npx", "mocha"], &[("SUPERCOV_MUTANTS", "1")])
        .succeeds();
    let run = project.latest();
    let marker = project.root.with_extension("marker");
    let _ = std::fs::remove_file(&marker);
    let mut supercov = project
        .supercov_command(&["runs", "latest", "mutants", "test"])
        .env("SUPERCOV_TEST_MARKER", &marker)
        .process_group(0)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .unwrap();
    let started = std::time::Instant::now();
    while !marker.exists() {
        assert!(
            started.elapsed() < std::time::Duration::from_secs(120),
            "the strong pass never started its tests"
        );
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    let pids = std::fs::read_to_string(&marker)
        .unwrap()
        .split_whitespace()
        .map(|pid| pid.parse::<i32>().unwrap())
        .collect::<Vec<_>>();
    // SAFETY: a signal to the process group this test started.
    unsafe { libc::kill(-(supercov.id() as i32), libc::SIGINT) };
    let status = supercov.wait().unwrap();
    let running = |pid: i32| {
        // SAFETY: signal 0 only asks whether the process is there.
        unsafe { libc::kill(pid, 0) == 0 }
    };
    let gone = (0..50).any(|_| {
        std::thread::sleep(std::time::Duration::from_millis(100));
        !pids.iter().any(|pid| running(*pid))
    });
    let _ = std::fs::remove_file(&marker);
    for pid in &pids {
        if running(*pid) {
            // SAFETY: cleaning up a process this test's run left.
            unsafe { libc::kill(*pid, libc::SIGKILL) };
        }
    }
    assert!(gone, "{pids:?} outlived the interrupted pass");
    assert_eq!(status.code(), Some(130), "{status:?}");
    assert!(
        project
            .root
            .join(format!(".supercov/runs/{run}/strong-mutation.json"))
            .is_file()
    );
}

/// A Vitest project for passes cut short: `src/cart.js`'s mutants are
/// decided at once, while each of `src/slow.js`'s holds its test for five
/// minutes, past its limit, the test's process id written to
/// `SUPERCOV_TEST_MARKER` first.
#[cfg(unix)]
fn vitest_slow_project(label: &str) -> Project {
    vitest_slow_project_waiting(label, 0)
}

/// `vitest_slow_project`, its slow test also taking `unmutated_ms` without
/// a mutant: a mutant's test is given three times its measured time and
/// 10 s more, so the longer it takes, the later slow.js's mutants are
/// judged timeouts.
#[cfg(unix)]
fn vitest_slow_project_waiting(label: &str, unmutated_ms: u64) -> Project {
    let project = vitest_mutants_project(label);
    project.write("src/slow.js", "export const twice = (n) => n * 2;\n");
    let unmutated = if unmutated_ms > 0 {
        format!(
            " else {{\n    await new Promise((done) => setTimeout(done, {unmutated_ms}));\n  }}"
        )
    } else {
        String::new()
    };
    project.write(
        "test/slow.test.js",
        &format!(
            "import {{ renameSync, writeFileSync }} from \"node:fs\";\nimport {{ expect, it }} from \"vitest\";\nimport {{ twice }} from \"../src/slow.js\";\nit(\"doubles\", async () => {{\n  if (twice(2) !== 4) {{\n    const marker = process.env.SUPERCOV_TEST_MARKER;\n    if (marker) {{\n      writeFileSync(`${{marker}}.tmp`, String(process.pid));\n      renameSync(`${{marker}}.tmp`, marker);\n    }}\n    await new Promise((done) => setTimeout(done, 300000));\n  }}{unmutated}\n  expect(twice(2)).toBe(4);\n}}, 300000);\n"
        ),
    );
    project.commit("slow");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    project
}

/// The saved verdicts of `project`'s latest run, by mutant id.
#[cfg(unix)]
fn saved_statuses(project: &Project) -> std::collections::BTreeMap<String, String> {
    let run = project.latest();
    std::fs::read(
        project
            .root
            .join(format!(".supercov/runs/{run}/strong-mutation.json")),
    )
    .ok()
    .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
    .and_then(|saved| saved["mutants"].as_object().cloned())
    .unwrap_or_default()
    .into_iter()
    .map(|(id, verdict)| (id, verdict["status"].as_str().unwrap_or("").to_owned()))
    .collect()
}

/// A Vitest pass sent a signal -- only Supercov, as `timeout` signals the
/// command it runs, the tests' processes being in a group of their own --
/// stops its workers and ends within seconds, as the signal ends it, with
/// the verdicts it reached saved. A pass that does not end once told to
/// (a test makes one linger) is ended `STOP_PATIENCE` (8 s) after the
/// signal, what it decided saved first.
#[cfg(unix)]
#[test]
fn a_vitest_pass_sent_a_signal_ends_in_seconds_with_what_it_decided_saved() {
    let project = vitest_slow_project("strong-signalled");
    let run = project.latest();
    let marker = project.root.with_extension("marker");
    let stop = |signal: i32, faults: &str| {
        let _ = std::fs::remove_file(
            project
                .root
                .join(format!(".supercov/runs/{run}/strong-mutation.json")),
        );
        let _ = std::fs::remove_file(&marker);
        let mut supercov = project
            .supercov_command(&["runs", "latest", "mutants", "test"])
            .env("SUPERCOV_TEST_MARKER", &marker)
            .env("SUPERCOV_TEST_FAULT", faults)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .unwrap();
        // The slow copy is running, and cart.js's mutants are decided.
        let started = std::time::Instant::now();
        while !marker.exists()
            || saved_statuses(&project)
                .values()
                .all(|status| status != "killed")
        {
            assert!(
                started.elapsed() < std::time::Duration::from_secs(120),
                "the pass never got under way"
            );
            std::thread::sleep(std::time::Duration::from_millis(50));
        }
        let test = std::fs::read_to_string(&marker)
            .unwrap()
            .trim()
            .parse::<i32>()
            .unwrap();
        // SAFETY: a signal to the process this test started.
        unsafe { libc::kill(supercov.id() as i32, signal) };
        let told = std::time::Instant::now();
        let mut said = String::new();
        std::io::Read::read_to_string(supercov.stderr.as_mut().unwrap(), &mut said).unwrap();
        let status = supercov.wait().unwrap();
        let took = told.elapsed();
        // SAFETY: signal 0 only asks whether the process is there.
        let gone = (0..50).any(|_| {
            std::thread::sleep(std::time::Duration::from_millis(100));
            unsafe { libc::kill(test, 0) != 0 }
        });
        if !gone {
            // SAFETY: cleaning up a process this test's pass left.
            unsafe { libc::kill(test, libc::SIGKILL) };
        }
        assert!(gone, "the slow copy's worker outlived the pass\n{said}");
        let killed = saved_statuses(&project)
            .values()
            .filter(|status| *status == "killed")
            .count();
        assert!(killed > 0, "{said}");
        (status.code(), took, said)
    };
    let (code, took, said) = stop(libc::SIGTERM, "");
    assert_eq!(code, Some(143), "{said}");
    assert!(took < std::time::Duration::from_secs(8), "{took:?}\n{said}");
    assert!(
        said.contains(
            "[supercov] interrupted: the verdicts the pass reached are saved into the run"
        ),
        "{said}"
    );
    let (code, took, said) = stop(libc::SIGINT, "strong-pass-lingers");
    assert_eq!(code, Some(130), "{said}");
    assert!(
        took >= std::time::Duration::from_secs(8) && took < std::time::Duration::from_secs(14),
        "{took:?}\n{said}"
    );
    assert!(
        said.contains("[supercov] the strong pass did not end within 8 s of being told to stop (sent SIGINT), so it is ended: the verdicts it reached are saved into the run"),
        "{said}"
    );
}

/// A command still running past its budget is ended by the budget's own
/// deadline, whatever holds it up: here the progress loop that stops a pass
/// at its budget never gets to (it stalls), and the pass would never end on
/// its own. It ends about 45 s after the budget, and says why.
#[cfg(unix)]
#[test]
fn a_command_held_up_past_its_budget_is_ended_by_the_budget_s_deadline() {
    let project = vitest_slow_project_waiting("strong-budget-deadline", 10_000);
    let started = std::time::Instant::now();
    let held = project.supercov_with(
        &["runs", "latest", "mutants", "test", "--budget", "3"],
        &[(
            "SUPERCOV_TEST_FAULT",
            "strong-progress-stalls,strong-pass-lingers",
        )],
    );
    let took = started.elapsed();
    let said = held.stderr();
    assert_eq!(held.code(), 143, "{said}");
    assert!(
        took >= std::time::Duration::from_secs(3 + 45)
            && took < std::time::Duration::from_secs(3 + 45 + 15),
        "{took:?}\n{said}"
    );
    assert!(
        said.contains("[supercov] still running 45 s after its budget was spent, so it is ended"),
        "{said}"
    );
}

/// `--budget <seconds>`: once it is spent the pass stops and ends as one
/// that finished, the verdicts it reached saved, the mutants left without
/// one for the next pass -- not errors, and not a pass that ran nothing.
/// A pass that does not end once its budget is spent is ended in time. The
/// budget is the whole command's: what `supercov mutants` spent measuring
/// is not the pass's, and a budget measuring spent runs nothing.
#[cfg(unix)]
#[test]
fn a_budget_ends_the_pass_and_leaves_the_rest_for_the_next() {
    // Ten seconds without a mutant: slow.js's mutants are judged timeouts
    // 40 s into their copies, well past the budget below. Given 13 s, the
    // limit of a test that takes no time, they were judged before a slow
    // runner's budget was spent.
    let project = vitest_slow_project_waiting("strong-budget", 10_000);
    let slow_ids = || {
        saved_statuses(&project)
            .into_iter()
            .filter(|(id, _)| id.starts_with("src/slow.js:"))
            .collect::<Vec<_>>()
    };
    // Spent before any slow mutant could end.
    let first = project.supercov(&[
        "runs",
        "latest",
        "mutants",
        "test",
        "--file",
        "src/slow.js",
        "--budget",
        "1",
        "--json",
    ]);
    let reply = first.json();
    assert_eq!(first.code(), 0, "{reply}\n{}", first.stderr());
    let left = reply["budget"]["left"].as_u64().unwrap();
    assert!(left > 0, "{reply}");
    assert_eq!(reply["budget"]["seconds"], 1, "{reply}");
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    assert!(reply["result"].is_null(), "{reply}");
    assert!(slow_ids().is_empty(), "{:?}", slow_ids());
    // Long enough for cart.js's mutants, not for slow.js's, whose test waits
    // five minutes and is judged a timeout 40 s in. What cart.js's take is
    // this machine's: a fixed twelve seconds decided only some of them on a
    // busy macOS runner. Timed by a pass of their own, whose verdicts are
    // then forgotten.
    let timed = project.supercov(&[
        "runs",
        "latest",
        "mutants",
        "test",
        "--file",
        "src/cart.js",
        "--json",
    ]);
    let reply = timed.json();
    assert_eq!(timed.code(), 0, "{reply}\n{}", timed.stderr());
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    let cart_ms = reply["summary"]["durationMs"].as_u64().unwrap();
    let run = project.latest();
    std::fs::remove_file(
        project
            .root
            .join(format!(".supercov/runs/{run}/strong-mutation.json")),
    )
    .unwrap();
    // Three times that beside slow.js's copies, and short of their 40 s.
    let budget = (cart_ms * 3 / 1000 + 10).min(30).to_string();
    let second = project.supercov(&[
        "runs", "latest", "mutants", "test", "--budget", &budget, "--json",
    ]);
    let reply = second.json();
    assert_eq!(second.code(), 0, "{reply}\n{}", second.stderr());
    assert!(reply["summary"]["killed"].as_u64() > Some(0), "{reply}");
    assert_eq!(reply["budget"]["left"].as_u64(), Some(left), "{reply}");
    assert!(slow_ids().is_empty(), "{:?}", slow_ids());
    // A pass that lingers once its budget is spent.
    let lingering = project.supercov_with(
        &["runs", "latest", "mutants", "test", "--budget", "1"],
        &[("SUPERCOV_TEST_FAULT", "strong-pass-lingers")],
    );
    let said = lingering.stderr();
    assert_eq!(lingering.code(), 143, "{said}");
    assert!(
        said.contains(
            "did not end within 8 s of being told to stop (its budget spent), so it is ended"
        ) && said.contains("[supercov] budget spent, "),
        "{said}"
    );
    // Measured first, as the latest run recorded no values for its
    // mutants: measuring, which takes two seconds here, spends the budget,
    // and the pass runs nothing.
    let started = std::time::Instant::now();
    let measured = project.supercov(&[
        "mutants",
        "--file",
        "src/slow.js",
        "--budget",
        "1",
        "--",
        "sh",
        "-c",
        "sleep 2 && npx vitest run",
    ]);
    let (out, said) = (measured.stdout(), measured.stderr());
    assert_eq!(measured.code(), 0, "{out}\n{said}");
    assert!(said.contains("measuring first"), "{said}");
    assert!(
        out.contains("  budget of 1 s spent: 2 mutant(s) left without a verdict")
            && out.contains(" s of the 1 s budget, which leaves the pass 0 s\n"),
        "{out}"
    );
    // Ended once measuring did: no pass began.
    assert!(
        !said.contains("strong pass:") && started.elapsed() < std::time::Duration::from_secs(60),
        "{said}"
    );
}

/// A pass told to stop judges nothing from then on: its copies are being
/// stopped under their tests, and one that ends then says nothing of its
/// mutant. A pass the budget stopped on a macOS runner saved a mutant whose
/// test waits five minutes as `killed`. Here the mutant's test stands in for
/// the stop: it marks the pass as stopping (`stopped-at`, beside its
/// results, as Supercov does before it signals the command) and its copy's
/// process exits at once, as one the stop reached before the pass's own
/// process did. That copy did not finish its file: judged, its mutant was
/// `killed`; now it has no verdict from this pass.
#[cfg(unix)]
#[test]
fn a_copy_that_ends_once_the_pass_is_stopping_decides_nothing() {
    let project = vitest_mutants_project("strong-stopping-copy");
    project.write("src/slow.js", "export const twice = (n) => n * 2;\n");
    project.write(
        "test/slow.test.js",
        "import { writeFileSync } from \"node:fs\";\nimport { dirname, join } from \"node:path\";\nimport { expect, it } from \"vitest\";\nimport { twice } from \"../src/slow.js\";\nit(\"doubles\", () => {\n  const results = process.env.SUPERCOV_STRONG_RESULTS;\n  if (twice(2) !== 4 && results) {\n    writeFileSync(join(dirname(results), \"stopped-at\"), String(Date.now()));\n    process.exit(1);\n  }\n  expect(twice(2)).toBe(4);\n});\n",
    );
    project.commit("slow");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let ran = project.supercov(&[
        "runs",
        "latest",
        "mutants",
        "test",
        "--file",
        "src/slow.js",
        "--json",
    ]);
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let slow = listed["data"]["mutants"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|mutant| mutant["id"].as_str().unwrap().starts_with("src/slow.js:"))
        .collect::<Vec<_>>();
    assert_eq!(slow.len(), 2, "{listed}");
    for mutant in slow {
        assert_ne!(
            mutant["strong"]["status"],
            "killed",
            "{mutant}\n{}",
            ran.stderr()
        );
    }
}

/// Copies run within the project's own worker limit, each with a pool id
/// Vitest gave it (1 to `maxWorkers`) that no copy running beside it has: a
/// setup file that gives each worker its own database by `VITEST_POOL_ID`,
/// and throws where the id is past the databases it made or another
/// copy's still in use, lets every copy run, and every mutant gets a
/// verdict.
#[cfg(unix)]
#[test]
fn copies_keep_to_the_project_s_workers_and_their_pool_ids() {
    let project = vitest_mutants_project("strong-pool-ids");
    project.write(
        "vitest.config.js",
        "export default { test: { maxWorkers: 2, setupFiles: [\"./test/database.js\"] } };\n",
    );
    project.write(
        "test/database.js",
        "import { mkdirSync, readFileSync, rmSync, writeFileSync } from \"node:fs\";\nimport { afterAll } from \"vitest\";\nconst worker = Number(process.env.VITEST_POOL_ID);\nif (!(worker >= 1 && worker <= 2)) throw new Error(`Worker ${worker} has no database: 2 were made`);\nconst locks = new URL(\"../.databases/\", import.meta.url);\nmkdirSync(locks, { recursive: true });\nconst lock = new URL(String(worker), locks);\nlet holder;\ntry { holder = Number(readFileSync(lock, \"utf8\")); } catch {}\nif (holder && holder !== process.pid) {\n  let running = true;\n  try { process.kill(holder, 0); } catch { running = false; }\n  if (running) throw new Error(`Worker ${worker}'s database is in use by process ${holder}`);\n}\nwriteFileSync(lock, String(process.pid));\nafterAll(() => rmSync(lock, { force: true }));\n",
    );
    for file in ["a", "b", "c"] {
        project.write(
            &format!("test/{file}.test.js"),
            "import { describe, expect, it } from \"vitest\";\nimport { shipping, label, refund } from \"../src/cart.js\";\nconst nap = () => new Promise((done) => setTimeout(done, 50));\ndescribe(\"cart\", () => {\n  it(\"ships big orders free\", async () => { await nap(); expect(shipping(80)).toBe(0); });\n  it(\"charges small orders\", async () => { await nap(); expect(shipping(10)).toBe(5); });\n  it(\"labels\", async () => { await nap(); expect(label(\" a \")).toBe(\"A\"); });\n  it(\"refunds\", async () => { await nap(); expect(refund(200)).toBe(180); });\n});\n",
        );
    }
    project.write(".gitignore", "node_modules\n.supercov\n.databases\n");
    project.commit("a database per worker");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let reply = project
        .supercov(&["runs", "latest", "mutants", "test", "--json"])
        .json();
    assert_eq!(reply["summary"]["error"], 0, "{reply}");
    assert!(reply["summary"]["killed"].as_u64() >= Some(5), "{reply}");
    assert_eq!(
        reply["passes"][0]["profile"]["unevaluatedReruns"], 0,
        "{reply}"
    );
}

/// A mutant that makes a hook fail (a `beforeAll` seeding through a schema
/// the mutant broke) is killed: Vitest skips the hook's tests and fails the
/// run, and the reason is the hook's error. A copy whose file does not load
/// or set up before its mutant ran runs again; where that repeats, the
/// mutant is an error that says the file's error. A copy that ran none of
/// its tests says why. The staged pass judges a hook alike.
#[cfg(unix)]
#[test]
fn a_hook_or_a_load_that_fails_says_its_error() {
    let project = vitest_mutants_project("strong-hooks");
    // One worker: the file's baseline copy, listed first, loads first, and
    // the mutant's copies after it. With a worker per processor the two
    // started side by side, and on an arm64 runner the mutant's copy loaded
    // first some of the time: the load meant to fail was the baseline's.
    project.write(
        "vitest.config.js",
        "export default { test: { maxWorkers: 1, setupFiles: [\"./test/setup.js\"] } };\n",
    );
    // Fails where `SETUP_FAILS_COUNTER` names a directory: the first load
    // after the first, or (`always`) every load after the first. Each load
    // takes the next number by creating its file, so that two loads can
    // never both take the same one.
    project.write(
        "test/setup.js",
        "import { closeSync, mkdirSync, openSync } from \"node:fs\";\nconst counter = process.env.SETUP_FAILS_COUNTER;\nif (counter) {\n  mkdirSync(counter, { recursive: true });\n  let count = 0;\n  for (;; count++) {\n    try { closeSync(openSync(`${counter}/${count}`, \"wx\")); break; } catch (error) { if (error.code !== \"EEXIST\") throw error; }\n  }\n  if (count === 1 || (count > 1 && process.env.SETUP_FAILS === \"always\")) throw new Error(\"the test database is gone\");\n}\n",
    );
    project.write(
        "src/schema.js",
        "export const users = { name: \"users\" };\n",
    );
    project.write(
        "src/store.js",
        "const tables = new Map([[\"users\", []]]);\nexport function insert(table, row) {\n  const rows = tables.get(table.name);\n  if (!rows) throw new Error(`relation \"${table.name}\" does not exist`);\n  rows.push(row);\n  return rows.length;\n}\n",
    );
    project.write(
        "test/store.test.js",
        "import { beforeAll, describe, expect, it } from \"vitest\";\nimport { users } from \"../src/schema.js\";\nimport { insert } from \"../src/store.js\";\ndescribe(\"store\", () => {\n  beforeAll(() => {\n    if (process.env.HOOK_FAILS) throw new Error(\"the seed did not load\");\n    insert(users, { id: 1 });\n  });\n  it(\"inserts\", () => expect(insert(users, { id: 2 })).toBe(2));\n});\n",
    );
    project.commit("hooks");
    project.supercov(&["--", "npx", "vitest", "run"]).succeeds();
    let schema = "src/schema.js:1:30-1:37:StringLiteral:empty";
    let counter = project.root.with_extension("counter");
    let counter_path = counter.to_str().unwrap();
    let pass = |env: &[(&str, &str)]| {
        let _ = std::fs::remove_dir_all(&counter);
        let run = project.latest();
        let _ = std::fs::remove_file(
            project
                .root
                .join(format!(".supercov/runs/{run}/strong-mutation.json")),
        );
        let reply = project
            .supercov_with(
                &[
                    "runs",
                    "latest",
                    "mutants",
                    "test",
                    "--file",
                    "src/schema.js",
                    "--json",
                ],
                env,
            )
            .json();
        let listed = project
            .supercov(&[
                "runs",
                "latest",
                "mutants",
                "src/schema.js",
                "--json",
                "--limit",
                "0",
            ])
            .json();
        let mutant = listed["data"]["mutants"]
            .as_array()
            .unwrap()
            .iter()
            .find(|mutant| mutant["id"] == schema)
            .unwrap_or_else(|| panic!("{listed}"))
            .clone();
        (reply, mutant["strong"].clone())
    };
    for stages in ["", "1"] {
        let (_, strong) = pass(&[("SUPERCOV_STRONG_STAGES", stages)]);
        assert_eq!(strong["status"], "killed", "{strong}");
        assert_eq!(
            strong["reason"], "a hook failed: relation \"\" does not exist",
            "{strong}"
        );
        assert_eq!(strong["killedBy"], "test/store.test.js", "{strong}");
    }
    // Fails once: the copy runs again, and the mutant is killed.
    let (reply, strong) = pass(&[("SETUP_FAILS_COUNTER", counter_path)]);
    assert_eq!(strong["status"], "killed", "{strong}");
    assert!(
        reply["passes"][0]["profile"]["unevaluatedReruns"].as_u64() >= Some(1),
        "{reply}"
    );
    // Fails every time: an error with the file's own.
    let (_, strong) = pass(&[
        ("SETUP_FAILS_COUNTER", counter_path),
        ("SETUP_FAILS", "always"),
    ]);
    assert_eq!(strong["status"], "error", "{strong}");
    assert_eq!(
        strong["reason"],
        "its copy of test/store.test.js did not load before the mutant ran, twice: the test database is gone",
        "{strong}"
    );
    // The hook fails without the mutant too: the copy ran none of its tests,
    // and says why.
    let (_, strong) = pass(&[("HOOK_FAILS", "1")]);
    assert_eq!(strong["status"], "error", "{strong}");
    assert_eq!(
        strong["reason"],
        "its copy of test/store.test.js ran none of the tests it was to run: the seed did not load",
        "{strong}"
    );
}

/// A file the command builds only with a tag (`go test -tags tagged`) gets
/// value probes as any other: the type checker is asked with the tag.
#[test]
fn a_go_file_behind_a_build_tag_gets_value_probes() {
    let Some(go) = go() else {
        eprintln!("skipping: no Go toolchain found");
        return;
    };
    let project = Project::empty("go-probes-tagged");
    project.write("go.mod", "module example.com/tagged\n\ngo 1.22\n");
    project.write(
        "double.go",
        "//go:build tagged\n\npackage tagged\n\nfunc Double(n int) int { return n * 2 }\n",
    );
    project.write(
        "double_test.go",
        "//go:build tagged\n\npackage tagged\n\nimport \"testing\"\n\nfunc TestDouble(t *testing.T) {\n\tif Double(3) != 6 {\n\t\tt.Fatal(\"double\")\n\t}\n}\n",
    );
    project
        .supercov_with(
            &["--", go, "test", "-tags", "tagged", "./..."],
            &[("SUPERCOV_MUTANTS", "1")],
        )
        .succeeds();
    let listed = project
        .supercov(&["runs", "latest", "mutants", "--json", "--limit", "0"])
        .json();
    let mutant = &listed["data"]["mutants"][0];
    assert_eq!(
        mutant["id"], "double.go:5:35-5:36:ArithmeticOperator:/",
        "{listed}"
    );
    // `3 * 2` and `3 / 2` differ, and the probe saw it.
    assert_eq!(mutant["status"], "infected", "{listed}");
}

/// Ctrl-C during a Go strong pass, sent to Supercov's process group as a
/// terminal sends it, stops every test binary the pass started and what
/// they started, though each runs in a process group of its own.
#[cfg(unix)]
#[test]
fn an_interrupted_go_pass_leaves_no_process_running() {
    use std::os::unix::process::CommandExt;
    let Some(go) = go() else {
        eprintln!("skipping: no Go toolchain found");
        return;
    };
    let project = Project::empty("go-strong-interrupted");
    project.write("go.mod", "module example.com/slow\n\ngo 1.22\n");
    project.write(
        "slow.go",
        "package slow\n\nfunc Big(n int) bool { return n > 9 }\n",
    );
    // In the strong pass (its binaries are given an active mutant), the
    // test starts a process and waits: its pid and its own go to the marker.
    project.write(
        "slow_test.go",
        "package slow\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"os/exec\"\n\t\"testing\"\n\t\"time\"\n)\n\nfunc TestBig(t *testing.T) {\n\tif !Big(10) {\n\t\tt.Fatal(\"big\")\n\t}\n\tif os.Getenv(\"SUPERCOV_ACTIVE_MUTANT\") == \"\" {\n\t\treturn\n\t}\n\tsleeper := exec.Command(\"sleep\", \"120\")\n\tif err := sleeper.Start(); err != nil {\n\t\tt.Fatal(err)\n\t}\n\tmarker := os.Getenv(\"SUPERCOV_TEST_MARKER\")\n\tos.WriteFile(marker+\".tmp\", []byte(fmt.Sprintf(\"%d %d\", os.Getpid(), sleeper.Process.Pid)), 0o644)\n\tos.Rename(marker+\".tmp\", marker)\n\ttime.Sleep(120 * time.Second)\n}\n",
    );
    let marker = project.root.with_extension("marker");
    let _ = std::fs::remove_file(&marker);
    let mut supercov = project
        .supercov_command(&["mutants", "--", go, "test", "./..."])
        .env("SUPERCOV_TEST_MARKER", &marker)
        .process_group(0)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .unwrap();
    let started = std::time::Instant::now();
    while !marker.exists() {
        assert!(
            started.elapsed() < std::time::Duration::from_secs(240),
            "the strong pass never started its tests"
        );
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
    let pids = std::fs::read_to_string(&marker)
        .unwrap()
        .split_whitespace()
        .map(|pid| pid.parse::<i32>().unwrap())
        .collect::<Vec<_>>();
    // SAFETY: a signal to the process group this test started.
    unsafe { libc::kill(-(supercov.id() as i32), libc::SIGINT) };
    supercov.wait().unwrap();
    let running = |pid: i32| {
        // SAFETY: signal 0 only asks whether the process is there.
        unsafe { libc::kill(pid, 0) == 0 }
    };
    let gone = (0..50).any(|_| {
        std::thread::sleep(std::time::Duration::from_millis(100));
        !pids.iter().any(|pid| running(*pid))
    });
    let _ = std::fs::remove_file(&marker);
    for pid in &pids {
        if running(*pid) {
            // SAFETY: cleaning up a process this test's run left.
            unsafe { libc::kill(*pid, libc::SIGKILL) };
        }
    }
    assert!(gone, "{pids:?} outlived the interrupted pass");
}

/// A mutant `go vet` rejects fails `go test` before any test runs, as one
/// that does not compile does: the strong pass calls it unviable, with
/// vet's finding.
#[cfg(unix)]
#[test]
fn a_go_mutant_vet_rejects_is_unviable() {
    let Some(go) = go() else {
        eprintln!("skipping: no Go toolchain found");
        return;
    };
    let project = Project::empty("go-strong-vet");
    project.write("go.mod", "module example.com/vet\n\ngo 1.22\n");
    project.write(
        "odd.go",
        "package vet\n\nfunc Middle(x int) bool { return x != 1 && x != 2 }\n\nfunc Big(x int) bool { return x > 9 }\n",
    );
    project.write(
        "odd_test.go",
        "package vet\n\nimport \"testing\"\n\nfunc TestMiddle(t *testing.T) {\n\tif !Middle(3) || Middle(1) || !Big(10) {\n\t\tt.Fatal(\"middle\")\n\t}\n}\n",
    );
    let text = project
        .supercov(&["mutants", "--", go, "test", "./..."])
        .succeeds();
    assert!(text.contains("  unviable      1\n"), "{text}");
    let saved = std::fs::read_dir(project.root.join(".supercov/runs"))
        .unwrap()
        .filter_map(|entry| std::fs::read(entry.unwrap().path().join("strong-mutation.json")).ok())
        .next()
        .expect("verdicts saved");
    let saved: serde_json::Value = serde_json::from_slice(&saved).unwrap();
    let verdict = &saved["mutants"]["odd.go:3:41-3:43:LogicalOperator:||"];
    assert_eq!(verdict["status"], "unviable", "{saved}");
    assert!(
        verdict["reason"]
            .as_str()
            .unwrap()
            .ends_with("odd.go:3:34: suspect or: x != 1 || x != 2"),
        "{verdict}"
    );
}
